SELECT 'moj-all-verified-judgments-review-002-chunk-160' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"b4916c7f-9aee-5c42-9d1d-2c94cc69c1fd","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة -عقد مضاربة -مطالبة برأس املال مع األرباح -ادعاء تسليم آلخر مبوافقة رب املال -استخالف محكمة أخرى لسماع الشهود -مين املدعي واملدعى عليه -احلكم بجزء من املبلغ","document_number":"33316144","case_number":"2308","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/25","year":"1434","subject":"شراكة -عقد مضاربة -مطالبة برأس املال مع األرباح -ادعاء تسليم آلخر مبوافقة رب املال -استخالف محكمة أخرى لسماع الشهود -مين املدعي واملدعى عليه -احلكم بجزء من املبلغ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫تاريخه‪1433/6/25 :‬هـ‬\n                     ‫ُ‬                ‫َر ْق ُم َّ‬\n                        ‫الص ِّك‪33316144 :‬‬\n                           ‫َر ْق ُم الدعوى‪2308 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34188358‬تاريخه‪1434/4/15:‬هـ‬\n\n\n    ‫شــراكة ‪ -‬عقــد مضاربــة ‪ -‬مطالبــة بــرأس املــال مــع األربــاح ‪ -‬ادعــاء‬\n    ‫تســليم آلخــر مبوافقــة رب املــال ‪ -‬اســتخالف محكمــة أخــرى لســماع‬\n    ‫الشــهود ‪ -‬ميــن املدعــي واملدعــى عليــه ‪ -‬احلكــم بجــزء مــن املبلــغ‬\n                                                                    ‫املدعــى بــه ‪.‬‬\n\n\n\n    ‫مــا ذكــره القاضــي مــن مبــادئ عامــة وقواعــد العدالــة يف تســبيب‬\n                                                                 ‫حكمــه ‪.‬‬\n\n\n\n    ‫ادعــى املدعــي بقولــه‪ :‬لقــد ســلم مــوكل موكلــي للمدعــى عليــه مائــة‬\n    ‫وخمســة وعشــرين ألــف ريــال يف ‪2006/2/29‬م لكــي يتجــر بهــا‬\n    ‫املدعــى عليــه‪ ،‬وقــد ربــح وبلــغ نصيــب مــوكل موكلــي مــن الربــح مائــة‬\n    ‫وخمســة وعشــرين ألــف ريــال‪ ،‬وقــد ســلم املدعــى عليــه ملــوكل موكلــي‬\n    ‫مــن الربــح عشــرة آالف ريــال‪ .‬لــذا أطلــب إلــزام املدعــى عليــه بــأن يســلم‬\n    ‫ملــوكل موكلــي رأس املــال مــع األربــاح‪ .‬أنكــر املدعــى عليــه مــا قالــه‬\n    ‫املدعــي والصحيــح أن املدعــي أصالــة ســلم مائــة ألــف ريــال لطــرف آخــر‬\n    ‫‪ ،‬لكــي يســلمها لشــخص آخــر لكــي يتجــر بهــا‪ ،‬وبعــد مضــي شــهر‬\n    ‫ذكــر ‪ ......‬أن مبلــغ املدعــي أصالــة ربــح عشــرة آالف ريــال وســلم هــذا‬\n    ‫الربــح ‪ ،.....‬للمدعــي أصالــة‪ ،‬ثــم أعــاد املدعــي أصالــة بعــد عشــرين يومــا‬\n‫‪5‬‬\n\f‫وســلم ‪ ........‬خمســة وعشــرين ألــف ريــال؛ لكــي يتجــر بهــا‪ .‬وأنكــر‬\n‫املدعــي أنــه فــوض املدعــى عليــه بتســليمها لطــرف آخــر وليــس للمدعــى‬\n‫عليــه بينــة علــى ذلــك وطلــب ميــن املدعــي وحلــف علــى ذلــك‪ .‬ومبــا أن‬\n‫املدعــى عليــه أقــر بكتابــة ســند للمدعــي يتضمــن أنــه اســتلم منــه مائــة‬\n‫وخمســة وعشــرين ألــف ريــال وذلــك عــروض جتــارة عامــة ويقــدم املبلــغ‬\n‫لصاحبــه عنــد طلبــه ودفــع بــأن املبلــغ قــد ســلم ‪ ..........‬لكــي ي ّتجــر بــه‬\n‫ـاء علــى موافقــة املدعــي‪ ،‬ومبــا أن املدعــى عليــه أنكــر حصــول ربــح‬         ‫بنـ ً‬\n‫للمبلــغ املذكــور يف الدعــوى وأقــر بــأن العشــرة آالف ريــال التــي ســلمت‬\n‫للمدعــي عبــارة عــن ربــح ملبلــغ ادعــاه ‪ ....‬لــذا فقــد حكمــت احملكمــة‬\n‫علــى املدعــى عليــه بــأن يســلم املدعــي مائــة وخمســة وعشــرين ألــف ريــال‬\n‫وردت دعــوى املدعــي فيمــا زاد علــى ذلــك ‪ ،‬لــم يقنــع املدعــي وال املدعــى‬\n                 ‫عليــه باحلكــم صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ ،‬فلــدي أنــا ‪ .......................‬القاضــي يف‬\n‫احملكمــة العامــة بالريــاض ففــي يــوم األربعــاء املوافــق ‪1431/03/17‬ه ـ‬\n‫حضــر ‪ .................‬حامــل الســجل املدنــي رقــم ‪ .....................‬بالوكالــة‬\n‫عــن ‪ ........................‬بصفتــه الوكيــل الشــرعي عــن ‪ .................‬مبوجــب‬\n‫الوكالــة الصــادرة مــن كاتــب العــدل املكلــف مبكتــب صاحــب‬\n‫الســمو امللكــي وزيــر الدفــاع والطيــران واملفتــش العــام برقــم ‪ 32‬يف‬\n‫‪1431/1/10‬هــ‪ ،‬وادعــى علــى احلاضــر معــه ‪ ........................‬ســوري‬\n‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ .....................‬قائــا يف دعــواه‪:‬‬\n‫لقــد ســلم مــوكل موكلــي للمدعــى عليــه مائــة وخمســة وعشــرين ألــف‬\n\n                                                                                           ‫‪6‬‬\n\f    ‫ريــال يف ‪2006/2/29‬م لكــي يتجــر بهــا املدعــى عليــه‪ ،‬وقــد ربحــت‬\n    ‫وبلــغ نصيــب مــوكل موكلــي مــن الربــح مائــة وخمســة وعشــرين ألــف‬\n    ‫ريــال‪ ،‬وقــد ســلم املدعــى عليــه ملــوكل موكلــي مــن الربــح عشــرة آالف‬\n    ‫ريــال‪ .‬وأطلــب إلــزام املدعــى عليــه بــأن يســلم ملــوكل موكلــي رأس املــال‬\n    ‫مــع األربــاح‪ .‬هــذه دعــواي‪ .‬وباســتجواب املدعــى عليــه‪ ،‬أجــاب بقولــه‪ :‬مــا‬\n    ‫ذكــره املدعــي وكالــة مــن أن مــوكل موكلــه ســلمني مائــة وخمســة‬\n    ‫وعشــرين ألــف ريــال لكــي أجتــر بهــا فغيــر صحيــح‪ ،‬والصحيــح أن‬\n    ‫املدعــي أصالــة ســلم ل‪.......................‬مائــة ألــف ريــال‪ ،‬لكــي يســلمها‬\n    ‫ل‪ ..................‬لكــي يتجــر بهــا‪ ،‬وبعــد مضي شــهر ذكــر ‪...........‬أن مبلغ‬\n    ‫املدعــي أصالــة ربــح عشــرة آالف ريــال وســلم هــذا الربــح ل‪،................‬‬\n    ‫فســلم ‪............‬هــذا الربــح للمدعــي أصالــة‪ ،‬ثــم أعــاد املدعــي أصالــة بعــد‬\n    ‫عشــرين يومــا وســلم ل‪ ...............‬خمســة وعشــرين ألــف ريــال؛ لكــي‬\n    ‫يتجــر بهــا‪ ،‬وقــد كتبــت للمدعــي أصالــة ســندا يف ‪2006/8/29‬م‪،‬‬\n    ‫وقــد جــاء فيــه مــا نصــه‪( :‬نعــم أنــا ‪ ................‬لقــد اســتلمت مــن املدعــو‬\n    ‫‪..................‬مبلغــا قــدره مائــة وخمســة وعشــرين ألــف ريــال ســعودي‬\n    ‫وذلــك عــروض جتــارة عامــة علمــا أن امليزانيــة شــهرية‪ ،‬ويقــدم املبلــغ‬\n    ‫لصاحبــه عنــد طلبــه) ا‪.‬هــ‪ .‬ثــم وقعــت علــى هــذا الســند‪ ،‬وقــد كتبــت‬\n    ‫هــذا الســند باســمي لكــون املدعــي أصالــة لوجــود الثقــة التــي بينــي‬\n    ‫وبــن املدعــي أصالــة‪ ،‬وبعــد مضــي شــهر حضــر لــدي يف ورشــتي‬\n    ‫املدعــي أصالــة و‪ ،......................‬وقــال ‪ ...................‬للمدعــي أصالــة‬\n    ‫إن أموالــي وأمــوال ‪ ..............‬قــد وضعناهــا لــدى املوظــف مبؤسســتي‬\n    ‫‪ ،................‬فهــل تريــد أن أعيــد لــك أموالــك أم تريــد أن أضعهــا عنــد‬\n    ‫‪.............‬لكــي يتجــر بهــا لــك؟ فقــال املدعــي أصالــة يف أول األمــر بــل‬\n\n\n‫‪7‬‬\n\f‫أريــد أن تعيــد لــي أموالــي‪ ،‬ثــم رجــع املدعــي أصالــة قبــل خروجــه مــن‬\n‫الورشــة‪ ،‬وقــال‪ :‬ل‪ ......................‬مــا دام أنــك قــد وضعــت أنــت و‪..............‬‬\n‫أموالكمــا لــدى ‪ .................‬فضــع أموالــي التــي لديــك وقدرهــا مائــة‬\n‫وخمســة وعشــرون ألــف ريــال عنــد ‪ ................‬لكــي يتجــر لــي بهــا وقــد‬\n‫قــام ‪ .................‬بتســليم أمــوال املدعــي أصالــة ل‪ .....................‬ثــم تبــن‬\n‫أن ‪ ........................‬محتــال‪ ،‬وقــد أكل أموالــي وأمــوال ‪.................‬‬\n‫وأمــوال املدعــي أصالــة‪ ،‬وأن األربــاح التــي ســلمها وهميــة‪ ،‬وقــد طالبــه‬\n‫‪..........‬بــرأس املــال الــذي ســلمه لــه‪ ،‬والــذي يخصنــي ويخــص املدعــي‬\n‫أصالــة‪ ،‬ويخــص ‪ ،...................‬وقــد حكــم علــى ‪...............‬بــأن يســلم‬\n‫ل ــ‪ ................‬ثمامنائــة وثالثــن ألــف ريــال‪ ،‬منهــا مائــة وخمســة عشــر‬\n‫ألــف ريــال التــي تخــص املدعــي أصالــة‪ ،‬وذلــك بالصــك الصــادر مــن‬\n‫احملكمــة العامــة بالدمــام برقــم ‪ 5/41‬يف ‪1429/3/3‬هــ‪ ،‬ولــم ينفــذ‬\n‫‪..............‬هــذا احلكــم حتــى اآلن وال يــزال مســجونا مــن أجــل تنفيــذ‬\n‫احلكــم‪ .‬هكــذا أجــاب‪ .‬وبعــرض ذلــك علــى املدعــي وكالــة قــال‪:‬‬\n‫إننــي ســأراجع املدعــي أصالــة وأفيدكــم يف اجللســة القادمــة‪ .‬ويف يــوم‬\n‫األربعــاء املوافــق ‪ 1432/01/02‬ه ـ حضــر ‪ ...............‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ..................‬بالوكالــة عــن ‪...................‬‬\n‫ا عــن‬ ‫حامــل الســجل املدنــي رقــم ‪ ....................................‬بصفتــه وكيـ ً‬\n‫‪ .....................‬ســوري اجلنســية مبوجــب اإلقامــة رقــم ‪ ................‬مبوجــب‬\n‫الوكالــة الصــادرة مــن كاتــب العــدل املكلــف بالعمــل مبكتــب‬\n‫صاحــب الســمو امللكــي وزيــر الدفــاع والطيــران واملفتــش العــام برقــم‬\n‫‪ 491‬يف ‪1431/08/16‬ه ـ كمــا حضــر ‪.....................‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ....................‬بالوكالــة عــن ‪.............‬‬\n\n\n                                                                                              ‫‪8‬‬\n\f    ‫ســوري اجلنســية مبوجــب اإلقامــة رقــم ‪ .......................‬مبوجــب الوكالــة‬\n    ‫الصــادرة مــن كتابــة العــدل الثانيــة بشــرق الريــاض برقــم ‪ 146273‬يف‬\n    ‫‪1431/03/14‬ه ـ فطلبــت مــن املدعــي وكالــة اجلــواب عــن مــا ذكــره‬\n    ‫املدعــى عليــه وكالــة فقــال إن مــا ذكــره مــوكل املدعــى عليــه غيــر‬\n    ‫صحيــح والصحيــح وأن موكلــي اتفــق مــع املدعــى عليــه أصالــة علــى أن‬\n    ‫يســلم مــوكل موكلــي للمدعــى عليــه أصالــة مائــة وخمســة وعشــرين‬\n    ‫ألــف ريــال لكــي يتجــر بهــا املدعــى عليــه أصالــة والربــح بينهمــا فطلــب‬\n    ‫املدعــى عليــه أصالــة مــن موكلــي إيــداع هــذا املبلــغ يف حســاب مؤسســة‬\n    ‫‪.............‬للمقــاوالت يف بنــك ‪ ....‬فــأودع موكلــي املبلــغ يف حســاب‬\n    ‫املؤسســة املذكــورة وكتــب املدعــى عليــه أصالــة الســند الــذي أقــر بــه‬\n    ‫يف اجللســة األولــى ولــم يوافــق موكلــي علــى تســليم شــيء مــن هــذا املبلــغ‬\n    ‫ل‪ .....................‬وأطلــب إلــزام املدعــى عليــه أصالــة بــأن يســلم ملوكلــي‬\n    ‫املتبقــي مــن رأس مالــه وقــدره مائــة وخمســة عشــر ألــف ريــال وأحصــر‬\n    ‫دعــواي يف ذلــك هكــذا أجــاب فســألت املدعــى عليــه وكالــة هــل لــدى‬\n    ‫موكلــه بينــة علــى قبــول املدعــي أصالــة لتســليم املبلــغ املذكــور يف‬\n    ‫الدعــوى ل‪....................‬لإلجتــار بــه فقــال إننــي ســوف أراجــع موكلــي‬\n    ‫وأفيدكــم يف اجللســة القادمــة وموكلــي يســكن يف اخلبــر مــن خمــس‬\n    ‫ســنوات وأطلــب إحالــة املعاملــة للمحكمــة العامــة باخلبــر هكــذا أجــاب‬\n    ‫فأفهمتــه أنــه إن كان لــدى موكلــه بينــة فعليــه إحضارهــا يف اجللســة‬\n    ‫القادمــة وأمــا مــا يتعلــق بالدفــع بعــدم االختصــاص احمللــي فأفهمتــه أن‬\n    ‫هــذا الدفــع ال يقبــل بعــد اجللســة األولــى حســب املــادة احلاديــة والســبعني‬\n    ‫مــن نظــام املرافعــات الشــرعية‪ .‬ويف يــوم الســبت املوافــق ‪1432/5/5‬ه ـ‬\n    ‫حضــر املدعــي أصالــة ‪ ...................‬ســوري اجلنســية مبوجــب اإلقامــة رقم‬\n\n\n‫‪9‬‬\n\f‫‪.....................‬واملدعــى عليــه أصالــة فســألت املدعــى عليــه هــل لديــه بينــة‬\n‫علــى قبــول املدعــي بتســليم املبلــغ املذكــور يف الدعــوى ل‪....................‬‬\n‫لإلجتــار بــه فقــال نعــم فســألته لـ َـم لــم يحضرهــا وقــد أفهمــت وكيلــه‬\n‫بإحضارهــا فقــال إنــه لــم يخبرنــي بذلــك فرفعــت اجللســة إلحضــار البينــة‬\n‫وأفهمتــه أنــه إن أحضرهــا يف اجللســة القادمــة وإال اعتبرتــه عاجــز ًا عــن‬\n                                                                        ‫إحضارهــا‪.‬‬\n‫ويف يــوم الســبت املوافــق ‪1432/8/15‬ه ـ حضــر املدعــي واملدعــى عليــه‬\n‫فســألت املدعــى عليــه هــل أحضــر البينــة التــي وعــد بإحضارهــا ؟‬\n‫فقــال ‪ :‬نعــم وأحضــر ‪ .....................‬ســوري اجلنســية مبوجــب اإلقامــة‬\n‫رقــم ‪ ......................‬وبســؤاله عمــا لديــه قــال أشــهد أنــه قبــل أكثــر مــن‬\n‫ســنة أخبرنــي املدعــي ‪ ..............‬أنــه ســوف يشــغل أموالــه يف شــركة‬\n‫عــن طريــق املدعــى عليــه‪ ................‬وســألني عنــه فقلــت لــه ‪ :‬الرجــال‬\n‫مــا عليــه ثــم أخبرنــي املدعــي بعــد ذلــك أنــه ســلم مبلغــا للمدعــى عليــه‬\n‫هكــذا شــهد ‪ ،‬كمــا أحضــر ‪ ...........‬ســوري اجلنســية مبوجــب اإلقامــة‬\n‫رقــم ‪ .............‬وبســؤاله عمــا لديــه قــال أشــهد أن املبلــغ الــذي ســلمه‬\n‫املدعــي ‪ ..............‬للمدعــى عليه‪...............‬لتســليمه لشــركة ‪ ....‬يف ‪....‬‬\n‫للتجــارة بــه وليــس ليتجــر بــه بنفســه ولــم أحضــر معهمــا عنــد تســليم‬\n‫املبلــغ أو عنــد االتفــاق وقــد علمــت ذلــك ألن املدعــى عليــه يســتلم املبالــغ‬\n‫مــن النــاس لغــرض تســليمها لتلــك الشــركة لإلجتــار بهــا هكــذا شــهد‬\n‫‪ ،‬فســألت املدعــى عليــه هــل لديــه زيــادة بينــة ؟ فقــال ‪ :‬نعــم ووعــد‬\n‫بإحضارهــا يف اجللســة القادمــة ‪ ،‬فأفهمتــه إنــه إن أحضرهــا يف اجللســة‬\n‫القادمــة وإال اعتبرتــه عاجــزا عــن إحضارهــا‪ .‬ويف يــوم األربعــاء املوافــق‬\n‫‪1433/2/10‬ه ـ حضــر املدعــي واملدعــى عليــه فســألت املدعــى عليــه‬\n\n\n                                                                                           ‫‪10‬‬\n\f     ‫هــل أحضــر الشــهود فقــال ‪ :‬إنهمــا يقيمــان يف الدمــام وهمــا ‪...............‬‬\n     ‫و‪ ..............‬ورفضــا احلضــور معــي للريــاض وأطلــب اســتخالف احملكمــة‬\n     ‫العامــة بالدمــام لســماع شــهادتهما لــذا قــررت اســتخالف فضيلــة رئيــس‬\n     ‫احملكمــة العامــة بالدمــام أو مــن ينيبــه مــن قضــاة احملكمــة يف ســماع‬\n     ‫شــهادة الشــاهدين املذكوريــن وشــهادة املزكــن لهمــا ‪ .‬وقــرر املدعــي‬\n     ‫أنــه ال يرغــب احلضــور عنــد أداء الشــهادة ‪ .‬فرفعــت اجللســة لذلك‪ .‬ويف يوم‬\n     ‫األربعــاء املوافــق ‪1433/06/25‬ه ـ حضــر املدعــي واملدعــى عليــه وقــد‬\n     ‫وردنــي خطــاب رئيــس احملكمــة العامــة بالدمــام برقــم ‪ 33/630501‬يف‬\n     ‫‪1433/06/04‬ه ـ واملرفــق بــه صــورة طبــق األصــل مــن الضبــط التالــي‬\n     ‫نصــه‪( :‬اســتخالف يف قضيــة حقوقيــة ـ بطلــب رســمي احلمــد هلل وحــده‬\n     ‫وبعــد فلــدي أنــا ‪ .......................‬القاضــي يف احملكمــة العامــة بالدمــام‬\n     ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n     ‫بالدمــام املســاعد برقــم ‪ 33236227‬وتاريــخ ‪1433/04/04‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 33630501‬وتاريــخ ‪1433/04/04‬ه ـ واملبنيــة علــى‬\n     ‫كتــاب فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم ‪33/307762‬‬\n     ‫وتاريــخ ‪1433/02/16‬ه ـ املتضمــن اســتخالف فضيلــة القاضــي الشــيخ‬\n     ‫‪ ...................‬لنــا يف ســماع بينــة املدعــى عليــه يف الدعــوى التــي أقامهــا‬\n     ‫‪ ................‬ضــده ففــي يــوم األحــد املوافــق ‪1433/05/16‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 47:10‬وفيهــا حضــر ‪ .....................‬ســوري اجلنســية‬\n     ‫مبوجــب اإلقامــة رقــم ‪ ..................‬وأحضــر معــه ‪ ...............‬ســوري‬\n     ‫اجلنســية مبوجــب اإلقامــة رقــم ‪.......................‬و‪ .................‬ســوري‬\n     ‫اجلنســية مبوجــب اإلقامــة رقــم ‪..............‬وقــد شــهد كل واحــد منهمــا‬\n     ‫علــى حــده بقولــه اجتمــع ‪ ............‬مــع ‪ .................‬يف بيتــي أنــا ‪.............‬‬\n\n\n‫‪11‬‬\n\f‫باخلبــر ومعهمــا جماعــة يطلبــون ‪ ..................‬مبالــغ واعتــرف‪.................‬‬\n‫باملبالــغ التــي يطالبونــه بهــا وأنهــا يف ذمتــه والتــزم بســدادها وكتــب‬\n‫لــكل واحــد منهــم ورقــة وســندا باملبلــغ الــذي يف ذمتــه وأعطــى كل‬\n‫دائــن ورقــة باملبلــغ هكــذا شــهدا وأمــرت ببعــث صــورة ضبطــه لفضيلــة‬\n‫القاضــي املســتخلف‪ .‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلى‬\n‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/05/16‬ه ـ املدعــى عليــه ‪..............‬‬\n‫توقيــع شــاهد ‪ ........‬توقيــع شــاهد ‪ ................‬توقيــع كاتــب الضبــط‬\n‫‪ ..............‬توقيــع القاضــي يف احملكمــة العامــة بالدمــام ‪..................‬‬\n‫ختمــه وتوقيعه)اهــ‪ .‬ثــم قــال املدعــي إننــي أعــود إلــى املطالبــة مبــا طالــب‬\n‫بــه وكيلــي يف اجللســة األولــى فســألت املدعــي هــل لديــه بينــة علــى أن‬\n‫املدعــى عليــه قــد ربــح يف املبلــغ الــذي ســلمه إيــاه مائــة وخمــس وعشــرين‬\n‫ألــف ريــال فقــال ال بينــة لــدي علــى ذلــك‪ .‬فأفهمــت املدعــي أن لــه ميــن‬\n‫املدعــى عليــه بالصيغــة التاليــة‪( :‬واهلل الــذي ال إلــه إال هــو إننــي لــم أجتــر‬\n‫باملبلــغ املذكــور يف الدعــوى ولــم أحصــل منــه أي أربــاح عــدا العشــرة‬\n‫آالف ريــال التــي ســلمني إياهــا ‪ ..............‬وســلمتها للمدعــي) فقــال‬\n‫أطلــب ميينــه وبعــرض اليمــن علــى املدعــى عليــه اســتعد ببذلهــا ثــم حلــف‬\n‫اليمــن بالصيغــة املذكــورة آنفــا فأفهمــت املدعــى عليــه أن لــه ميــن‬\n‫املدعــي بالصيغــة التاليــة‪( :‬واهلل الــذي ال إلــه إال هــو إننــي قــد ســلمت‬\n‫مائــة وخمــس وعشــرين ألــف ريــال للمدعــى عليــه ‪ ...........‬لكــي يتجــر‬\n‫بهــا بنفســه ولــم أســلمها لــه لكــي يســلمها ل‪ .................‬لكــي يتجــر‬\n‫بهــا) فقــال أطلــب ميينــه وبعــرض اليمــن علــى املدعــي اســتعد ببذلهــا ثــم‬\n‫حلــف اليمــن بالصيغــة املذكــورة آنفــا فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة ومبــا أن املدعــى عليــه أقــر بكتابــة ســند للمدعــي يتضمــن‬\n\n\n                                                                                          ‫‪12‬‬\n\f     ‫أنــه اســتلم منــه مائــة وخمســة وعشــرين ألــف ريــال وذلــك عــروض جتــارة‬\n     ‫عامــة ويقــدم املبلــغ لصاحبــه عنــد طلبــه ودفــع بــأن املبلــغ قــد ســلم‬\n     ‫ل‪ ................‬لكــي يتجــر بــه بنــاء علــى موافقــة املدعــي وأنكــر املدعــي‬\n     ‫ذلــك ولــم يقــم املدعــى عليــه بينــة علــى موافقــة املدعــي علــى تســليم‬\n     ‫املبلــغ ل‪ .........................‬لكــي يتجــر بــه والشــهود الذيــن أحضرهــم‬\n     ‫املدعــى عليــه لــم يشــهدوا بذلــك وطلــب ميــن املدعــي علــى نفــي ذلــك‬\n     ‫وحلــف املدعــي علــى نحــو مــا طلــب منــه ومبــا أن املدعــى عليــه أنكــر‬\n     ‫حصــول ربــح للمبلــغ املذكــور يف الدعــوى وأقــر بــأن العشــرة آالف‬\n     ‫ريــال التــي ســلمت للمدعــي عبــارة عــن ربــح ملبلغــه ادعــاه ‪..........‬لــذا فقــد‬\n     ‫حكمــت علــى املدعــى عليــه بــأن يســلم املدعــي مائــة وخمســة وعشــرين‬\n     ‫ألــف ريــال ورددت دعــوى املدعــي فيمــا زاد علــى ذلــك وأخليــت ســبيل‬\n     ‫املدعــى عليــه منــه وبذلــك حكمــت‪ .‬وبعــرض احلكــم علــى الطرفــن‬\n     ‫قــررا عــدم القناعــة وطلبــا االســتئناف فأجبتهمــا لطلبهما وقررت تســليم‬\n     ‫كل واحــد منهمــا صــورة مــن صــك احلكــم حــاال لتقــدمي معارضتــه عليــه‬\n     ‫خــال مــدة ال تتجــاوز ثالثــن يومــا فمــن تأخــر منهمــا عــن ذلــك ســقط‬\n     ‫حقــه يف تقــدمي االعتــراض واكتســب احلكــم يف حقــه القطعيــة‪ .‬وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                              ‫حــرر يف ‪1433/06/25‬هــ‪.‬‬\n\n\n     ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34188358‬وتاريــخ‬\n                                                      ‫‪1434/4/15‬هـ‬\n\n\n\n\n‫‪13‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":5,"source_page_end":13,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"988287423af5b11c09cfcdd7d6d15b022461625feb5abc804b955ba370efd564","normalized_text_hash":"797dc21ea44b418f9b55416e469b7e7bcfe4bed2dd0b2a2cb3754deb015c87d4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p5-33316144"},{"id":"ba8d9ee8-34c3-5641-b84f-b52e6614f0c7","document_type":"judgment","category":"judicial","subcategory":"general","title":"شركة -نزاع بن شركاء يف شركة -تظلم من قرار شريك أدى خلسارة الشركة -إقامة الدعوى ضد الغرفة التجارية -دفع املدعى عليها بعدم الصفة وأن مهمتها تقدمي الدعم واملشورة وكونها حاضنة للمشروع ال يلزمها منه حتمل املسؤولية التضامنية -صرف النظر عن دعوى املدعي.","document_number":"3443725","case_number":"2354","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/23","year":"1434","subject":"شركة -نزاع بن شركاء يف شركة -تظلم من قرار شريك أدى خلسارة الشركة -إقامة الدعوى ضد الغرفة التجارية -دفع املدعى عليها بعدم الصفة وأن مهمتها تقدمي الدعم واملشورة وكونها حاضنة للمشروع ال يلزمها منه حتمل املسؤولية التضامنية -صرف النظر عن دعوى املدعي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/2/23 :‬هـ َر ْق ُم‬\n                         ‫ُ‬                ‫َر ْق ُم َّ‬\n                             ‫الص ِّك‪3443725 :‬‬\n                                   ‫الدعوى‪2354 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 34265623‬تاريخه‪1434/7/11:‬هـ‬\n\n\n   ‫شــركة ‪ -‬نــزاع بــن شــركاء يف شــركة ‪ -‬تظلــم مــن قــرار شــريك‬\n   ‫أدى خلســارة الشــركة ‪ -‬إقامــة الدعــوى ضــد الغرفــة التجاريــة ‪ -‬دفــع‬\n   ‫املدعى عليها بعدم الصفة وأن مهمتها تقدمي الدعم واملشــورة وكونها‬\n   ‫حاضنة للمشــروع ال يلزمها منه حتمل املســؤولية التضامنية ‪ -‬صرف‬\n                                                   ‫النظــر عــن دعــوى املدعــي‪.‬‬\n\n\n\n\n   ‫مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة الــواردة يف‬\n                                                                ‫تســبب احلكــم‪.‬‬\n\n\n\n   ‫ادعــى املدعــي بدعــوى ضــد الغرفــة التجاريــة بأنــه اتفــق مــع أحــد رؤســاء‬\n   ‫جلانهــا علــى إنشــاء شــركة ملزاولــة نشــاط جتــاري وبعــد فتــح حســاب‬\n   ‫مصــريف لــه والترويــج واســتقبال املســاهمات مــن النــاس أصــدر قــرارا‬\n   ‫برفــع قيمــة الســهم ممــا حمــل املســاهمني لســحب أموالهــم ممــا أحلــق‬\n   ‫اخلســارة الفادحــة بــه ويطلــب تعويضــه عمــا حصــل لــه مــن ضــرر دفــع‬\n   ‫وكيــل الغرفــة التجاريــة بطلــب صــرف النظــر عــن دعــواه إلقامتــه علــى‬\n   ‫غيــر ذي صفــة فمهمــة الغرفــة التجاريــة تقــدمي االرشــادات واالستشــارات‬\n   ‫وقــرار رئيــس أحــد اللجــان املتظلــم منــه كان بصفتــه الشــخصية ال‬\n   ‫بصفتــه رئيس ـ ًا للجنــة وأن النظــام ال يســمح للغرفــة التجاريــة مبزاولــة‬\n                                                                                       ‫‪14‬‬\n\f     ‫التجــارة وكــون الغرفــة حاضنــة للمشــروع وداعمــة لــه ال يعنــي ضمانهــا‬\n     ‫وال يحملهــا املســؤولية عليــه وملــا اتضــح مــن دعــوى املدعــي أن النــزاع‬\n     ‫الــذي يذكــره نــزاع بــن شــركاء‪ ،‬والغرفــة التجارية ليســت طرف ًا فيه‪،‬‬\n     ‫وليســت شــريكة يف هــذه الشــركة علــى فــرض وجودهــا‪ ،‬وقــد ظهر أن‬\n     ‫القــرار الــذي يدعــى املدعــي تضــرره منــه صــادر مــن رئيــس مجلــس إدارة‬\n     ‫الشــركة املشــار إليهــا‪ ،‬وكــون الغرفــة التجاريــة حتتضــن هذا املشــروع‬\n     ‫وتدعمــه ال يحملهــا مســؤولية إخفاقــه يف حــال تقصيرهــا‪ ،‬لــذا فقــد‬\n     ‫صــدر احلكــم بــرد دعــوى املدعــي جتــاه املدعــى عليــه الغرفــة التجاريــة‬\n     ‫ولــه إقامــة دعــواه ضــد الشــريك لــدى اجلهــة القضائيــة املختصــة قــرر‬\n     ‫املدعــي االعتــراض فأفهــم بالتعليمــات‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                         ‫االســتئناف‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده لــدي أنــا (‪ )......‬القاضــي يف احملكمــة العامــة‬\n     ‫ـاء علــى املعاملــة املقيــدة يف هــذه احملكمــة برقــم‬      ‫باملدينــة املنــورة بنـ ً‬\n     ‫‪ 318588‬وتاريــخ ‪1431/02/10‬ه ـ واحملالــة مــن فضيلــة الرئيــس برقــم‬\n     ‫‪2354‬وتاريــخ ‪1431/02/10‬ه ـ عليــه ففــي هــذا اليــوم الســبت املوافــق‬\n     ‫‪1432/06/25‬ه افتتحــت اجللســة الســاعة ‪11.30‬ص وفيهــا حضــر‬\n     ‫(‪ )......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )......‬ولــم يحضــر‬\n     ‫ممثــل (‪ )......‬وقــد وردنــا خطــاب (‪ )......‬املتضمــن أنــه نظــر ًا النتهــاء مــدة‬\n     ‫مجلــس اإلدارة احلالــي وال تــزال وزارة التجــارة والصناعــة بصــدد اتخــاذ‬\n     ‫إجــراءات انتخــاب مجلــس إدارة جديــد ورفعــت اجللســة ويف جلســة‬\n     ‫أخــرى لــم يحضــر املدعــي وال مــن ميثلــه ولــم يحضــر املدعــى عليــه وال مــن‬\n\n‫‪15‬‬\n\f‫ميثلــه ونظــر ًا النتهــاء الوقــت احملــدد للنظــر يف الدعــوى لــذا فقــد جــرى‬\n‫شــطبها للمــرة األولــى ويف جلســة أخــرى كان املدعــي قــد تقــدم بطلــب‬\n‫مواصلــة النظــر يف دعــواه فتــم قبــول طلبــه ومت حتديــد هــذا اليــوم موعــد ًا‬\n‫لنظــر الدعــوى وقــد حضــر املدعــي ولــم يحضــر ممثــل للمدعــى عليهــا‬\n‫(‪ )......‬وقــد وردنــا منهــم خطــاب رقــم ق‪ 258/‬وتاريــخ ‪1433/01/24‬ه ـ‬\n‫يتضمــن أنــه لــم يصلهــم قــرار اعتمــاد رئيــس مجلــس (‪ )......‬إال منــذ‬\n‫أيــام قليلــة ويطلبــون تأجيــل اجللســة وعليــه رفعــت اجللســة ويف جلســة‬\n‫أخــرى حضــر املدعــي وحضــر حلضــوره (‪ )......‬ســعودي اجلنســية مبوجــب‬\n‫الهويــة الوطنيــة ذات الرقــم (‪ )......‬بصفتــه الوكيــل الشــرعي عــن اجلهــة‬\n‫املدعــى عليهــا مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الثانيــة‬\n‫باملدينــة املنــورة برقــم ‪ 7293‬وتاريــخ ‪1433/01/29‬ه ـ وقــد قــرر املدعــي‬\n‫قائ ـاً‪ :‬أطلــب إمهالــي إلحضــار دعــواي محــررة فأجيــب لطلبــه ورفعــت‬\n‫اجللســة ويف جلســة أخــرى حضــر املدعــي وحضــر حلضــوره املدعــى عليــه‬\n‫وكالــة ثــم ابــرز املدعــي الئحــة دعــوى مكونــة مــن ســبع صفحــات‬\n‫تقــرر االطــاع عليهــا ورصــد مضمونهــا يف اجللســة القادمــة ومت تزويــد‬\n‫املدعــى عليــه وكالــة بنســخة منهــا للجــواب عليهــا يف اجللســة القادمــة‬\n‫ورفعــت اجللســة ويف جلســة أخــرى حضــر الطرفــان وقــد أحضــر املدعــى‬\n‫عليــه وكالــة مذكــرة جوابيــة علــى الدعــوى ونظــر ًا ألن مذكرتــي‬\n‫الدعــوى واإلجابــة طويلتــان فقــد طلــب مــن الطرفــن إحضارهمــا عــن‬\n‫طريــق وســائط إلكترونيــة لكــي يتــم تنزيلهــا يف الضبــط فاســتعدا‬\n‫لذلــك ورفعــت اجللســة ويف جلســة أخــرى حضــر املدعــي وحضــر حلضــوره‬\n‫(‪ )......‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪ )......‬بصفتــه‬\n‫ممثـ ًـا (‪ )......‬مبوجــب خطــاب التفويــض ذي الرقــم ق‪ 1791/‬وتاريــخ‬\n\n\n                                                                                      ‫‪16‬‬\n\f     ‫‪1433/9/9‬ه ـ الصــادر مــن رئيــس مجلــس إدارة (‪ )......‬والتــي تخــول لــه‬\n     ‫حــق املرافعــة واملدافعــة واملخاصمــة واملطالبــة وحضــور اجللســات والــرد‬\n     ‫عليهــا وســماعها واإلقــرار واإلنــكار واجلــرح والتعديــل والطعــن وقبــول‬\n     ‫األحــكام مــن عدمهــا واملطالبــة باحلقــوق وإثباتهــا وطلــب حلــف اليمــن‬\n     ‫ورده واالســتئناف والتمييــز وقــد قــرر الطرفــان قائلــن‪ :‬نطلــب تأجيــل‬\n     ‫ـاع للصلــح فأجيبــا لطلبهمــا ورفعــت اجللســة ويف‬        ‫اجللســة لوجــود مسـ ٍ‬\n     ‫جلســة أخــرى حضــر املدعــي وحضــر حلضــوره (‪ )......‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم (‪ )......‬بصفتــه الوكيــل الشــرعي عــن‬\n     ‫اجلهــة املدعــى عليهــا مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n     ‫الثانيــة باملدينــة املنــورة برقــم ‪ 343368‬وتاريــخ ‪1434/1/3‬ه والتــي‬\n     ‫تخــول لــه فيهــا حــق املطالبــة وإقامــة الدعــاوي واملرافعــة واملدافعــة‬\n     ‫وســماع الدعــاوي والــرد عليهــا وطلــب حلــف اليمــن ورده واالمتنــاع عنــه‬\n     ‫واحضــار الشــهود والبينــات والطعــن فيهــا واالجابــة وبســؤال املدعــي عــن‬\n     ‫ا إننــي أملــك مؤسســة جتاريــة باســم (‪ )......‬واملســجلة‬   ‫دعــواه ادعــى قائـ ً‬\n     ‫يف وزارة التجــارة مبوجــب الســجل التجــاري ذي الرقــم (‪ )......‬وتاريــخ‬\n     ‫‪1428/08/05‬هـ ـ تعمــل هــذه املؤسســة يف نشــاط تأهيــل وتدريــب‬\n     ‫وتوظيــف الكــوادر النســائية يف منطقــة (‪ )...‬ومنطقــة (‪ )...‬ثــم مت االتفاق‬\n     ‫مــع رئيــس جلنــة شــباب األعمــال يف الغرفــة التجاريــة بــ‪ ......‬املدعــى عليهــا‬\n     ‫مبوجــب مذكــرة تفاهــم وتتضمــن تأســيس شــركة (‪ )......‬كشــركة‬\n     ‫مســاهمة تطــرح لالكتتــاب ثــم مت فتــح حســاب بإســمي وباســم املديــر‬\n     ‫املالــي (‪ )......‬يف بنــك (‪ )......‬وبــدأ األعضــاء واملؤسســون بإيــداع املبالــغ‬\n     ‫وكان الســهم حينهــا لألعضــاء املؤسســن خمســة وثالثــون ألــف ريــال‬\n     ‫ثــم أتخــذ رئيــس جلنــة شــباب األعمــال املعــن رئيس ـ ًا ملجلــس إدارة هــذه‬\n\n\n‫‪17‬‬\n\f‫الشــركة قــرار ًا برفــع الســهم مــن خمســة وثالثــن ألــف ريــال إلــى مائــة‬\n‫ألــف ريــال فســحب املؤسســون مــا دفعــوه ثــم مت إجهــاض املشــروع مــن‬\n‫قبــل رئيــس مجلــس اإلدارة بعــد الترويــج لــه إعالميـ ًا وقــد تضــررت مــن‬\n‫ذلــك حيــث إننــي بذلــت جهــدي وانتقلــت مــع مؤسســتي وأســرتي كاملــة‬\n‫مــن منطقــة تبــوك واجلــوف إلــى املدينــة املنــورة وأعــددت دراســة جــدوى‬\n‫للمشــروع كلفتنــي مائــة وســتني ألــف ريــال لــذا أطلــب تعويضــي عــن‬\n‫ذلــك مببلــغ قــدره أربعمائــة وخمســون ألــف ريــال علم ـ ًا أننــي شــريك يف‬\n‫هــذه الشــركة واملديــر التنفيــذي للشــركة بنــاء علــى قــرار مجلــس‬\n‫إدارة الشــركة علمـ ًا أن رئيــس مجلــس اإلدارة مت تعيينــه مبوجــب قــرار‬\n‫مجلــس إدارة الشــركة والغرفــة التجاريــة ليســت شــريكه يف هــذه‬\n‫الشــركة هــذه دعــواي وبعــرض دعــوى املدعــي علــى املدعــى عليــه‬\n‫ا إن الغرفــة التجاريــة مهمتهــا تقــدمي‬‫ممثــل الغرفــة التجاريــة أجــاب قائـ ً‬\n‫اخلدمــات االرشــادية واالستشــارات املتعلقــة بالتجــار والصناعــة وتهيئــة‬\n‫األجــواء لغــرض االســتثمار وقــد تقــدم املدعــي إلــى الغرفــة مبشــروعه‬\n‫الــذي يذكــر وســاهمت الغرفــة يف تقــدمي االرشــادات وكان شــريك ًا‬\n‫لرئيــس جلنــة شــباب األعمــال يف الغرفــة حســب مــا ذكــر وذلــك بصفتــه‬\n‫الشــخصية فتــم عقــد جلنــة بينهــم لتأســيس شــركة تقــوم بالنشــاط الــذي‬\n‫ذكــره ولــم تظهــر الشــركة للوجــود ومهمــة الغرفــة هــي املســاعدة‬\n‫يحمــل‬‫واالشــراف وكونهــم فشــلوا يف االتفــاق فيمــا بينهــم فهــذا ال ّ‬\n‫الغرفــة أي مســؤولية والغرفــة التجاريــة ليســت شــريكه يف املشــروع‬\n‫وال يحــق لهــا نظام ـ ًا ذلــك لــذا فــإن الغرفــة التجاريــة موكلتــي ليســت‬\n‫مســؤولة عــن االضــرار التــي حلقــت بــه هكــذا أجــاب فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واالجابــة ومــا قــرره الطرفــان ونظــر ًا ألنــه اتضــح مــن‬\n\n\n                                                                                      ‫‪18‬‬\n\f     ‫دعــوى املدعــي أن النــزاع الــذي يذكــره هــو نــزاع بــن شــركاء والغرفــة‬\n     ‫التجاريــة ليســت طرف ـ ًا فيــه وليســت شــريكه يف هــذه الشــركة علــى‬\n     ‫فــرض وجودهــا وقــد ظهــر أن القــرار الــذي يدعــى املدعــي تضــرره منــه‬\n     ‫صــادر مــن رئيــس مجلــس إدارة الشــركة املشــار إليهــا وكــون الغرفــة‬\n     ‫التجاريــة حتتضــن هــذا املشــروع وتدعمــه ال يحملهــا مســؤولية اخفاقــه‬\n     ‫يف حــال تقصيرهــا لــذا فقــد حكمــت بــرد دعــوى املدعــي (‪ )......‬املشــار‬\n     ‫إليهــا جتــاه املدعــى عليــه (‪ )......‬وبعــرض احلكــم علــى الطرفــن قــرر‬\n     ‫ممثــل (‪ )......‬قناعتــه باحلكــم أمــا املدعــي فأبــدى عــدم القناعــة وطلــب‬\n     ‫اســتئناف احلكــم بالئحــة فتــم إفهامــه بالتعليمــات املتعلقــة بهــذا الشــأن‬\n     ‫وأن عليــه احلضــور خــال عشــرة أيــام الســتالم صــورة مــن صــك احلكــم‬\n     ‫لالعتــراض عليــه خــال ثالثــن يوم ـ ًا مبضيهــا وعــدم تقــدم اعتراضــه‬\n     ‫يســقط حقــه يف االعتــراض ويكتســب احلكــم القطعيــة‪ ،‬علم ـ ًا أن‬\n     ‫اجللســة املقــررة يف يــوم األحــد املوافــق ‪1433/11/21‬هـ ـ لــم تنعقــد‬\n     ‫اللتحاقــي يف دورة تدريبــة تابعــة لــوزارة العــدل وأغلقــت اجللســة الســاعة‬\n     ‫العاشــرة ‪ ،‬وبــاهلل التوفيــق ‪ ،‬حــرر يف ‪1434/02/20‬ه ـ وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬احلمــد هلل وحــده وبعــد ففــي‬\n     ‫هــذا اليــوم األحــد املوافــق ‪1434/6/18‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫الثانيــة عشــرة والربــع وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n     ‫بخطابهــم رقــم ‪ 341107169‬وتاريــخ ‪1434/5/28‬ه ـ مرفق ـ ًا بهــا قــرار‬\n     ‫املالحظــة رقــم ‪ 34216615‬وتاريــخ ‪1434/5/20‬ه ـ املتضمــن بعــد‬\n     ‫حــذف املقدمــة مــا نصــه» وبدراســة احلكــم وصــورة ضبطــه والئحتــه‬\n     ‫االعتراضيــة تقــرر باألكثريــة إعادتهــا لفضيلتــه ملالحظــة مــا يلــي ‪:‬‬\n     ‫‪ -1‬الدعــوى غيــر محــررة وال بــد مــن حتريرهــا قبــل ضبطهــا علم ـ ًا أن‬\n\n\n‫‪19‬‬\n\f‫فضيلتــه أشــار إلــى أن الدعــوى قــد قدمهــا املدعــي وكذلــك اإلجابــة‬\n‫عنهــا عــن طريــق وســائط الكترونيــة ليتــم تنزليهــا يف الضبــط لكــن‬\n‫فضيلتــه لــم يقــم بذلــك ويعمــل املــادة (‪ )62‬مــن نظــام املرافعــات الشــرعية‬\n‫ولوائحــه التنفيذيــة ‪ -2‬علــى فضيلتــه بعــد حتريــر الدعــوى التأكــد مــن‬\n‫أن القضيــة داخلــة يف اختصاصــه الوالئــي ‪ -3‬االطــاع علــى العقــد‬\n‫بــن الطرفــن وتدويــن مضمونــه يف الضبــط وإجــراء الــازم نحــوه ‪-4‬‬\n‫االطــاع علــى الالئحــة االعتراضيــة ومناقشــة مــا ورد فيهــا بحضــور‬\n‫الطرفــن ال ســيما مــا ذكــره املعتــرض مــن أن لديــه مســتندات رســمية‬\n‫تثبــت صحــة دعــواه وإجــراء املقتضــى الشــرعي نحوهــا ‪ ،‬واهلل املوفــق‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم» أ‪.‬ه ـ وعليــه‬\n‫أجيــب أصحــاب الفضيلــة قضــاة محكمــة االســتئناف حفظهــم اهلل‬\n‫مبــا يلــي ‪ :‬أوالً‪ :‬الدعــوى محــررة وهــي شــفوية ‪ ،‬وكان قــد طلــب مــن‬\n‫الطرفــن إحضارهــا عبــر وســائط الكترونيــة لطولهمــا ‪ ،‬وقــد طلــب‬\n‫ـاء‬\n‫الطرفــان يف اجللســة الثامنــة ســماع الدعــوى واإلجابــة مشــافهة وبنـ ً‬\n‫عليــه مت رصــد الدعــوى واإلجابــة يف اجللســة الثامنــة‪ .‬ثاني ـاً‪ :‬ظهــر لــي‬\n‫أن هــذه الدعــوى مــن اختصــاص احملكمــة العامــة نظــر ًا ألن املدعــى‬\n‫عليهــا ليســت جهــة حكوميــة وإمنــا هــي يف احلقيقــة جمعيــة للتجــار ‪،‬‬\n‫ـاء عليــه فليســت الدعــوى‬   ‫كمــا أن املدعــى عليهــا ليســت شــريكه وبنـ ً‬\n‫بــن شــركاء ‪ .‬ثالثـاً‪ :‬اتضــح مــن دعــوى املدعــي أن االتفــاق مت بينــه وبــن‬\n‫رئيــس جلنــة شــباب األعمــال بالغرفــة ( الشــريك لــه ورئيــس مجلــس إدارة‬\n‫ـاء عليــه‬\n        ‫الشــركة) وأن الغرفــة ليســت شــريكة يف هــذه الشــركة وبنـ ً‬\n‫فــإن هــذه الدعــوى ال تتوجــه علــى املدعــى عليهــا واحلقيقــة أنــه خــاف‬\n‫بــن الشــركاء ومــن ضمنهــم رئيــس مجلــس إدارة الشــركة ويســتطيع‬\n\n\n                                                                                     ‫‪20‬‬\n\f     ‫ـاء‬\n      ‫رفــع دعــواه عليــه إذا كان لــه حــق أمــام احملكمــة املختصــة‪ ،‬وبنـ ً‬\n     ‫عليــه فــا زلــت علــى حكمــي واهلل أعلــم وأحكــم هــذا مــا أجيــب‬\n     ‫بــه أصحــاب الفضيلــة وأمــرت بإحلاقــه ورفعــه حملكمــة االســتئناف ‪،‬‬\n     ‫وأغلقــت اجللســة الســاعة الثانيــة عشــرة والنصــف ‪ ،‬وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/06/18‬ه ـ‬\n     ‫ويف هــذا اليــوم الثالثــاء املوافــق ‪1434/8/16‬ه ـ افتتحــت اجللســة لــدي‬\n     ‫أنــا (‪ )......‬القائــم بعمــل املكتــب القضائــي التاســع عشــر وقــد عــادت‬\n     ‫املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة بخطابهــم رقــم‬\n     ‫‪ 341107169‬وتاريــخ ‪1434/7/19‬ه ـ مرفقـ ًا بــه قــرار الدائــرة احلقوقيــة‬\n     ‫الثانيــة رقــم ‪ 34265623‬وتاريــخ ‪1434/7/11‬ه ـ املظهــر علــى الصــك‬\n     ‫املتضمــن املوافقــة علــى احلكــم لــذا جــرى إحلاقــه بضبطــه وســجله‬\n     ‫وبــاهلل التوفيــق حــرر يف ‪1434/8/16‬ه ـ وصلــى اهلل وســلم علــى نبينــا‬\n                                                   ‫محمــد وعلــى آلــه وصحبــه وســلم‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n     ‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n     ‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن‬\n     ‫فضيلــة رئيــس احملكمــة باملدينــة املنــورة برقــم ‪ 341107169‬وتاريــخ‬\n     ‫‪1434/6/19‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ (‪)......‬‬\n     ‫القاضــي باحملكمــة العامــة باملدينــة املنــورة برقــم ‪ 3443725‬وتاريــخ‬\n     ‫‪1434/2/23‬هـ ‪ ،‬املتضمن دعوى (‪ )......‬ضد (‪ ، )......‬وبدراســة الصك‬\n     ‫وصــورة ضبطــه والئحتــه اإلعتراضيــة تقــرر املوافقــة علــى احلكــم بعــد‬\n     ‫األجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                                                                ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n‫‪21‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":14,"source_page_end":21,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ba984b1c4d2a24f883b855d93101be4a16b092b06c5e5eb65bb0e62bdcbff7b2","normalized_text_hash":"a75b29464337ce7701cb43c14276446110a6aa0c0f2b7f8a3012e66212a598a3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p14-3443725"},{"id":"84a71e57-7466-5784-968c-a84ae12d6de9","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة -عقد -مضاربة -تسليم أموال للمدعى عليها لغرض املتاجرة -ثبوت احتيال املدعى عليها -مطالبة املدعي برد رأس املال واألرباح -مصادقة املدعى عليها على رأس املال دون األرباح- دفع املدعى عليها باملتاجرة واخلسارة وال بينة على اخلسارة -إلزام املدعى عليها برد رأس املال للمدعي .","document_number":"34188973","case_number":"3250477","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبكة املكرمة بقرارها","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/15","year":"1434","subject":"شراكة -عقد -مضاربة -تسليم أموال للمدعى عليها لغرض املتاجرة -ثبوت احتيال املدعى عليها -مطالبة املدعي برد رأس املال واألرباح -مصادقة املدعى عليها على رأس املال دون األرباح- دفع املدعى عليها باملتاجرة واخلسارة وال بينة على اخلسارة -إلزام املدعى عليها برد رأس املال للمدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/15 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34188973 :‬‬\n                    ‫َر ْق ُم الدعوى‪3250477 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34232389‬تاريخه‪1434/6/6 :‬هـ‬\n\n\n‫شــراكة ‪ -‬عقــد ‪ -‬مضاربــة ‪ -‬تســليم أمــوال للمدعــى عليهــا لغــرض‬\n‫املتاجــرة ‪ -‬ثبــوت احتيــال املدعــى عليهــا‪ -‬مطالبــة املدعــي بــرد رأس‬\n‫املــال واألربــاح‪ -‬مصادقــة املدعــى عليهــا علــى رأس املــال دون األربــاح‪-‬‬\n‫دفــع املدعــى عليهــا باملتاجــرة واخلســارة وال بينــة علــى اخلســارة‪ -‬إلــزام‬\n                                  ‫املدعــى عليهــا بــرد رأس املــال للمدعــي ‪.‬‬\n\n\n\n         ‫قوله صلى اهلل عليه وسلم ‪ ( :‬على اليد ما أخذت حتى تؤديه )‬\n\n\n\n\n‫ذكــر وكيــل املدعــي شــرح ًا لدعــواه أن موكلــه قــام بتســليم مبلــغ‬\n‫للمدعــى عليهــا لغــرض املتاجــرة فيــه وســلمته إيصــا ًال بذلــك يتضمــن‬\n‫أنهــا مرابحــة يف األســهم‪ ،‬تبــن للمدعــي أن املدعــى عليهــا قــد حكــم‬\n‫عليهــا يف قضيــة احتيــال لقيامهــا بجمــع األمــوال والنصــب واالحتيــال‬\n‫علــى النــاس لذلــك طلــب إلــزام املدعــى عليها بــرد املبلغ املســلم واألرباح‪،‬‬\n‫صادقــت املدعــى عليهــا علــى دعــوى املدعــي فيمــا يتعلــق باملبلــغ املســلم‬\n‫لهــا والثابــت مبوجــب شــيك دون غيــره ألنهــا تاجــرت وخســرت مــن جتــارة‬\n‫األســهم وال بينــة لهــا علــى اخلســارة‪ ،‬لــذا حكمــت احملكمــة بإلــزام‬\n‫املدعــى عليهــا بــرد املبلــغ للمدعــي‪ ،‬قــرر املدعــي القناعــة وقــررت‬\n\n                                                                                    ‫‪22‬‬\n\f     ‫املدعــى عليهــا االعتــراض علــى احلكــم بالئحــة اعتراضيــة‪ -‬متــت‬\n                             ‫مصادقــة احلكــم مــن محكمــة اإلســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا‪ ........‬القاضــي باحملكمــة اجلزائيــة‬\n     ‫باملدينــة القاضــي اخللــف لفضيلــة القاضــي الشــيخ مبوجــب قــرار‬\n     ‫النقــل رقــم (‪ )33/18/2085‬يف ‪1433/4/17‬ه ـ الصــادر مــن املجلــس‬\n     ‫األعلــى للقضــاء ‪ ،‬وقــد عــادت املعاملــة مــن احملكمــة العليــا برقــم‬\n     ‫‪ 34169721‬وتاريــخ ‪1434/1/25‬ه ـ رفقهــا القــرار رقــم ‪/400‬ش‬\n     ‫وتاريــخ ‪1434/1/25‬ه ـ املتضمــن اإلذن باســتمرار ســماع الدعــوى بعــد‬\n     ‫شــطبها للمــرة الثانيــة وتنبيــه املدعــي بعــدم تكــرار غيابــه ورصــد ذلــك‬\n     ‫يف ضبــط القضيــة‪ .‬ويف يــوم االثنــن املوافــق ‪1434/3/23‬ه ـ افتتحــت‬\n     ‫اجللســة يف متــام الســاعة احلاديــة عشــر صباحــا وفيهــا حضــر ســعودي‬\n     ‫اجلنســية بالســجل املدنــي رقــم (‪ )........‬الوكيــل الشــرعي عــن املدعــي‬\n     ‫‪ ........ /‬مبوجــب الوكالــة رقــم ‪ 45909‬يف ‪1431/7/23‬ه ـ اجللــد ‪6440‬‬\n     ‫الصــادرة مــن كتابــة عــدل املدينــة املنــورة الثانيــة وجــرى تنبيهــه بعــدم‬\n     ‫تكــرار غيابــه وحضــر حلضــوره املدعــى عليهــا ســعودية بالســجل املدنــي‬\n     ‫رقــم وادعــى وكيــل املدعــي قائــا إن ملوكلــي يف ذمــة احلاضــرة معــي‬\n     ‫يف املجلــس الشــرعي مبلــغ وقــدرة مليــون وخمســة وثمانــون الــف ريــال‬\n     ‫ســلمها للمدعــى عليهــا لغــرض املتاجــرة فيهــا وقــد اســتلمت املدعــى‬\n     ‫عليهــا املبلــغ وســلمتنا إيصــاال يتضمــن أنهــا مرابحــة يف األســهم تــرد‬\n     ‫بعــد طلبهــا بشــهر واحــد ‪ ،‬اإليصــال األول بســند قبــض برقــم ‪4591‬‬\n     ‫مببلــغ خمســة عشــر الــف ريــال وإيصــاال آخــر يتضمــن أنهــا قــرض‬\n\n‫‪23‬‬\n\f‫حســن ورده عنــد الطلــب بســند قبــض برقــم ‪ 5456‬مببلــغ ثمامنائــة الــف‬\n‫ريــال ويوجــد شــيك برقــم ‪ 152‬بتاريــخ ‪1429/7/17‬ه ـ املســحوب‬\n‫علــى البنــك االهلــي التجــاري مببلــغ مئتــان وثمانــن الــف وجميعهــا‬\n‫بتوقيــع املدعــى عليهــا ومكتوبــة بخــط يدهــا ثــم تبــن لنــا بعــد ذلــك‬\n‫أنهــا قامــت بجمــع األمــوال والنصــب واالحتيــال علــى النــاس وقــد صــدر‬\n‫حكــم قضائــي علــى املدعــى عليهــا مــن قبــل فضيلــة القاضــي الشــيخ‬\n‫للحــق العــام يف قضيــة احتيالهــا مــن خــال جمعهــا أمــوال النــاس بغــرض‬\n‫توظيفهــا بالقــرار الشــرعي رقــم ‪ 8/69‬يف ‪ 1432/5/14‬واملؤيــد مــن‬\n‫محكمــة االســتئناف مبكــة املكرمــة بقرارهــا رقــم ‪ 2/2/300‬املــؤرخ‬\n‫يف ‪1432/4/28‬ه ـ يف مبالــغ ماليــة هــذا وقــد طلــب موكلــي مــن املدعــى‬\n‫املســلم لهــا لكنهــا امتنعــت والمتناعهــا عــن الدفــع أطلب‬    ‫عليهــا رد املبلــغ َ‬\n‫احلكــم عليهــا بدفــع مــا بذمتهــا ملوكلــي وهــو مبلــغ وقــدره مليــون‬\n‫وخمســة وثمانــون ألــف ريــال هــذه دعــواي وبســؤال املدعــى عليهــا عــن‬\n‫دعــوى املدعــي وكالــة أجابــت املدعــى عليهــا بقولهــا مــا ذكــره املدعــي‬\n‫وكالــة مــن اســتالمي مــن موكلــه املبلــغ الــذي ذكــر غيــر صحيــح‬\n‫والصحيــح أننــي تاجــرت مببلــغ مالــي ســلمه لــي وال أذكــر مقــداره يف‬\n‫جتــارة تــداول األســهم وخســرت وال بينــة لــي علــى ذلــك أطلــب إحضــار‬\n‫املدعــي أصالــة إليضــاح مبلغــه الــذي ســلمه لــي و أمــا بالنســبة للســندات‬\n‫والشــيك املرصــود أرقامهــا بدعــوى املدعــي وكالــة فهــي بخــط يــدي وال‬\n‫أنكرهــا ولكنــي خســرت يف جتــارة األســهم وال بينــة لــي علــى اخلســارة‬\n‫هكــذا أجابــت عليــه فقــد قــررت رفــع اجللســة إلحضــار املدعــي أصالــة‬\n‫ويف جلســة أخرى افتتحت يف يوم األحد املوافق ‪1434/4/14‬هـ يف متام‬\n‫الســاعة الثانيــة ظهــر ًا بنــاء علــى قــرار وزيــر العــدل املوافقــة علــى العمــل‬\n\n\n                                                                                          ‫‪24‬‬\n\f     ‫خــارج وقــت الــدوام الرســمي برقــم (‪ )2982‬وتاريــخ ‪1434/2/18‬ه ـ‬\n     ‫وفيهــا حضــر املدعــي أصالــة ســعودي اجلنســية مبوجــب هويــة وطنيــة‬\n     ‫رقــم (‪ )........‬وحضــر حلضــوره املدعــى عليهــا ســعودية مبوجــب هويــة‬\n     ‫وطنيــة رقــم (‪ )........‬وبســؤال املدعــي أصالــة عــن إيضــاح للمبلــغ املســلم‬\n     ‫للمدعــى عليهــا حقيقــة فأجــاب بقولــه املبلــغ املســلم للمدعــى عليهــا هــو‬\n     ‫املبلــغ املرصــود بالشــيك املشــار إليــه يف اجللســة الســابقة التــي حضرهــا‬\n     ‫وكيلــي الشــرعي وهــو مبلــغ مائتــان وثمانــون ألــف ريــال فقــط وأما باقي‬\n     ‫املبلــغ املرصــود بســندات القبــض والــذي قــدره ثمامنائــة وخمســة عشــر‬\n     ‫ألــف ريــال فهــو وعــد مــن املدعــى عليهــا كأربــاح للمبلــغ املســلم لهــا‬\n     ‫والــذي قدره ـ مائتــان وثمانــون ألــف ريــال وتكــون مــن نصيبــي هكــذا‬\n     ‫أجــاب وبعــرض ذلــك علــى املدعــى عليهــا قالــت مــا ذكــره املدعــي مــن‬\n     ‫أننــي ســلمته الشــيك املشــار إليــه بالدعــوى واملرصــود فيــه مبلــغ مائتــان‬\n     ‫وثمانــون ألــف ريــال فهــذا صحيــح ولكننــي ســلمته لــه مقابــل حفــظ‬\n     ‫حقــه يف املســاهمة باملبلــغ احلقيقــي الــذي ســلمه لــي وال اذكــره مقــداره‬\n     ‫حاليــا فهــذا الشــيك يحتــوي مبلــغ املســاهمة الــذي ســلمه لــي للمتاجرة به‬\n     ‫ومبلــغ األربــاح التــي كنــت ســأعطيها لــه لــو ربحــت بالتجــارة ولكننــي‬\n     ‫خســرت وال بينــة لــي علــى اخلســارة هكــذا أجابــت لــذا وبنــاء علــى مــا‬\n     ‫تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــي أصالــة أنــه لــم يســلم‬\n     ‫املدعــى عليهــا ســوى مبلــغ مائتــان وثمانــون ألــف ريــال مبوجــب الشــيك‬\n     ‫املشــار إليــه بالدعــوى وحيــث صادقــت املدعــى عليهــا علــى صــدور‬\n     ‫هــذا الشــيك مــن قبلهــا إال أنهــا ادعــت اخلســارة وال بينــة لهــا علــى ذلــك‬\n     ‫وباالطــاع علــى الصــك املشــار إليــه رقــم ‪ 8/69‬وتاريــخ ‪1431/5/14‬ه ـ‬\n     ‫واملصــدق مــن محكمــة االســتئناف مبكــة املكرمــة واملتضمــن إثبــات‬\n\n\n‫‪25‬‬\n\f‫ناظــر القضيــة إدانــة املدعــى عليهــا باالحتيــال علــى بعــض املواطنــن مــن‬\n‫خــال توظيــف أموالهــم لتداولهــا بســوق األســهم ودفــع عمــوالت وأربــاح‬\n‫وهميــة لهــم حلملهــم علــى إيــداع أموالهــم لديهــا بــدون ترخيــص والتســبب‬\n‫يف ضياعهــا وتبديدهــا بــدون وجــه حــق ‪ ،‬فنظــر َا إلــى مــا دون ونظــر َا‬\n‫ملصادقــة املدعــى عليهــا علــى اســتالمها للمبلــغ املدعــى بــه مــن املدعيــة‬\n‫أصالــة لقصــد املتاجــرة ولعــدم وجــود بينــة لهــا علــى مــا دفعــت بــه مــن‬\n‫اخلســارة ونظــرا ملــا جــاء يف القــرار الشــرعي رقــم ‪ 8/69‬واملؤيــد مــن‬\n‫محكمــة االســتئناف بثبــوت إدانتهــا بالنصــب واالحتيــال وخروجهــا‬\n‫عــن قصــد املتاجــرة وهــذا يجعلهــا ضامنــة للمبلــغ ولقــول النبــي صلــى‬\n‫اهلل عليــه وســلم ( علــى اليــد مــا أخــذت حتــى تؤديــه ) وعليــه فقــد‬\n‫حكمــت علــى املدعــى عليهــا بدفــع مبلــغ مائتــن وثمانــن ألــف ريــال‬\n‫للمدعــي وبعــرض احلكــم علــى طــريف الدعــوى قــرر املدعــي القناعــة‬\n‫باحلكــم وقــررت املدعــى عليهــا عــدم القناعــة باحلكــم واســتعدت‬\n‫بتقــدمي الئحــة اعتراضيــة فأفهمتهــا باملــدة النظاميــة وان عليهــا تقــدمي‬\n‫الالئحــة االعتراضيــة خــال ثالثــن يومــا مــن تاريــخ اســتالمها لصــورة‬\n‫مــن صــك احلكــم وإال فيعتبــر احلكــم مكتســب القطعيــة ففهمــت ذلــك‬\n‫واســتعدت بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                               ‫وصحبــه أجمعــن ‪ .‬حــرر يف ‪1434/04/14‬هــ‪.‬‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪:‬ـ فقــد‬\n‫جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 32877919‬وتاريــخ‬\n‫‪1434/05/22‬ه ـ املرفــق بهــا الصــك الصادر من فضيلة الشــيخ القاضي‬\n\n\n                                                                                    ‫‪26‬‬\n\f     ‫باحملكمــة اجلزائيــة باملدينــة املنــورة املســجل برقــم ‪ 34188973‬وتاريــخ‬\n     ‫‪1434/04/15‬ه ـ املتضمــن دعــوى ضــد ‪ ،‬وبدراســة الصــك وص ــورة‬\n     ‫ضبطـه والئحته االعتراضية تقـررت املوافقـة علـى احلكم واهلل املوفق‪.‬‬\n                    ‫وصلـى اهلل علـى نبينا محمد وعلـى آلـه وصحبـه وسلم ‪.‬‬\n\n\n\n\n‫‪27‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":22,"source_page_end":27,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"75589ed67c4712ab76bcd23d75148ff908fa487cc0951d0be690786d89c187ca","normalized_text_hash":"b98b4c2667be0d8d56a6aab5cce479b3ebe63b3d9daafd15c3cf4fe4eaf7a788","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p22-34188973"},{"id":"4fd2442c-632d-5295-89e7-1d19f3e00f69","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة يف فتح مطعم -حوالة -املطالبة برأس املال مع األرباح -إذا صحت احلوالة برئ احمليل من الدين سواء أمكن استيفاء احلق أو تعذر-اعتماد الترجمة يف الترافع حال كون أحد االطراف أجنبي ا -احلكم بصرف النظر عن دعوى املدعي.","document_number":"3427257","case_number":"3313727","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/2","year":"1434","subject":"شراكة يف فتح مطعم -حوالة -املطالبة برأس املال مع األرباح -إذا صحت احلوالة برئ احمليل من الدين سواء أمكن استيفاء احلق أو تعذر-اعتماد الترجمة يف الترافع حال كون أحد االطراف أجنبي ا -احلكم بصرف النظر عن دعوى املدعي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/2/2 :‬هـ َر ْق ُم‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪3427257 :‬‬\n                              ‫الدعوى‪3313727 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 34564058‬تاريخه‪1434/3/7:‬هـ‬\n\n\n ‫شــراكة يف فتــح مطعــم ‪ -‬حوالــة ‪ -‬املطالبــة بــرأس املــال مــع األربــاح‬\n ‫‪ -‬إذا صحــت احلوالــة بــرئ احمليــل مــن الديــن ســواء أمكــن اســتيفاء‬\n ‫احلــق أو تعذر‪-‬اعتمــاد الترجمــة يف الترافــع حــال كــون أحــد االطــراف‬\n                       ‫أجنبي ـ ًا ‪ -‬احلكــم بصــرف النظــر عــن دعــوى املدعــي‪.‬‬\n\n\n\n\n ‫‪ -1‬قــال ابــن قدامــه رحمــه اهلل ‪ ( :‬وإذا صحــت احلوالــة بــرئ احمليــل مــن‬\n ‫الديــن ألنــه قــد حتــول مــن ذمتــه فــإن تعــذر االيفــاء مــن احملــال عليــه‬\n ‫ملــوت أو فلــس حــادث أو مطــل لــم يرجــع علــى احمليــل كمــا لــو أبــرأه )‪.‬‬\n                                                         ‫الكافــى(‪.)346-345/2‬‬\n ‫‪ -2‬قــال صاحــب الــروض املربــع (‪ ( : )120-119/5‬وإذا صحــت احلوالــة‬\n ‫نقلــت احلــق إلــى ذمــة احملــال عليــه وبــرئ احمليــل مبجــرد احلوالــة فــا‬\n ‫ميلــك الرجــوع علــى احمليــل بحــال ‪.‬قــال صاحــب احلاشــية ‪ :‬ألن احلــق‬\n ‫انتقــل بذلــك فلــم يعــد احلــق إلــى احمليــل أبــدا ‪ .‬ثــم جــاء يف الــروض‬\n ‫أيض ـ ًا ‪ :‬ســواء أمكــن اســتيفاء احلــق أو تعــذر ملطــل أو فلــس أو مــوت أو‬\n                                                                         ‫غيرهــا ‪).‬‬\n\n\n\n\n                                                                                      ‫‪28‬‬\n\f     ‫ادعــى مقيــم علــى مقيــم آخــر بأنــه ســلم للمدعــى عليــه خمســة وعشــرين‬\n     ‫الــف ريــال بنــاء علــى طلــب املدعــى عليــه مــن أجــل افتتــاح مطعــم ‪ ،‬بعــد‬\n     ‫اســتالم املدعــى عليــه املبلــغ اســتأجر مطعمــا بتاريــخ ‪1431/6/14‬ه ـ‬\n     ‫وأبرمــا عقــدا لتلــك الشــراكة متتــد الــى تاريــخ ‪1433/1/14‬ه ـ ‪ ،‬يف‬\n                                               ‫شــهر رمضــان مــن عــام ‪1432‬ه ـ ‪.‬‬\n     ‫لــم يقــم املدعــى عليــه بدفــع أي ربــح وأخبــر املدعــي أنــه اذا رغــب يف‬\n     ‫اخلــروج مــن تلــك الشــراكة فســوف يعيــد لــه رأس املــال الــذي دفعــه‬\n     ‫باإلضافــة الــى اربــاح قدرهــا اثنــان وعشــرون ألفــا وخمســمائة وثمانيــة‬\n     ‫وعشــرون ريــاال باإلضافــة إلــى مبلــغ قــدره خمســة وعشــرون ألــف ريــال‬\n     ‫نصيــب املدعــى مــن تقديــر املطعــم عنــد تقبيلــه مببلــغ مائتــن وعشــرين‬\n     ‫ألــف ريــال ‪ ،‬كان أقصــى موعــد لتســليم هــذه املبالــغ ‪1432/9/15‬هــ‪،‬‬\n     ‫عنــد حلــول األجــل حــول املدعــى عليــه املدعــي علــى شــخص آخــر‬\n     ‫لكونــه مــن قــام بتقبيــل املطعــم ‪ .‬قابــل املدعــى احملــال عليــه يف أحــد‬\n     ‫املســاجد بتاريــخ ‪1432/9/15‬ه ـ فطلــب هــذا الشــخص (احملــال عليــه)‬\n     ‫مــن املدعــي اثبــات مالــه يف ذمــة املدعــى عليــه ‪ ،‬أبــرز املدعــى ســندا‬\n     ‫بذلــك ‪ .‬قــام احملــال عليــه بتمزيــق هــذا الســند ‪ ، .‬ماطــل احملــال عليــه‬\n     ‫املدعــى يف الســداد ثــم أخبــره أنــه ســيعطيه خمســن ألــف ريــال بعــد‬\n     ‫حــج عــام ‪1433‬ه ـ ‪ ،‬بعــد احلــج ذهــب املدعــي للمحــال عليــه فطلــب منــه‬\n     ‫كتابــة اقــرار باســتالمه ملبلــغ خمســن الــف ريــال والباقــي وقــدره اثنــان‬\n     ‫وعشــرون ألف ـ ًا وخمســمائة وثمانيــة وعشــرون ريــا ًال ســيدفعها احملــال‬\n     ‫عليــه الحق ـ ًا ‪ .‬كتــب املدعــى اقــرار ًا باســتالمه اخلمســن ألــف ريــال‬\n\n‫‪29‬‬\n\f‫وســلم احملــال عليــه للمدعــى شــيكا بخمســة وثالثــن ألــف ريــال فقــط‬\n‫‪ .‬عنــد طلــب صــرف هــذه الشــيك تبــن أنــه بغيــر رصيــد ‪ .‬وكل املدعــي‬\n‫أحــد األشــخاص ملطالبــة احملــال عليــه وســلم املدعــى الشــيك لوكيلــه‬\n‫‪ .‬ذهــب وكيــل املدعــي للمحــال عليــه فاخــذ احملــال عليــه الشــيك وقــام‬\n‫بتقطيعــه وســلم لوكيــل املدعــي قيمتــه خمســة وثالثــن الــف ريــال‬\n‫وهــى اآلن بحــوزة والــد الوكيــل الشــرعي للمدعــي ‪ .‬طلــب املدعــي‬\n‫احلكــم علــى املدعــى عليــه بدفــع املبلــغ كامــا وقــدره اثنــان وســبعون‬\n‫ألف ـ ًا وخمســمائة وثمانيــة وعشــرون ريــا ًال صــادق املدعــى عليــه علــى‬\n‫الشــراكة وأنــه اســتلم مــن املدعــي خمســة وعشــرين الــف ريــا ًال كمــا‬\n‫صــادق املدعــى عليــه علــى أربــاح املدعــي البالــغ قدرهــا اثنــان وعشــرون‬\n‫الفــا وخمســمائة وثمانيــة وعشــرون ريــا ًال دفــع املدعــى عليــه بــأن املدعــي‬\n‫طلــب منــه أن يضيــف لــه علــى رأس املــال واألربــاح مبلغــا قــدره خمســة‬\n‫وعشــرون الــف ريــال مــن قيمــة تقبيــل املطعــم وأن املدعــى عليــه وافــق‬\n‫علــى ذلــك رغــم أن املدعــي ال يســتحقها ‪ .‬قــرر املدعــى عليــه بأنــه ســلم‬\n‫خمســن الــف ريــال للمحــال عليــه مــن أجــل أن يســلمها للمدعــى ‪ .‬قــرر‬\n‫املدعــي بأنــه ذهــب مــع املدعــى عليــه للمحــال عليــه يف احــدى ليالــى شــهر‬\n‫رمضــان عــام ‪1432‬ه ـ وأن احملــال عليــه أعطــى للمدعــى خمســة وثالثــن‬\n‫الــف ريــال مبوجــب شــيك ســأل املدعــى عليــه احملــال عليــه عــن ذلــك‬\n‫فأخبــره احملــال عليــه بأنــه توجــد هنــاك حســابات بينــه وبــن املدعــي‬\n‫وقــرر املدعــى عليــه أنــه ال يعلــم تفاصيــل هــذه احلســابات ‪ .‬ملــا قــرره أهــل‬\n‫العلــم مــن أنــه اذا صحــت احلوالــة بــرئ احمليــل مــن الديــن ســواء أمكــن‬\n‫اســتيفاء احلــق أم تعــذر لــذا صــدر احلكــم بصــرف النظــر عــن دعــوى‬\n‫املدعــى جتــاه املدعــى عليــه ‪ .‬اعتــرض املدعــي علــى احلكــم ‪ .‬صــدق‬\n\n\n                                                                                        ‫‪30‬‬\n\f                                            ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة مبكــة‬\n     ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة مبكــة املكرمــة برقــم ‪ 3313727‬وتاريــخ ‪ 1433/01/04‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 3334336‬وتاريــخ ‪ 1433/01/04‬ه ـ املتعلقــة‬\n     ‫بدعــوى ‪...‬ضــد ‪...‬ففــي هــذا اليــوم الثالثــاء املوافــق ‪1433/04/27‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 11 : 00‬وفيهــا حضــر ‪...‬باكســتاني‬\n     ‫اجلنســية مبوجــب االقامــة رقــم ‪...‬وحضــر حلضــوره املدعــى عليــه املدعــو‬\n     ‫‪...‬باكســتاني اجلنســية مبوجــب االقامــة رقــم ‪...‬ثــم ســألت املدعــي‬\n     ‫عــن دعــواه فأدعــى بواســطة مترجــم احملكمــة ‪...‬قائــا لقــد أعطيــت‬\n     ‫هــذا املدعــى عليــه مبلغــا مــن املــال قــدره خمســة وعشــرين الــف ريــال‬\n     ‫حيــث طلــب منــي ذلــك ألجــل افتتــاح مطعــم يقــع يف حــي ‪ ...‬فمــا كان‬\n     ‫مــن املدعــى عليــه بعــد أن ســلمته ذلــك املبلــغ إال أن أســتأجر مطعمــا‬\n     ‫بتاريــخ ‪1431/6/14‬ه ـ وأبرمنــا عقــدا لتلــك الشــراكة متتــد إلــى تاريــخ‬\n     ‫‪1433/1/14‬ه ـ وقبــل نهايــة عقــد الشــراكة وبالتحديــد قبــل شــهر‬\n     ‫رمضــان مــن عــام ‪1432‬ه ـ لــم يقــم هــذا املدعــى عليــه بدفــع أي ربــح لــي‬\n     ‫منهــا وأخبرنــي بأنــي إن رغبــت يف اخلــروج مــن تلــك الشــراكة فســوف‬\n     ‫يعيــد لــي رأس مالــي الــذي دفعتــه لــه باالضافــة إلــى أربــاح حــدد لــي‬\n     ‫قدرهــا وهــي أثنــان و عشــرون الفـ ًا و خمســمائة و ثمانيــة و عشــرون ريــال‬\n     ‫هــذا إضافــة إلــى موافقتــه علــى أن يدفــع لــي مبلــغ خمســة وعشــرين ألــف‬\n     ‫ريــال والتــي تعــد نصيبــي بعــد أن مت تقديــر املطعــم عنــد تقبيلــه مببلــغ‬\n\n‫‪31‬‬\n\f‫مائتــن وعشــرين ألــف ريــال وكان أقصــي موعــد وعدنــي بتســليمي‬\n‫املــال الــذي يخصنــي هــو يف ‪1432/9/15‬ه ـ فلمــا أتــى موعــد التســليم‬\n‫طالبتــه بــه ولكنــه أحالنــي علــى شــخص يدعــى ‪...‬كــي أتقاضــى حقــي‬\n‫منــه وحــدد لــي مكانــة فســألته عــن ســبب ذلــك فأخبرنــي بأنــه مــن‬\n‫تقبــل املطعــم وبإمكانــي أن آخــذ مالــي منــه فتوجهــت ل‪ ...‬هــذا وقابلتــه‬\n‫يف أحــد املســاجد بتاريــخ ‪1432/9/15‬ه ـ بعــد األفطــار فطلــب منــي أن‬\n‫اثبــت لــه إن كان لــي بالفعــل حــق علــي هــذا املدعــى عليــه فأبــرزت‬\n‫ســندا يثبــت حقــي فلمــا قــام بأخــذه منــي مزقــة أمــام عينــي فتغيظــت مــن‬\n‫صنيعــه ذلــك لكنــه قــال ســأعطيك حقــك الحقــا فأخــذ يف مماطلتــي‬\n‫الــى أن قــال يف وقــت آخــر بأنــه ســيعطيني خمســن ألــف ريــال بعــد حــج‬\n‫عــام ‪1433‬ه ـ فلمــا ذهبــت إليــه يف ذلــك الوقــت طلــب منــي أن أكتــب‬\n‫لــه إقــرار ًا باســتالمي ملبلــغ خمســن ألــف ريــال والباقــي وقــدره أثنــان و‬\n‫عشــرون ألف ريال و خمســمائة وثمانية و عشــرون رياال ســيعطيني إياها‬\n‫يف وقــت آخــر فأخــذ منــي إقــرار ًا بذلك وأعطاني شــيك ًا مصرفي ًا مببلغ‬\n‫خمســة و ثالثــن ألــف ريــال فقــط فلمــا اســتلمته توجهــت لســحب مبلغــه‬\n‫فوجدتــه بغيــر رصيــد وبعــد ذلــك وكلــت أحــد األشــخاص الســعوديني‬\n‫للمرافعــة واملدافعــة وأعطيتــه ذلــك الشــيك فلمــا توجــه بــه إلــى ‪ ...‬الــذي‬\n‫ذكرتــه أخــذ ‪ ...‬الشــيك وقــام بتقطيعــه وســلم للوكيــل الشــرعي قيمتــه‬\n‫البالغــة خمســة و ثالثــن ألــف ريــال وهــي اآلن بحــوزة والــد الوكيــل‬\n‫الشــرعي لــم أســتلمها حتــى اآلن لــذا فإنــي أطلــب احلكــم علــى هــذا‬\n‫احلاضــر بدفــع املبلــغ الكامــل وقــدره اثنــن وســبعني ألــف وخمســمائة‬\n‫وثمانيــة وعشــرين ريــال هــذه دعــواي وأســأله اجلــواب وبعــرض ذلــك علــى‬\n‫ا إن بعــض مــا جــاء‬  ‫املدعــى عليــه أجــاب بواســطة املترجــم املذكــور قائـ ً‬\n\n\n                                                                                     ‫‪32‬‬\n\f     ‫يف دعــوى املدعــي صحيــح وبعضــه غيــر صحيــح فمــا ورد يف دعــواه مــن‬\n     ‫تســليمي مبلــغ خمســة وعشــرين ألــف ريــال ألجــل الشــراكة يف افتتــاح‬\n     ‫مطعــم فصحيــح وال أنكــره يف ذلــك حيــث افتتحــت مطعم ـ ًا واســتمر‬\n     ‫يف العمــل قرابــة ســنة وشــهرين وفــق مــا ذكــره ثــم أراد كفيلــي تقبيلــه‬\n     ‫فعرضــت ذلــك علــى املدعــي وأخبرتــه إن كان يرغــب هــو يف تقبلــه‬\n     ‫فرفــض ذلــك بحجــة قلــة خبرتــه يف ذلــك املجــال فطلــب منــي إعطــاءه‬\n     ‫رأس املــال الــذي دفعــه واملكاســب فوعدتــه بإعطائــه إياهــا حيــث‬\n     ‫ظهــر بــأن مكاســبه بلغــت اثنــن وعشــرين ألــف وخمســمائة وثمانيــة‬\n     ‫وعشــرين ريــا ًال غيــر أنــه طلــب منــي قســر ًا أن أضيــف لــه علــى رأس‬\n     ‫املــال واألربــاح مبلــغ خمســة وعشــرين ألــف ريــال مــن قيمــة تقبيــل املطعــم‬\n     ‫فوافقــت علــى ذلــك علــى الرغــم مــن أنــه ال يســتحقها ثــم ســلمت مبلــغ‬\n     ‫خمســن ألــف ريــال للمدعــو‪... /‬كــي يســلمه لهــذا املدعــي وقــد ذهبــت‬\n     ‫مــع املدعــي يف إحــدى ليالــي شــهر رمضــان عــام ‪1432‬ه ـ إلــى ‪...‬الــذي‬\n     ‫ذكرتــه ولكنــه أعطــاه خمســة وثالثــن ألــف ريــال مبوجــب شــيك ثــم‬\n     ‫ســألت ‪ ...‬عــن ذلــك فأخبرنــي بــأن هنــاك حســابات بينــه وبــن املدعــي ال‬\n     ‫أعلــم تفاصيلهــا هكــذا قــال ويف يــوم الســبت ‪1434/01/17‬ه ـ افتتحت‬\n     ‫اجللســة وفيهــا حضراملتداعيــان وبعــد دراســة مــا تقــدم وإلقــرار املدعــي‬\n     ‫بــأن املدعــى عليــه أحالــه علــى الشــخص الــذي أســماه ‪...‬كــي يتقاضــا‬\n     ‫حقــه منــه ولتوجهــه إليــه وإبــرازه ســند ًا يثبــت حقــه وملــا قالــه أهــل العلــم‬\n     ‫يف هــذا الشــأن حيــث قــال ابــن قدامــه رحمــه اهلل يف الــكايف «وإذا‬\n     ‫صحــت احلوالــة بــرئ احمليــل مــن الديــن ألنــه قــد حتــول مــن ذمتــه فــإن‬\n     ‫تعــذر اإليفــاء مــن احملــال عليــه ملــوت أو فلــس حــادث أو مطــل لــم يرجــع‬\n     ‫علــى احمليــل كمــا لــو أبــرأه» ‪ 346 - 345/2‬وقــال صاحــب الــروض‬\n\n\n‫‪33‬‬\n\f‫املربــع «وإذا صحــت احلوالــة نقلــت احلــق إلــى ذمــة احملــال عليــه وبــرئ‬\n‫احمليــل مبجــرد احلوالــة فــا ميلــك الرجــوع علــى احمليــل بحــال» قــال‬\n‫صاحــب احلاشــية «ألن احلــق إنتقــل بذلــك فلــم يعــد احلــق إلــى احمليــل‬\n‫أبــداً» ثــم جــاء يف الــروض أيض ـ ًا «ســواء أمكــن إســتيفاء احلــق أو تعــذر‬\n‫ملطــل أو فلــس أو مــوت أو غيرهــا» ‪ 120 - 119/5‬بنــاء علــى ذلــك فقــد‬\n‫صرفــت النظــر عــن دعــوى املدعــي ‪ ...‬وأخليــت ســبيل املدعــى عليــه‬\n‫‪...‬ومبــا تقــدم حكمــت وبعرضــه علــى لســان مترجــم احملكمــة ‪...‬قــرر‬\n‫املدعــي اعتراضــه عليــه بينمــا قنــع املدعــى عليــه فجــرى إفهــام املدعــي‬\n‫مبراجعــة احملكمــة خــال عشــرة أيــام الســتالم نســخة احلكــم لتقــدمي‬\n‫اعتراضــه عليــه خــال ثالثــن يوم ـ ًا فــإن لــم يفعــل خاللهــا فــإن حقــه‬\n‫يف االعتــراض يســقط ويكتســب احلكــم القطعيــة فقــرر ذلــك علــى‬\n‫لســان املترجــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                          ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/17‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ثــم عــادت أوراق املعاملــة من محكمة االســتئناف‬\n‫باخلطــاب رقــم ‪ 34515559‬يف ‪1434/3/18‬ه ـ رفقهــا الصــك الشــرعي‬\n‫رقــم ‪ 3427257‬يف ‪1434/2/2‬ه ـ مظهــر ًا عليــه بقــرار الدائــرة احلقوقيــة‬\n‫السادســة مبحكمــة االســتئناف رقــم ‪ 3456405‬يف ‪1434/3/7‬ه ـ‬\n‫املتضمــن أنــه بدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة‬\n‫تقــررت املوافقــة علــى احلكــم قاضــي اســتئناف ختــم وتوقيــع‪ /...‬رئيــس‬\n‫اســتئناف ختــم وتوقيــع ‪ /.../‬رئيــس الدائــرة ختــم وتوقيــع ‪... /‬وصــل اهلل‬\n   ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/4/17‬ه ـ‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ فق ــد ج ــرى‬\n‫م ّنــا نح ــن رئيــس واعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n\n\n                                                                                    ‫‪34‬‬\n\f     ‫االستئناف مبنطقة مك ــة املكرم ــة االطال ُع عل ــى هذا احلكم الصادر‬\n     ‫مــن فضيلــة الشــيخ ‪... /‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‬\n     ‫واملســجل بع ــدد ‪ 3427257‬وتاريــخ ‪1434/2/2‬ه ـ املتضمــن دعــوى ‪...‬‬\n     ‫باكســتاني اجلنســية ضــد ‪ ...‬باكســتاني اجلنســية ‪ ،‬احملكــوم في ــه مبــا‬\n     ‫دون باطنــه ‪ ،‬وبدراس ــة احلكــم وص ــورة ضبط ــه و الئحتــه االعتراضيــة‬\n     ‫تق ــررت املوافق ــة عل ــى احلكــم ‪ ،‬واهلل املوفــق وصل ــى اهلل عل ــى نبينــا‬\n                                               ‫محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪35‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":28,"source_page_end":35,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"130d1f391b2d736ca92782cfbc95a68218986d156c6052aa4abd762f2ec4133c","normalized_text_hash":"af7879563b87747e15fcb86845a20d7be5495f35e84adccaeebcaae352c5996c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p28-3427257"},{"id":"62d3f48b-6e34-531c-a530-e6dd184b94c7","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة -عقد مضاربة -مطالبة بكامل رأس املال -عدم إعفاء رب املال للمضارب -ال يحق تصرف الشريك يف مال شريكه من غير علمه -احلكم بالباقي من رأس املال .","document_number":"34167017","case_number":"3341856","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/21","year":"1434","subject":"شراكة -عقد مضاربة -مطالبة بكامل رأس املال -عدم إعفاء رب املال للمضارب -ال يحق تصرف الشريك يف مال شريكه من غير علمه -احلكم بالباقي من رأس املال .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/3/21 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34167017 :‬‬\n                    ‫َر ْق ُم الدعوى‪3341856 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34343932‬تاريخه‪1434/10/28:‬ه‬\n\n\n‫شــراكة ‪ -‬عقــد مضاربــة ‪ -‬مطالبــة بكامــل رأس املــال ‪ -‬عــدم إعفــاء رب‬\n‫املــال للمضــارب ‪ -‬ال يحــق تصــرف الشــريك يف مــال شــريكه مــن غيــر‬\n                                  ‫علمــه ‪ -‬احلكــم بالباقــي مــن رأس املــال ‪.‬‬\n\n\n\n\n‫‪ -1‬قــال ابــن قدامــة يف املغنــي « وليــس لــه أن يشــارك مبــال الشــركة‬\n‫وال يدفعــه مضاربــة ألن ذلــك يثبــت يف املــال حقوقــا ويســتحق ربحــه‬\n                                                ‫لغيــره وليــس لــه ذلــك» ‪.‬‬\n‫‪ -2‬جــاء يف قــرار مجمــع الفقــه اإلســامي الدولــي رقــم (‪ )123‬مــا نصــه‬\n‫[ املضــارب أمــن وال يضمــن مــا يقــع مــن خســارة أو تلــف إال بالتعــدي‬\n                                                              ‫والتقصيــر ] ‪.‬‬\n\n\n\n\n‫دعــوى املدعــي يف كونــه ســلم ملــوكل املدعــى عليــه مبلغــا وقــدره مئتــان‬\n‫وثمانــون ألــف ريــال علــى أن يتاجــر لــه يف البرســيم ويكــون مــن املدعــي‬\n‫املــال ومــن املدعــى عليــه العمــل ولــم يســلمه شــيئا مــن رأس املــال وال‬\n‫األربــاح يطلــب إلزامــه بتســليمه كامــل رأس املــال وقــدره مئتــان وثمانون‬\n‫ألــف ريــال ‪..‬ثــم قصــر دعــواه يف مبلــغ وقــدره مائــة وثمانيــة وتســعون ألــف‬\n‫ريــال‪ ،‬أجــاب املدعــى عليــه بــأن مــا ذكــره املدعــي صحيــح ولكننــي‬\n\n                                                                                      ‫‪36‬‬\n\f               ‫ســلمت مــوكل املدعــي مبلغــا وقــدره اثنــان وثمانــون ألــف ريــال‪.‬‬\n     ‫وقــد ســلمت جميــع املبلــغ لطــرف آخــر وأخبــرت موكلــه بذلــك وأعفانــي‬\n     ‫مــن الباقــي وقــال ســأطالب الطــرف اآلخــر‪ ،‬حضــر املدعــي أصالــة‬\n     ‫وأنكــر إعفــاؤه مــن املبلــغ وأنــه لــم يفوضــه يف تســليم املبلــغ ألي طــرف‬\n     ‫آخــر وبســؤال املدعــى عليــه ألديــك بينــة علــى االعفــاء قــال ال ‪ ،‬قــررت‬\n     ‫احملكمــة إلــزام املدعــى عليــه بســداد مبلــغ وقــدره مائة وثمانية وتســعون‬\n     ‫ألــف ريــال ‪ ،‬اعتــرض املدعــى عليــه علــى احلكــم ‪ ،‬قــررت محكمــة‬\n     ‫االســتئناف إعــادة الدعــوى لتحليــف املدعــي اليمــن بعــدم اإلعفــاء مــن‬\n            ‫املبلــغ‪ ،‬حلــف املدعــي صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......................‬القاضــي يف احملكمــة‬\n     ‫العامــة بتبــوك وبنــاء علــى املعاملــة احملالــة ملكتبنــا مــن فضيلــة‬\n     ‫رئيــس احملكمــة العامــة بتبــوك املكلــف برقــم ‪ 3340556‬وتاريــخ‬\n     ‫‪1433/01/16‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33102542‬وتاريــخ‬\n     ‫‪1433/01/16‬ه ـ ففــي ي ــوم األربع ــاء امل ــوافق ‪1434/01/14‬ه ـ افتتحت‬\n     ‫اجل ـلـس ــة الساعـ ــة ‪ 10 : 30‬وفيهــا حضــر ‪ .....................‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪ ...................‬بصفتــه وكيال عــن ‪..............‬‬\n     ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..................‬مبوجــب‬\n     ‫الوكالــة الصــادرة مــن كتابــة العــدل يف اخلــرج برقــم ‪310508020274‬‬\n     ‫يف ‪1431/6/18‬ه ـ كمــا حضــر ‪ .............‬ســعودي اجلنســية مبوجــب‬\n     ‫السجل املدني رقم ‪ .............‬وادعى األول يف عام ‪1428‬هـ سلم موكلي‬\n     ‫لهــذا احلاضــر مبلغــا وقــدره مئتــان وثمانــون ألــف ريــال علــى أن يتاجــر‬\n\n‫‪37‬‬\n\f‫لــه يف البرســيم ويكــون مــن موكلــي املــال ومــن املدعــى عليــه العمــل‬\n‫وحتــى هــذه الســاعة لــم يســلم موكلــي شــيئا مــن رأس املــال وال األربــاح‬\n‫شــيئا أطلــب إلزامــه بتســليم موكلــي كامــل رأس املــال وقــدره مئتــان‬\n‫وثمانــون ألــف ريــال هــذه دعــواي وبعــرض الدعــوى علــى املدعــي عليــه‬\n‫أجــاب بقولــه مــا ذكــره املدعــي وكالــة صحيــح كلــه جملــة وتفصيــا‬\n‫إال مــا ذكــره مــن أنــي لــم أســلم موكلــه شــيئا مــن رأس املــال فغيــر‬\n‫صحيــح فقــد ســلمته مبلغــا وقــدره اثنــان وثمانــون ألــف ريــال وذلــك أننــي‬\n‫ســلمت كامــل املبلــغ املدعــى بــه لشــخص يدعــى ‪ ..............‬ثــم طلــب منــي‬\n‫املدعــي أصالــة مبلغــا وقــدره اثنــان وثمانــون ألــف فأخذتهــا مــن ‪..............‬‬\n‫وأعطيتهــا املدعــي أصالــة وعليــه يكــون املتبقــي لــه يف ذمتــي قــدره مائــة‬\n‫وثمانيــة وتســعون الــف ريــال ومــع ذلــك فقــد أخبــرت املدعــي أصالــة بــأن‬\n‫املائــة وثمانيــة وتســعني ألــف ريــال مــع ‪ .............‬وملــا ذكــرت لــه ذلــك‬\n‫أعفانــي حينهــا مــن املطالبــة وقــال ســوف أطالــب ‪ ................‬هكــذا‬\n‫أجــاب وبعرضــه علــى املدعــي وكالــة قــال مــا ذكــره املدعــى عليــه‬\n‫مــن أنــه ســلم املبلــغ ل‪ ...............‬فــا علــم لــي بــه وليــس لــي بذلــك أي‬\n‫عالقــة وموكلــي لــم يعــف املدعــى عليــه مــن املطالبــة وأطلــب إمهالــي‬\n‫للرجــوع إلــى موكلــي الســتيضاح األمــر ويف جلســة أخــرى حضر املدعي‬\n‫أصالــة ‪ .......................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ .....................‬كمــا حضــر املدعــي عليــه وبعــرض مــا مت رصــده بعاليــه‬\n‫علــى املدعــي أصالــة قــال مــا ذكــره املدعــى عليــه مــن أنــي اســتلمت منــه‬\n‫مبلغــا وقــدره اثنــان وثمانــون ألــف ريــال وأن املتبقــي عليــه مائــة وثمانيــة‬\n‫وتســعون ألــف ريــال فصحيــح ومــا ذكــره مــن أنــي أعفيتــه عــن املطالبــة‬\n‫ملــا أبلغنــي أنــه ســلم كامــل املبلــغ للمدعــو ‪ .............‬وأنــي ســوف أطالــب‬\n\n\n                                                                                         ‫‪38‬‬\n\f     ‫‪ ................‬مباشــرة فغيــر صحيــح واملدعــى عليــه هــو الــذي فــرط وســلم‬\n     ‫املدعــو ‪ .................‬هــذا املبلــغ وال عالقــة لــي بذلــك فأنــا تعاقــدت مــع‬\n     ‫املدعــى عليــه دون ســواه هكــذا أجــاب وبســؤال املدعــى عليــه هــل أخبــر‬\n     ‫املدعــي أصالــة قبــل تســليم املبلــغ املدعــى بــه إلــى ‪ ....................‬وأنــه أذن‬\n     ‫لــه بهــذا التصــرف فقــال ال فجــرى ســؤال الطرفــن هــل مت إبــرام عقــد‬\n     ‫بينهــم فقــاال نعــم وأبــرزا صــورة مــن العقــد ومت إرفاقــه باملعاملــة وهــذا‬\n     ‫نصــه ‪ ( :‬مت بحمــد اهلل االتفــاق بــن كل مــن الطرفــن الطــرف األول‬\n     ‫‪ .....................‬الطــرف الثانــي ‪ .................‬وذلــك علــى دفــع الطــرف األول‬\n     ‫مبلــغ مــن املــال وقــدره ‪ 280.000‬ريــال للطــرف الثانــي وذلــك لشــراء‬\n     ‫كميــة مــن األعــاف خــال موســم ‪1428‬ه ـ وبيعهــا يف نهايــة املوســم‬\n     ‫علــى أن يكــون الطــرف الثانــي لــه التصــرف املطلــق وعليــه مت التوقيــع‬\n     ‫وعلــى العقــد اســم وتوقيــع املدعــي أصالــة واملدعــى عليه)أ‪.‬ه ـ ولتأمــل‬\n     ‫مــا مت رصــده بعاليــه رفعــت اجللســة ويف جلســة أخــرى حضــر املدعــي‬\n     ‫وكالــة واملدعــى عليــه وبســؤال الطرفــن هــل لديهمــا مــا يضيفانــه‬\n     ‫أجابــا بالنفــي فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر‬\n     ‫املدعــى عليــه بأنــه اســتلم مــن املدعــي أصالــة مبلغــا وقــدره مائتــان‬\n     ‫وثمانــون ألــف ريــال وأنــه ســلم املدعــي مبلغــا وقــدره اثنــان وثمانــون ألــف‬\n     ‫ريــال وحيــث قصــر املدعــي أصالــة مطالبتــه باملبلــغ املتبقــي وقــدره مائــة‬\n     ‫وثمانيــة وتســعون ألــف ريــال وحيــث دفــع املدعــى عليــه بأنــه ســلم املبلــغ‬\n     ‫املدعــى بــه لطــرف ثالــث دون علــم رب املــال وحيــث أن هــذا التصــرف‬\n     ‫ليــس مــن حقــه قــال ابــن قدامــة يف املغنــي ‪( :‬وليــس لــه ـ أي ‪ :‬املضــارب‬\n     ‫ـ أن يشــارك مبــال الشــركة ‪ ،‬وال يدفعــه مضاربــة ؛ ألن ذلــك يثبــت يف‬\n     ‫املــال حقوقــا ‪ ،‬ويســتحق ربحــه لغيــره ‪ ،‬وليــس ذلــك لــه) ‪ ،‬وقــال أيضــا‬\n\n\n‫‪39‬‬\n\f‫‪( :‬وليــس للمضــارب دفــع املــال إلــى آخــر مضاربــة) ‪ ،‬وقــال البهوتــي يف‬\n‫كشــاف القنــاع ‪( :‬فلــو قــال رب املــال‪ :‬عليــك ضمانــه لــم يضمنــه ؛ ألن‬\n‫العقــد يقتضــي كونــه أمانــة غيــر مضمونــة ‪ ،‬مــا لــم يتعــد أو يفــرط)‬\n‫وجــاء يف قــرار مجمــع الفقــه اإلســامي الدولــي رقــم ‪ 123‬مــا نصــه ‪:‬‬\n‫( املضــارب أمــن وال يضمــن مــا يقــع مــن خســارة أو تلــف إال بالتعــدي‬\n‫أو التقصيــر) ‪ ،‬واملدعــى عليــه فــرط يف دفعــه املــال ملضــارب آخــر دون‬\n‫علــم املدعــي لذلــك كلــه فقــد حكمــت علــى املدعــى عليــه ‪..................‬‬\n‫أن يســلم للمدعــي ‪ ..............‬مبلغــا وقــدره مائــة وثمانيــة وتســعون ألــف‬\n‫ريــال ومبــا تقــدم قضيــت وبعرضــه علــى الطرفــن قــرر املدعــي وكالــة‬\n‫القناعــة وقــرر املدعــى عليــه عــدم القناعــة وطلــب االســتئناف واســتعد‬\n‫بتقــدمي الئحــة اعتراضيــة فأجبتــه لطلبــه وجــرى تســليمه نســخة مــن‬\n‫صــك احلكــم لتقــدمي الئحتــه االعتراضيــة خــال املــدة النظاميــة ثالثــن‬\n‫يومــا يســقط بعدهــا حقــه يف االعتــراض ويكتســب احلكــم الصفــة‬\n‫القطعيــة ففهــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                              ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/18‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1434/07/01‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 12 : 00‬وفيهــا أن املعاملــة عــادت مــن محكمة‬\n‫االســتئناف يف تبــوك بخطــاب رئيســها رقــم ‪ 33102542‬وتاريــخ‬\n‫‪1434/5/22‬هـ وبرفقه القرار رقم ‪ 34216577‬وتاريخ ‪1434/5/20‬هـ‬\n‫واملتضمــن بعــد املقدمــة مــا نصــه ‪ ( :‬وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة املقدمــة مــن املدعــى عليــه وأوراق املعاملــة لوحــظ‬\n‫مــا يلــي ‪ -1 :‬لــم ترفــق وكالــة املدعــي أصالــة ولــم يذكــر مضمونهــا يف‬\n‫الصــك والضبــط ‪ -2 .‬لــم يطلــب البينــة مــن املدعــى عليــه علــى مــا دفــع‬\n\n\n                                                                                    ‫‪40‬‬\n\f     ‫بــه مــن أن املدعــى أصالــة أعفــاه مــن املطالبــة وأنــه ســوف يطالــب ‪..........‬‬\n     ‫وقــد ذكــر املدعــى عليــه يف مذكرتــه االعتراضيــة أنــه ال بينــة لديــه‬\n     ‫ويطلــب ميــن املدعــي أصالــة علــى نفــي ذلــك الطــاع فضيلتــه وإكمــال‬\n     ‫مــا يلــزم وإعــادة املعاملــة إلينــا وبــاهلل التوفيــق ) أ‪.‬ه ـ وعلــى القــرار ختــم‬\n     ‫وتوقيــع قضــاة الدائــرة احلقوقيــة األولــى مبحكمــة االســتئناف يف تبــوك‬\n     ‫‪ ....................‬و‪ ..................‬و‪ ..........................‬وأجيــب أصحــاب الفضيلــة‬\n     ‫حفظهــم اهلل مبــا يلــي‪ /1 :‬مــا يتعلــق باملالحظــة األولــى فقــد مت إرفــاق‬\n     ‫صــورة مصدقــة مــن صــك الوكالــة واملدعــي أصالــة ‪ ..................‬قد أقام‬\n     ‫املدعي وكالة ‪ ...................‬وكيال عنه يف املطالبة واملرافعة واملدافعة‬\n     ‫واملخاصمــة وإقامــة الدعــوى ضــد املدعــى عليــه وإنهــاء مــا يلــزم حضــوره‬\n     ‫أمــام احملاكــم الشــرعية والهيئــات القضائيــة وأي جهــة أخــرى وإنهــاء‬\n     ‫كافــة اإلجــراءات املتعلقــة بذلــك ولــه احلــق يف حضــور اجللســات وســماع‬\n     ‫الدعــوى والــرد عليهــا واإلقــرار واإلنــكار وإحضــار البينــات والشــهود‬\n     ‫وطلــب اليمــن وردهــا وقبــول احلكــم واالعتــراض عليــه وطلــب متييــزه‬\n     ‫والطعــن يف البينــات والشــهود وقبولــه ومراجعــة اجلهــات احلكوميــة ذات‬\n     ‫العالقــة بــكل مــا يلــزم والتوقيــع نيابــة عنــه وذلــك مبوجــب الوكالــة‬\n     ‫الصــادرة مــن كتابــة عــدل محافظــة اخلــرج برقــم ‪310508020274‬‬\n     ‫وتاريــخ ‪1431/6/18‬ه ـ ‪ /2 .‬مــا يتعلــق باملالحظــة الثانيــة فقــد حضــر‬\n     ‫الطرفــان وجــرى ســؤال املدعــي عليــه هــل لديــه بينــة علــى أن املدعــي‬\n     ‫أصالــة أعفــاه مــن املطالبــة وأنــه ســوف يطالــب ‪ ...................‬قــال ال‬\n     ‫فجــرى إفهامــه بأنــه لــه ميــن املدعــي أصالــة فقــال إننــي أطلــب ميينــه ‪.‬‬\n     ‫وبنــاء عليــه فقــد جــرى رفــع رفــع اجللســة وتأجيلهــا ويف جلســة أخــرى‬\n     ‫حضــر املدعــي أصالــة ‪ ...................‬ســعودي اجلنســية مبوجــب الســجل‬\n\n\n‫‪41‬‬\n\f‫املدنــي رقــم ‪ ...............‬كمــا حضــر املدعــى عليــه وبســؤال املدعــي‬\n‫أصالــة هــل هــو مســتعد بحلــف اليمــن قــال نعــم فجــرى تخويفــه بعاقبــة‬\n‫اليمــن فقــال إنــي مســتعد باحللــف ثــم حلــف قائــا ‪ ( :‬واهلل العظيــم الــذي‬\n‫ـف هــذا احلاضــر مــن املطالبــة باملبلــغ إطالقــا‬         ‫ال إلــه إال هــو أننــي لــم ُأ ْعـ ِ‬\n‫وأننــي بــاق علــى حقــي) أ‪.‬ه ـ فبنــاء علــى مــا تقــدم وحيــث حلــف املدعــي‬\n‫أصالــة اليمــن املرصــودة بعاليــه فإننــي ال زلــت علــى مــا حكمــت بــه‬\n‫ســابقا وبــه متــت اإلجابــة واالســتجابة علــى مــا حلظــه أصحــاب الفضيلــة‬\n‫وأمــرت بإعــادة كامــل أوراق املعاملــة حملكمــة االســتئناف كاملتبــع‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                  ‫وســلم ‪ .‬حــرر يف ‪1434/08/01‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق ‪ 1434/11/24‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا أن املعاملــة عــادت مــن محكمــة االســتئناف‬\n‫يف تبــوك بخطــاب رئيســها رقــم ‪ 33102542‬وتاريــخ ‪1434/11/10‬ه ـ‬\n‫وبرفقــه القــرار رقــم ‪ 34343932‬وتاريــخ ‪1434/10/28‬ه ـ واملتضمــن‬\n‫بعــد املقدمــة مــا نصــه ‪ ( :‬بنــاء علــى مــا أجــراه فضيلتــه علــى ضــوء‬\n‫قرارنــا رقــم ‪ 34216577‬وتاريــخ ‪1434/5/20‬ه ـ جــرت املصادقــة‬\n‫علــى احلكــم بعــد اإلجــراء األخيــر وبــاهلل التوفيــق) أ‪.‬ه ـ وعلــى القــرار‬\n‫ختــم وتوقيــع قضــاة الدائــرة احلقوقيــة األولــى مبحكمــة االســتئناف يف‬\n‫تبــوك ‪.................‬و‪........................‬و‪ . .............................‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                           ‫‪1434/11/24‬هــ‪.‬‬\n\n\n\n\n                                                                                                       ‫‪42‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":36,"source_page_end":42,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"26db47fbb7cb310bd05e7d19ae980c64c949157c136d1549a38afb3bdaa08c0d","normalized_text_hash":"88c26edc5b3be64e04564a641919c353447be4376a37e7071b3ba69ba1500104","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p36-34167017"},{"id":"0002f70b-8997-54ea-bf41-c86308c2dd67","document_type":"judgment","category":"judicial","subcategory":"general","title":"مشاركة يف عمل -املطالبة بسداد نصيبه من األرباح -رفض املدعى عليه استالم ورقة التبليغ -شهادة الشهود العدول واليمن -تسليم املبلغ احملكوم به -جواز التنازل عن بعض احملكوم به - إلزام املدعى عليه دفع املبلغ املدعى به.","document_number":"3429669","case_number":"3342255","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة يف يوم األربعاء املوافق 1433/2/17ه فتحت اجللسة الساعة يف متام 8","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/4","year":"1434","subject":"مشاركة يف عمل -املطالبة بسداد نصيبه من األرباح -رفض املدعى عليه استالم ورقة التبليغ -شهادة الشهود العدول واليمن -تسليم املبلغ احملكوم به -جواز التنازل عن بعض احملكوم به - إلزام املدعى عليه دفع املبلغ املدعى به.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/2/4 :‬هـ َر ْق ُم‬\n                             ‫ُ‬                ‫َر ْق ُم َّ‬\n                                 ‫الص ِّك‪3429669 :‬‬\n                                   ‫الدعوى‪3342255 :‬‬\n                ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                       ‫‪ 34216863‬تاريخه‪1434/5/20:‬هـ‬\n\n\n      ‫مشــاركة يف عمــل ‪ -‬املطالبــة بســداد نصيبــه مــن األربــاح ‪ -‬رفــض‬\n      ‫املدعــى عليــه اســتالم ورقــة التبليــغ ‪ -‬شــهادة الشــهود العــدول واليمــن‬\n      ‫‪ -‬تســليم املبلــغ احملكــوم بــه ‪ -‬جــواز التنــازل عــن بعــض احملكــوم بــه ‪-‬‬\n                                   ‫إلــزام املدعــى عليــه دفــع املبلــغ املدعــى بــه‪.‬‬\n\n\n\n      ‫‪ -1‬قــال ابــن قدامــة يف املغنــي « وليــس لــه أن يشــارك مبــال الشــركة‬\n      ‫وال يدفعــه مضاربــة ألن ذلــك يثبــت يف املــال حقوقــا ويســتحق ربحــه‬\n                                                      ‫لغيــره وليــس لــه ذلــك» ‪.‬‬\n      ‫‪ -2‬جــاء يف قــرار مجمــع الفقــه اإلســامي الدولــي رقــم (‪ )123‬مــا نصــه‬\n      ‫[ املضــارب أمــن وال يضمــن مــا يقــع مــن خســارة أو تلــف إال بالتعــدي‬\n                                                                        ‫والتقصيــر ] ‪.‬‬\n\n\n\n\n      ‫حضــر املدعــي ولــم يحضــر املدعــى عليــه وأفــاد محضــر اخلصــوم بــأن‬\n      ‫املدعــى عليــه رفــض اســتالم ورقــة التبليــغ‪ ،‬قــررت احملكمــة الســير‬\n      ‫يف نظــر الدعــوى غيابيـاً‪ ،‬ادعــى املدعــي بأنــه اشــترك مــع املدعــى عليــه‬\n      ‫يف عمــل ديكــورات جبســية إلحــدى العمائــر بطلــب مــن املدعــى عليــه‬\n      ‫علــى أن للمدعــي نصــف األربــاح‪ ،‬مت العمــل وجــرت احملاســبة وتبــن أن‬\n\n‫‪43‬‬\n\f‫نصيــب املدعــي مــن األربــاح تســعة وأربعــن ألــف ريــال‪ ،‬طلــب املدعــي‬\n‫إلــزام املدعــى عليــه بدفــع هــذا املبلــغ‪ ،‬أحضــر املدعــي أربعــة شــهود‪،‬‬\n‫ثالثــة شــهود بالعمــل والرابــع باملخالصــة لســبعة أدوار‪ ،‬جــرى ســؤال‬\n‫املدعــي عــن الفــرق يف املبلــغ بــن مــا جــاء يف شــهادة الشــاهد ومــا جــاء‬\n‫يف دعــواه فقــرر أن املبلــغ الــذي ذكــره يف دعــواه يشــمل أجــرة عمــل‬\n‫الــدور الثامــن كام ـاً‪ ،‬جــرى تعديــل الشــهود‪ ،‬طلــب مــن املدعــي‬\n‫اليمــن تكملــة لبينتــه فحلــف اليمــن‪ ،‬جــرى إفهــام املدعــي بــأن لــه‬\n‫ميــن املدعــى عليــه علــى نفــي مــا زاد عــن املبلــغ الــذي شــهد بــه الشــاهد‬\n‫فقــرر أنــه ال يطلــب ميينــه‪ ،‬صــدر احلكــم بإلــزام املدعــى عليــه بدفــع مبلــغ‬\n‫واحــد وأربعــن ألــف ريــال للمدعــي وصــرف النظــر عمــا زاد عــن ذلــك‬\n‫ممــا جــاء يف دعــوى املدعــي‪ ،‬اقتنــع املدعــي باحلكــم‪ ،‬صــدق احلكــم‬\n‫مــن محكمــة االســتئناف‪ ،‬حضــر املدعــي الحقــا وقــرر أنــه اســتلم مــن‬\n‫املدعــى عليــه أربعــن ألــف ريــال وتنــازل عــن ألــف ريــال وبذلــك انتهــت‬\n                                                                         ‫القضيــة‪.‬‬\n\n\n\n\n‫احلمــد هلل رب العاملــن والصــاة والســام علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه أجمعــن وبعــد فبنــاء علــى االســتدعاء الــوارد إلينــا واملقيــد برقم‬\n‫‪ 331073771‬وتاريــخ ‪1433/1/16‬ه ـ واحملــال مــن فضيلة الرئيس برقم‬\n‫‪ 3342255‬لــدي أنــا ‪...‬القاضــي باحملكمــة العامــة مبكــة املكرمــة يف‬\n‫يــوم األربعــاء املوافــق ‪1433/2/17‬ه ـ فتحــت اجللســة الســاعة يف متــام‬\n‫‪ 8.30‬وفيهــا حضــر ‪ ...‬باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة‬\n‫رقــم ‪...‬ثــم يف يــوم األربعــاء املوافــق ‪1433/4/7‬ه ـ فتحــت اجللســة وفيهــا‬\n\n                                                                                       ‫‪44‬‬\n\f     ‫حضــر املدعــي ولــم يحضــر املدعــى عليــه وقــد وردتنــا ورقــة التبليــغ رقــم‬\n     ‫‪ 33330085‬يف ‪1433/2/20‬ه ـ وتتضمــن أنــه مت الوصــول إلــى العنــوان‬\n     ‫املذكــور أعــاه فرفــض املدعــى عليــه اســتالم الطلــب حيــث يقــول ال‬\n     ‫أعتــرف باحملكمــة وال أحضــر يف اجللســة أ‪.‬ه ـ فأذنــت بســماع الدعــوى‬\n     ‫ا إننــي قــد اشــتركت أنــا واملدعــى‬      ‫عليــه غيابي ـ ًا فادعــى املدعــي قائ ـ ً‬\n     ‫عليــه يف عمــل ديكــورات جبســية يف عمــارة ‪...‬بطلــب منــه علــى أن لــي‬\n     ‫نصــف األربــاح التــي تنتــج مــن ذلــك وقــد مت العمــل وجــرت احملاســبة‬\n     ‫بيننــا ومت حســاب املصاريــف وتبــن أن نصيبــي تســعة وأربعــن ألــف‬\n     ‫ريــال فأطلــب إلزامــه بتســليم هــذا املبلــغ هــذه دعــواي فطلبــت منــه البينــة‬\n     ‫علــى ذلــك فقــال أطلــب مهلــة إلحضارهــا فأجبتــه لطلبــه ثــم يف يــوم‬\n     ‫األحــد املوافــق ‪1433/10/22‬ه ـ فتحــت اجللســة وفيهــا حضراملدعــي‬\n     ‫وأحضرللشــهادة كال مــن ‪...‬باكســتاني اجلنســية مبوجــب رخصــة‬\n     ‫االقامــة رقــم ‪...‬و‪ ...‬باكســتاني اجلنســية مبوجــب رخصــة االقامــة رقــم‬\n     ‫‪...‬و‪ ...‬شــاهد ‪ ...‬باكســتاني اجلنســية مبوجــب رخصــة االقامــة رقــم‬\n     ‫‪...‬فشــهد األول بقولــه رايــت هــذا احلاضــر ‪ ...‬عنــد عمــارة يف ‪...‬التــي فيهــا‬\n     ‫األن فنــدق ‪...‬وأخبرنــي ‪ ...‬أن ‪...‬شــريك معــه يف هــذه العمــارة هــذا مــا‬\n     ‫لــدي وبــه أشــهد وشــهد الثانــي بقولــه أنــه حــاول الصلــح بينهمــا وقــد أقــر‬\n     ‫أمامــي بــأن ‪...‬شــريك معــه يف االعمــال اجلبســية ويف عمــارة يف ‪...‬التــي‬\n     ‫فيهــا االن فنــدق ‪...‬وانهمــا اكمــا ســبعة أدوار فطلبــت منــه األوراق‬\n     ‫إلجــراء احملاســبة فاعتــذر بعــدم وجــود االوراق معــه ووعــد بإحضارهــا‬\n     ‫ولــم يفعــل هــذا مــا لــدي وبــه اشــهد وشــهد الثالــث بقولــه رايــت احلاضــر‬\n     ‫هــو و‪ ...‬بإنــزال جبــس مــن شــاحنة الــى عمــارة يف ‪...‬هــذا مــا لــدي وبــه‬\n     ‫أشــهد وبســؤال املدعــي هــل لديــه غيــر مــا أحضــر قــال أطلــب مهلــة‬\n\n\n‫‪45‬‬\n\f‫فأجبتــه لطلبــه ثــم يف يــوم الثالثــاء املوافــق ‪1434/1/6‬ه ـ الســاعة‬\n‫العاشــرة والنصــف صباحـ ًا فتحــت اجللســة وفيهــا حضــر املدعــي وأحضر‬\n‫معــه للشــهادة ‪ ... ...‬باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n‫‪...‬وبســؤال احلاضــر عمــا لديــه قــال إن هــذا احلاضــر ابــن عمــي وقــد كان‬\n‫يعمــل مــع ‪...‬يف عمــارة ‪...‬قــرب كليــة البنــات يعمــان ســوي ًا يف اجلبــس‬\n‫وقــد طلــب منــي هــذا احلاضــر اإلصــاح بينــه وبــن ‪...‬يف تصفيــة احلســاب‬\n‫بينهمــا فاتصلــت علــى ‪...‬وطلبــت منــه احلضــور إلينــا للتفاهــم فحضــر يف‬\n‫عصــر أحــد أيــام اجلمعــة وحصــل نقــاش فأفــاد ‪...‬بأنــه عمــل هــو ‪...‬هــذا‬\n‫احلاضــر ســبعة أدوار وجــزء ًا مــن الثامــن مــن العمــارة التــي يف ‪...‬وأنــه لــه‬\n‫نصــف األجــرة وأنــه قــد قــام بحســاب أجــرة األدوار الســبعة وأنهــا اثنــان‬\n‫وثمانــون ألف ـ ًا ولــم يتــم حســاب أجــرة مــا مت عملــه مــن الــدور الثامــن‬\n‫فقلــت لــه ســلم ‪...‬نصيبــه فقــال إذا اســتلمت املبلــغ مــن صاحــب العمــارة‬\n‫فسأســلم ‪...‬حقــه ثــم بعــد عــدة أســابيع اتصلــت عليــه فقــال ليــس عنــدي‬\n‫لــه إال ألــف ومائــة ريــال ولــن أعطيــه غيرهــا هــذا مــا لــدي وبــه أشــهد‬\n‫فســألت املدعــي هــل لديــه زيــادة بينــة فقــال ليــس لــدي زيــادة فســألته‬\n‫عــن املبلــغ الــذي ذكــره يف دعــواه فقــال إننــي طلبــت تســعة وأربعــن ألفـ ًا‬\n‫منهــا واحــد وأربعــن ألف ـ ًا نصيبــي مــن أجــرة ســبعة أدوار وثمانيــة آالف‬\n                                           ‫هــي نصيبــي مــن عمــل الــدور الثامــن‬\n‫فســألته هــل لديــه بينــة علــى أجــرة الــدور الثامــن فقــال ال فطلبــت منــه‬\n‫ال من ‪ ...‬باكســتاني اجلنســية‬     ‫تعديل شــهوده فاســتعد بذلك وأحضر ك ً‬\n‫مبوجــب رخصــة اإلقامــة رقــم ‪...‬و‪ ...‬باكســتاني اجلنســية مبوجــب رخصة‬\n‫اإلقامــة رقــم ‪...‬فشــهد كل منهمــا بثقــة وعدالــة الشــهود جميعـ ًا ونظــر ًا‬\n‫لعــدم وجــود بينــة للمدعــي علــى املبلــغ الزائــد عمــا شــهد بــه الشــاهد‬\n\n\n                                                                                        ‫‪46‬‬\n\f     ‫األخيــر فقــد أفهمتــه بــأن لــه ميــن املدعــى عليــه علــى نفيــه فقــال ال أريــد‬\n     ‫ميينــه فأفهمتــه بــأن عليــه أداء اليمــن علــى مقــدار املبلــغ الــذي ذكــره‬\n     ‫الشــاهد األخيــر مــع شــهادة الشــاهد الواحــد فاســتعد بذلــك ثــم حلــف‬\n     ‫ا أقســم بــاهلل أن ‪...‬قــد أخبرنــي أن حســاب األدوار الســبعة التــي‬            ‫قائ ـ ً‬\n     ‫عملناهــا اثنــان وثمانــون ألــف ريــال وأن لــي نصفهــا هكــذا حلــف فبنــاء‬\n     ‫علــى مــا تقــدم مــن الدعــوى وشــهادة الشــهود الذيــن أحضرهــم املدعــي‬\n     ‫وألنــه لــم يشــهد منهــم علــى املبلــغ إال شــاهد واحــد وأدى املدعــي اليمــن‬\n     ‫مــع شــهادة هــذا الشــاهد وقــد روى مســلم رحمــه اهلل بســنده عــن ابــن‬\n     ‫عبــاس رضــي اهلل عنهمــا أن النبــي صلــى اهلل عليــه وســلم قضــى بيمــن‬\n     ‫وشــاهد وألن املدعــي قــرر عــدم طلبــه ميــن املدعــى عليــه علــى املبلــغ‬\n     ‫الزائــد عمــا شــهد بــه الشــاهد فقــد ألزمــت املدعــى عليــه بــأن يدفــع‬\n     ‫للمدعــي واحــد ًا وأربعــن ألــف ريــال وصرفــت النظــر عــن الدعــوى عليــه‬\n     ‫مبــا زاد عــن ذلــك وبــه حكمــت وقنــع بــه املدعــي واملدعــى عليــه علــى‬\n     ‫حجتــه متــى حضــر وأمــرت بإصــدار صــك بذلــك وبعــث صورتــه للمدعــى‬\n     ‫عليــه ولــه حــق االعتــراض عليــه خــال ثالثــن يوم ـ ًا مــن تاريــخ تبلغــه‬\n     ‫بــه وإال يســقط حقــه يف االعتــراض ويكتســب احلكــم القطعيــة واهلل‬\n     ‫املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــة أجمعــن‬\n                                                                  ‫حــرر يف ‪1434/1/6‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪...‬ناظــر القضيــة ‪ ...‬يف يــوم األحــد املوافــق‬\n     ‫‪1434/11/23‬ه ـ حضــر ‪...‬وقــرر قائــا إننــي اســتلمت مــن املدعــى عليــه‬\n     ‫‪...‬كامــل املبلــغ احملكــوم بــه يف هــذه الدعــوى وقــدره أربعــون ألــف ريــال‬\n     ‫وإنــي متنــازل عــن األلــف الباقيــة مــن املبلــغ ولــم يبــق يف ذمــة املدعــى عليــه‬\n     ‫أي مبلــغ بخصــوص هــذه الدعــوى هكــذا قــرر وهــو بحالتــه املعتبــرة‬\n\n\n‫‪47‬‬\n\f‫شــرع ًا فبنــاء علــى ذلــك ثبــت لــدي هــذا اإلقــرار وأمــرت بإحلــاق ذلــك علــى‬\n‫الصــك وســجله وبــاهلل التوفيــق وصـ ــلى اهلل وســلم علــى نبينــا محـ ــمد‬\n               ‫وعلى آله وصـ ـ ــحبه أجم ـ ــعني حـ ــرر يف ‪1434 /11 /23‬هـ ‪.‬‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪:‬ـ فقــد‬\n‫جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪33/107371‬‬\n‫وتاريــخ ‪1434/05/04‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ ‪...‬القاضــي باحملكمــة العامــة مبكــة املكرمــة املســجل برقــم‬\n‫‪ 3429669‬وتاريــخ ‪1434/02/04‬ه ـ املتضمــن دعــوى ‪ ...‬باكســتاني‬\n‫اجلنســية ضــد ‪ ،...‬وبدراســة الصــك وص ــورة ضبط ــه تق ــررت املوافق ــة‬\n                          ‫عل ــى احلكــم والغائــب علــى حجتــه واهلل املوفــق‪.‬‬\n                    ‫وصلـى اهلل علـى نبينا محمد وعلـى آلـه وصحبـه وسلم‪.‬‬\n\n\n\n\n                                                                                        ‫‪48‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":43,"source_page_end":48,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7e193325b48956b140c5287c322215bd6baacd5e3fd52b57fc9518b2776545e1","normalized_text_hash":"1282d5669d37f5e178502bf990a8ce24111144bb4040f41b2e5d2195a44cf8b1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p43-3429669"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"b4916c7f-9aee-5c42-9d1d-2c94cc69c1fd","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة -عقد مضاربة -مطالبة برأس املال مع األرباح -ادعاء تسليم آلخر مبوافقة رب املال -استخالف محكمة أخرى لسماع الشهود -مين املدعي واملدعى عليه -احلكم بجزء من املبلغ","document_number":"33316144","case_number":"2308","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/25","year":"1434","subject":"شراكة -عقد مضاربة -مطالبة برأس املال مع األرباح -ادعاء تسليم آلخر مبوافقة رب املال -استخالف محكمة أخرى لسماع الشهود -مين املدعي واملدعى عليه -احلكم بجزء من املبلغ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫تاريخه‪1433/6/25 :‬هـ‬\n                     ‫ُ‬                ‫َر ْق ُم َّ‬\n                        ‫الص ِّك‪33316144 :‬‬\n                           ‫َر ْق ُم الدعوى‪2308 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34188358‬تاريخه‪1434/4/15:‬هـ‬\n\n\n    ‫شــراكة ‪ -‬عقــد مضاربــة ‪ -‬مطالبــة بــرأس املــال مــع األربــاح ‪ -‬ادعــاء‬\n    ‫تســليم آلخــر مبوافقــة رب املــال ‪ -‬اســتخالف محكمــة أخــرى لســماع‬\n    ‫الشــهود ‪ -‬ميــن املدعــي واملدعــى عليــه ‪ -‬احلكــم بجــزء مــن املبلــغ‬\n                                                                    ‫املدعــى بــه ‪.‬‬\n\n\n\n    ‫مــا ذكــره القاضــي مــن مبــادئ عامــة وقواعــد العدالــة يف تســبيب‬\n                                                                 ‫حكمــه ‪.‬‬\n\n\n\n    ‫ادعــى املدعــي بقولــه‪ :‬لقــد ســلم مــوكل موكلــي للمدعــى عليــه مائــة‬\n    ‫وخمســة وعشــرين ألــف ريــال يف ‪2006/2/29‬م لكــي يتجــر بهــا‬\n    ‫املدعــى عليــه‪ ،‬وقــد ربــح وبلــغ نصيــب مــوكل موكلــي مــن الربــح مائــة‬\n    ‫وخمســة وعشــرين ألــف ريــال‪ ،‬وقــد ســلم املدعــى عليــه ملــوكل موكلــي‬\n    ‫مــن الربــح عشــرة آالف ريــال‪ .‬لــذا أطلــب إلــزام املدعــى عليــه بــأن يســلم‬\n    ‫ملــوكل موكلــي رأس املــال مــع األربــاح‪ .‬أنكــر املدعــى عليــه مــا قالــه‬\n    ‫املدعــي والصحيــح أن املدعــي أصالــة ســلم مائــة ألــف ريــال لطــرف آخــر‬\n    ‫‪ ،‬لكــي يســلمها لشــخص آخــر لكــي يتجــر بهــا‪ ،‬وبعــد مضــي شــهر‬\n    ‫ذكــر ‪ ......‬أن مبلــغ املدعــي أصالــة ربــح عشــرة آالف ريــال وســلم هــذا‬\n    ‫الربــح ‪ ،.....‬للمدعــي أصالــة‪ ،‬ثــم أعــاد املدعــي أصالــة بعــد عشــرين يومــا‬\n‫‪5‬‬\n\f‫وســلم ‪ ........‬خمســة وعشــرين ألــف ريــال؛ لكــي يتجــر بهــا‪ .‬وأنكــر‬\n‫املدعــي أنــه فــوض املدعــى عليــه بتســليمها لطــرف آخــر وليــس للمدعــى‬\n‫عليــه بينــة علــى ذلــك وطلــب ميــن املدعــي وحلــف علــى ذلــك‪ .‬ومبــا أن‬\n‫املدعــى عليــه أقــر بكتابــة ســند للمدعــي يتضمــن أنــه اســتلم منــه مائــة‬\n‫وخمســة وعشــرين ألــف ريــال وذلــك عــروض جتــارة عامــة ويقــدم املبلــغ‬\n‫لصاحبــه عنــد طلبــه ودفــع بــأن املبلــغ قــد ســلم ‪ ..........‬لكــي ي ّتجــر بــه‬\n‫ـاء علــى موافقــة املدعــي‪ ،‬ومبــا أن املدعــى عليــه أنكــر حصــول ربــح‬         ‫بنـ ً‬\n‫للمبلــغ املذكــور يف الدعــوى وأقــر بــأن العشــرة آالف ريــال التــي ســلمت‬\n‫للمدعــي عبــارة عــن ربــح ملبلــغ ادعــاه ‪ ....‬لــذا فقــد حكمــت احملكمــة‬\n‫علــى املدعــى عليــه بــأن يســلم املدعــي مائــة وخمســة وعشــرين ألــف ريــال‬\n‫وردت دعــوى املدعــي فيمــا زاد علــى ذلــك ‪ ،‬لــم يقنــع املدعــي وال املدعــى‬\n                 ‫عليــه باحلكــم صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ ،‬فلــدي أنــا ‪ .......................‬القاضــي يف‬\n‫احملكمــة العامــة بالريــاض ففــي يــوم األربعــاء املوافــق ‪1431/03/17‬ه ـ‬\n‫حضــر ‪ .................‬حامــل الســجل املدنــي رقــم ‪ .....................‬بالوكالــة‬\n‫عــن ‪ ........................‬بصفتــه الوكيــل الشــرعي عــن ‪ .................‬مبوجــب‬\n‫الوكالــة الصــادرة مــن كاتــب العــدل املكلــف مبكتــب صاحــب‬\n‫الســمو امللكــي وزيــر الدفــاع والطيــران واملفتــش العــام برقــم ‪ 32‬يف‬\n‫‪1431/1/10‬هــ‪ ،‬وادعــى علــى احلاضــر معــه ‪ ........................‬ســوري‬\n‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ .....................‬قائــا يف دعــواه‪:‬‬\n‫لقــد ســلم مــوكل موكلــي للمدعــى عليــه مائــة وخمســة وعشــرين ألــف‬\n\n                                                                                           ‫‪6‬‬\n\f    ‫ريــال يف ‪2006/2/29‬م لكــي يتجــر بهــا املدعــى عليــه‪ ،‬وقــد ربحــت‬\n    ‫وبلــغ نصيــب مــوكل موكلــي مــن الربــح مائــة وخمســة وعشــرين ألــف‬\n    ‫ريــال‪ ،‬وقــد ســلم املدعــى عليــه ملــوكل موكلــي مــن الربــح عشــرة آالف‬\n    ‫ريــال‪ .‬وأطلــب إلــزام املدعــى عليــه بــأن يســلم ملــوكل موكلــي رأس املــال‬\n    ‫مــع األربــاح‪ .‬هــذه دعــواي‪ .‬وباســتجواب املدعــى عليــه‪ ،‬أجــاب بقولــه‪ :‬مــا‬\n    ‫ذكــره املدعــي وكالــة مــن أن مــوكل موكلــه ســلمني مائــة وخمســة‬\n    ‫وعشــرين ألــف ريــال لكــي أجتــر بهــا فغيــر صحيــح‪ ،‬والصحيــح أن‬\n    ‫املدعــي أصالــة ســلم ل‪.......................‬مائــة ألــف ريــال‪ ،‬لكــي يســلمها‬\n    ‫ل‪ ..................‬لكــي يتجــر بهــا‪ ،‬وبعــد مضي شــهر ذكــر ‪...........‬أن مبلغ‬\n    ‫املدعــي أصالــة ربــح عشــرة آالف ريــال وســلم هــذا الربــح ل‪،................‬‬\n    ‫فســلم ‪............‬هــذا الربــح للمدعــي أصالــة‪ ،‬ثــم أعــاد املدعــي أصالــة بعــد‬\n    ‫عشــرين يومــا وســلم ل‪ ...............‬خمســة وعشــرين ألــف ريــال؛ لكــي‬\n    ‫يتجــر بهــا‪ ،‬وقــد كتبــت للمدعــي أصالــة ســندا يف ‪2006/8/29‬م‪،‬‬\n    ‫وقــد جــاء فيــه مــا نصــه‪( :‬نعــم أنــا ‪ ................‬لقــد اســتلمت مــن املدعــو‬\n    ‫‪..................‬مبلغــا قــدره مائــة وخمســة وعشــرين ألــف ريــال ســعودي‬\n    ‫وذلــك عــروض جتــارة عامــة علمــا أن امليزانيــة شــهرية‪ ،‬ويقــدم املبلــغ‬\n    ‫لصاحبــه عنــد طلبــه) ا‪.‬هــ‪ .‬ثــم وقعــت علــى هــذا الســند‪ ،‬وقــد كتبــت‬\n    ‫هــذا الســند باســمي لكــون املدعــي أصالــة لوجــود الثقــة التــي بينــي‬\n    ‫وبــن املدعــي أصالــة‪ ،‬وبعــد مضــي شــهر حضــر لــدي يف ورشــتي‬\n    ‫املدعــي أصالــة و‪ ،......................‬وقــال ‪ ...................‬للمدعــي أصالــة‬\n    ‫إن أموالــي وأمــوال ‪ ..............‬قــد وضعناهــا لــدى املوظــف مبؤسســتي‬\n    ‫‪ ،................‬فهــل تريــد أن أعيــد لــك أموالــك أم تريــد أن أضعهــا عنــد‬\n    ‫‪.............‬لكــي يتجــر بهــا لــك؟ فقــال املدعــي أصالــة يف أول األمــر بــل‬\n\n\n‫‪7‬‬\n\f‫أريــد أن تعيــد لــي أموالــي‪ ،‬ثــم رجــع املدعــي أصالــة قبــل خروجــه مــن‬\n‫الورشــة‪ ،‬وقــال‪ :‬ل‪ ......................‬مــا دام أنــك قــد وضعــت أنــت و‪..............‬‬\n‫أموالكمــا لــدى ‪ .................‬فضــع أموالــي التــي لديــك وقدرهــا مائــة‬\n‫وخمســة وعشــرون ألــف ريــال عنــد ‪ ................‬لكــي يتجــر لــي بهــا وقــد‬\n‫قــام ‪ .................‬بتســليم أمــوال املدعــي أصالــة ل‪ .....................‬ثــم تبــن‬\n‫أن ‪ ........................‬محتــال‪ ،‬وقــد أكل أموالــي وأمــوال ‪.................‬‬\n‫وأمــوال املدعــي أصالــة‪ ،‬وأن األربــاح التــي ســلمها وهميــة‪ ،‬وقــد طالبــه‬\n‫‪..........‬بــرأس املــال الــذي ســلمه لــه‪ ،‬والــذي يخصنــي ويخــص املدعــي‬\n‫أصالــة‪ ،‬ويخــص ‪ ،...................‬وقــد حكــم علــى ‪...............‬بــأن يســلم‬\n‫ل ــ‪ ................‬ثمامنائــة وثالثــن ألــف ريــال‪ ،‬منهــا مائــة وخمســة عشــر‬\n‫ألــف ريــال التــي تخــص املدعــي أصالــة‪ ،‬وذلــك بالصــك الصــادر مــن‬\n‫احملكمــة العامــة بالدمــام برقــم ‪ 5/41‬يف ‪1429/3/3‬هــ‪ ،‬ولــم ينفــذ‬\n‫‪..............‬هــذا احلكــم حتــى اآلن وال يــزال مســجونا مــن أجــل تنفيــذ‬\n‫احلكــم‪ .‬هكــذا أجــاب‪ .‬وبعــرض ذلــك علــى املدعــي وكالــة قــال‪:‬‬\n‫إننــي ســأراجع املدعــي أصالــة وأفيدكــم يف اجللســة القادمــة‪ .‬ويف يــوم‬\n‫األربعــاء املوافــق ‪ 1432/01/02‬ه ـ حضــر ‪ ...............‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ..................‬بالوكالــة عــن ‪...................‬‬\n‫ا عــن‬ ‫حامــل الســجل املدنــي رقــم ‪ ....................................‬بصفتــه وكيـ ً‬\n‫‪ .....................‬ســوري اجلنســية مبوجــب اإلقامــة رقــم ‪ ................‬مبوجــب‬\n‫الوكالــة الصــادرة مــن كاتــب العــدل املكلــف بالعمــل مبكتــب‬\n‫صاحــب الســمو امللكــي وزيــر الدفــاع والطيــران واملفتــش العــام برقــم‬\n‫‪ 491‬يف ‪1431/08/16‬ه ـ كمــا حضــر ‪.....................‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ....................‬بالوكالــة عــن ‪.............‬‬\n\n\n                                                                                              ‫‪8‬‬\n\f    ‫ســوري اجلنســية مبوجــب اإلقامــة رقــم ‪ .......................‬مبوجــب الوكالــة‬\n    ‫الصــادرة مــن كتابــة العــدل الثانيــة بشــرق الريــاض برقــم ‪ 146273‬يف‬\n    ‫‪1431/03/14‬ه ـ فطلبــت مــن املدعــي وكالــة اجلــواب عــن مــا ذكــره‬\n    ‫املدعــى عليــه وكالــة فقــال إن مــا ذكــره مــوكل املدعــى عليــه غيــر‬\n    ‫صحيــح والصحيــح وأن موكلــي اتفــق مــع املدعــى عليــه أصالــة علــى أن‬\n    ‫يســلم مــوكل موكلــي للمدعــى عليــه أصالــة مائــة وخمســة وعشــرين‬\n    ‫ألــف ريــال لكــي يتجــر بهــا املدعــى عليــه أصالــة والربــح بينهمــا فطلــب‬\n    ‫املدعــى عليــه أصالــة مــن موكلــي إيــداع هــذا املبلــغ يف حســاب مؤسســة‬\n    ‫‪.............‬للمقــاوالت يف بنــك ‪ ....‬فــأودع موكلــي املبلــغ يف حســاب‬\n    ‫املؤسســة املذكــورة وكتــب املدعــى عليــه أصالــة الســند الــذي أقــر بــه‬\n    ‫يف اجللســة األولــى ولــم يوافــق موكلــي علــى تســليم شــيء مــن هــذا املبلــغ‬\n    ‫ل‪ .....................‬وأطلــب إلــزام املدعــى عليــه أصالــة بــأن يســلم ملوكلــي‬\n    ‫املتبقــي مــن رأس مالــه وقــدره مائــة وخمســة عشــر ألــف ريــال وأحصــر‬\n    ‫دعــواي يف ذلــك هكــذا أجــاب فســألت املدعــى عليــه وكالــة هــل لــدى‬\n    ‫موكلــه بينــة علــى قبــول املدعــي أصالــة لتســليم املبلــغ املذكــور يف‬\n    ‫الدعــوى ل‪....................‬لإلجتــار بــه فقــال إننــي ســوف أراجــع موكلــي‬\n    ‫وأفيدكــم يف اجللســة القادمــة وموكلــي يســكن يف اخلبــر مــن خمــس‬\n    ‫ســنوات وأطلــب إحالــة املعاملــة للمحكمــة العامــة باخلبــر هكــذا أجــاب‬\n    ‫فأفهمتــه أنــه إن كان لــدى موكلــه بينــة فعليــه إحضارهــا يف اجللســة‬\n    ‫القادمــة وأمــا مــا يتعلــق بالدفــع بعــدم االختصــاص احمللــي فأفهمتــه أن‬\n    ‫هــذا الدفــع ال يقبــل بعــد اجللســة األولــى حســب املــادة احلاديــة والســبعني‬\n    ‫مــن نظــام املرافعــات الشــرعية‪ .‬ويف يــوم الســبت املوافــق ‪1432/5/5‬ه ـ‬\n    ‫حضــر املدعــي أصالــة ‪ ...................‬ســوري اجلنســية مبوجــب اإلقامــة رقم‬\n\n\n‫‪9‬‬\n\f‫‪.....................‬واملدعــى عليــه أصالــة فســألت املدعــى عليــه هــل لديــه بينــة‬\n‫علــى قبــول املدعــي بتســليم املبلــغ املذكــور يف الدعــوى ل‪....................‬‬\n‫لإلجتــار بــه فقــال نعــم فســألته لـ َـم لــم يحضرهــا وقــد أفهمــت وكيلــه‬\n‫بإحضارهــا فقــال إنــه لــم يخبرنــي بذلــك فرفعــت اجللســة إلحضــار البينــة‬\n‫وأفهمتــه أنــه إن أحضرهــا يف اجللســة القادمــة وإال اعتبرتــه عاجــز ًا عــن‬\n                                                                        ‫إحضارهــا‪.‬‬\n‫ويف يــوم الســبت املوافــق ‪1432/8/15‬ه ـ حضــر املدعــي واملدعــى عليــه‬\n‫فســألت املدعــى عليــه هــل أحضــر البينــة التــي وعــد بإحضارهــا ؟‬\n‫فقــال ‪ :‬نعــم وأحضــر ‪ .....................‬ســوري اجلنســية مبوجــب اإلقامــة‬\n‫رقــم ‪ ......................‬وبســؤاله عمــا لديــه قــال أشــهد أنــه قبــل أكثــر مــن‬\n‫ســنة أخبرنــي املدعــي ‪ ..............‬أنــه ســوف يشــغل أموالــه يف شــركة‬\n‫عــن طريــق املدعــى عليــه‪ ................‬وســألني عنــه فقلــت لــه ‪ :‬الرجــال‬\n‫مــا عليــه ثــم أخبرنــي املدعــي بعــد ذلــك أنــه ســلم مبلغــا للمدعــى عليــه‬\n‫هكــذا شــهد ‪ ،‬كمــا أحضــر ‪ ...........‬ســوري اجلنســية مبوجــب اإلقامــة‬\n‫رقــم ‪ .............‬وبســؤاله عمــا لديــه قــال أشــهد أن املبلــغ الــذي ســلمه‬\n‫املدعــي ‪ ..............‬للمدعــى عليه‪...............‬لتســليمه لشــركة ‪ ....‬يف ‪....‬‬\n‫للتجــارة بــه وليــس ليتجــر بــه بنفســه ولــم أحضــر معهمــا عنــد تســليم‬\n‫املبلــغ أو عنــد االتفــاق وقــد علمــت ذلــك ألن املدعــى عليــه يســتلم املبالــغ‬\n‫مــن النــاس لغــرض تســليمها لتلــك الشــركة لإلجتــار بهــا هكــذا شــهد‬\n‫‪ ،‬فســألت املدعــى عليــه هــل لديــه زيــادة بينــة ؟ فقــال ‪ :‬نعــم ووعــد‬\n‫بإحضارهــا يف اجللســة القادمــة ‪ ،‬فأفهمتــه إنــه إن أحضرهــا يف اجللســة‬\n‫القادمــة وإال اعتبرتــه عاجــزا عــن إحضارهــا‪ .‬ويف يــوم األربعــاء املوافــق‬\n‫‪1433/2/10‬ه ـ حضــر املدعــي واملدعــى عليــه فســألت املدعــى عليــه‬\n\n\n                                                                                           ‫‪10‬‬\n\f     ‫هــل أحضــر الشــهود فقــال ‪ :‬إنهمــا يقيمــان يف الدمــام وهمــا ‪...............‬‬\n     ‫و‪ ..............‬ورفضــا احلضــور معــي للريــاض وأطلــب اســتخالف احملكمــة‬\n     ‫العامــة بالدمــام لســماع شــهادتهما لــذا قــررت اســتخالف فضيلــة رئيــس‬\n     ‫احملكمــة العامــة بالدمــام أو مــن ينيبــه مــن قضــاة احملكمــة يف ســماع‬\n     ‫شــهادة الشــاهدين املذكوريــن وشــهادة املزكــن لهمــا ‪ .‬وقــرر املدعــي‬\n     ‫أنــه ال يرغــب احلضــور عنــد أداء الشــهادة ‪ .‬فرفعــت اجللســة لذلك‪ .‬ويف يوم‬\n     ‫األربعــاء املوافــق ‪1433/06/25‬ه ـ حضــر املدعــي واملدعــى عليــه وقــد‬\n     ‫وردنــي خطــاب رئيــس احملكمــة العامــة بالدمــام برقــم ‪ 33/630501‬يف‬\n     ‫‪1433/06/04‬ه ـ واملرفــق بــه صــورة طبــق األصــل مــن الضبــط التالــي‬\n     ‫نصــه‪( :‬اســتخالف يف قضيــة حقوقيــة ـ بطلــب رســمي احلمــد هلل وحــده‬\n     ‫وبعــد فلــدي أنــا ‪ .......................‬القاضــي يف احملكمــة العامــة بالدمــام‬\n     ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n     ‫بالدمــام املســاعد برقــم ‪ 33236227‬وتاريــخ ‪1433/04/04‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 33630501‬وتاريــخ ‪1433/04/04‬ه ـ واملبنيــة علــى‬\n     ‫كتــاب فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم ‪33/307762‬‬\n     ‫وتاريــخ ‪1433/02/16‬ه ـ املتضمــن اســتخالف فضيلــة القاضــي الشــيخ‬\n     ‫‪ ...................‬لنــا يف ســماع بينــة املدعــى عليــه يف الدعــوى التــي أقامهــا‬\n     ‫‪ ................‬ضــده ففــي يــوم األحــد املوافــق ‪1433/05/16‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 47:10‬وفيهــا حضــر ‪ .....................‬ســوري اجلنســية‬\n     ‫مبوجــب اإلقامــة رقــم ‪ ..................‬وأحضــر معــه ‪ ...............‬ســوري‬\n     ‫اجلنســية مبوجــب اإلقامــة رقــم ‪.......................‬و‪ .................‬ســوري‬\n     ‫اجلنســية مبوجــب اإلقامــة رقــم ‪..............‬وقــد شــهد كل واحــد منهمــا‬\n     ‫علــى حــده بقولــه اجتمــع ‪ ............‬مــع ‪ .................‬يف بيتــي أنــا ‪.............‬‬\n\n\n‫‪11‬‬\n\f‫باخلبــر ومعهمــا جماعــة يطلبــون ‪ ..................‬مبالــغ واعتــرف‪.................‬‬\n‫باملبالــغ التــي يطالبونــه بهــا وأنهــا يف ذمتــه والتــزم بســدادها وكتــب‬\n‫لــكل واحــد منهــم ورقــة وســندا باملبلــغ الــذي يف ذمتــه وأعطــى كل‬\n‫دائــن ورقــة باملبلــغ هكــذا شــهدا وأمــرت ببعــث صــورة ضبطــه لفضيلــة‬\n‫القاضــي املســتخلف‪ .‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلى‬\n‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/05/16‬ه ـ املدعــى عليــه ‪..............‬‬\n‫توقيــع شــاهد ‪ ........‬توقيــع شــاهد ‪ ................‬توقيــع كاتــب الضبــط‬\n‫‪ ..............‬توقيــع القاضــي يف احملكمــة العامــة بالدمــام ‪..................‬‬\n‫ختمــه وتوقيعه)اهــ‪ .‬ثــم قــال املدعــي إننــي أعــود إلــى املطالبــة مبــا طالــب‬\n‫بــه وكيلــي يف اجللســة األولــى فســألت املدعــي هــل لديــه بينــة علــى أن‬\n‫املدعــى عليــه قــد ربــح يف املبلــغ الــذي ســلمه إيــاه مائــة وخمــس وعشــرين‬\n‫ألــف ريــال فقــال ال بينــة لــدي علــى ذلــك‪ .‬فأفهمــت املدعــي أن لــه ميــن‬\n‫املدعــى عليــه بالصيغــة التاليــة‪( :‬واهلل الــذي ال إلــه إال هــو إننــي لــم أجتــر‬\n‫باملبلــغ املذكــور يف الدعــوى ولــم أحصــل منــه أي أربــاح عــدا العشــرة‬\n‫آالف ريــال التــي ســلمني إياهــا ‪ ..............‬وســلمتها للمدعــي) فقــال‬\n‫أطلــب ميينــه وبعــرض اليمــن علــى املدعــى عليــه اســتعد ببذلهــا ثــم حلــف‬\n‫اليمــن بالصيغــة املذكــورة آنفــا فأفهمــت املدعــى عليــه أن لــه ميــن‬\n‫املدعــي بالصيغــة التاليــة‪( :‬واهلل الــذي ال إلــه إال هــو إننــي قــد ســلمت‬\n‫مائــة وخمــس وعشــرين ألــف ريــال للمدعــى عليــه ‪ ...........‬لكــي يتجــر‬\n‫بهــا بنفســه ولــم أســلمها لــه لكــي يســلمها ل‪ .................‬لكــي يتجــر‬\n‫بهــا) فقــال أطلــب ميينــه وبعــرض اليمــن علــى املدعــي اســتعد ببذلهــا ثــم‬\n‫حلــف اليمــن بالصيغــة املذكــورة آنفــا فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة ومبــا أن املدعــى عليــه أقــر بكتابــة ســند للمدعــي يتضمــن‬\n\n\n                                                                                          ‫‪12‬‬\n\f     ‫أنــه اســتلم منــه مائــة وخمســة وعشــرين ألــف ريــال وذلــك عــروض جتــارة‬\n     ‫عامــة ويقــدم املبلــغ لصاحبــه عنــد طلبــه ودفــع بــأن املبلــغ قــد ســلم‬\n     ‫ل‪ ................‬لكــي يتجــر بــه بنــاء علــى موافقــة املدعــي وأنكــر املدعــي‬\n     ‫ذلــك ولــم يقــم املدعــى عليــه بينــة علــى موافقــة املدعــي علــى تســليم‬\n     ‫املبلــغ ل‪ .........................‬لكــي يتجــر بــه والشــهود الذيــن أحضرهــم‬\n     ‫املدعــى عليــه لــم يشــهدوا بذلــك وطلــب ميــن املدعــي علــى نفــي ذلــك‬\n     ‫وحلــف املدعــي علــى نحــو مــا طلــب منــه ومبــا أن املدعــى عليــه أنكــر‬\n     ‫حصــول ربــح للمبلــغ املذكــور يف الدعــوى وأقــر بــأن العشــرة آالف‬\n     ‫ريــال التــي ســلمت للمدعــي عبــارة عــن ربــح ملبلغــه ادعــاه ‪..........‬لــذا فقــد‬\n     ‫حكمــت علــى املدعــى عليــه بــأن يســلم املدعــي مائــة وخمســة وعشــرين‬\n     ‫ألــف ريــال ورددت دعــوى املدعــي فيمــا زاد علــى ذلــك وأخليــت ســبيل‬\n     ‫املدعــى عليــه منــه وبذلــك حكمــت‪ .‬وبعــرض احلكــم علــى الطرفــن‬\n     ‫قــررا عــدم القناعــة وطلبــا االســتئناف فأجبتهمــا لطلبهما وقررت تســليم‬\n     ‫كل واحــد منهمــا صــورة مــن صــك احلكــم حــاال لتقــدمي معارضتــه عليــه‬\n     ‫خــال مــدة ال تتجــاوز ثالثــن يومــا فمــن تأخــر منهمــا عــن ذلــك ســقط‬\n     ‫حقــه يف تقــدمي االعتــراض واكتســب احلكــم يف حقــه القطعيــة‪ .‬وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                              ‫حــرر يف ‪1433/06/25‬هــ‪.‬‬\n\n\n     ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34188358‬وتاريــخ‬\n                                                      ‫‪1434/4/15‬هـ‬\n\n\n\n\n‫‪13‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":5,"source_page_end":13,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"988287423af5b11c09cfcdd7d6d15b022461625feb5abc804b955ba370efd564","normalized_text_hash":"797dc21ea44b418f9b55416e469b7e7bcfe4bed2dd0b2a2cb3754deb015c87d4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p5-33316144"},{"id":"ba8d9ee8-34c3-5641-b84f-b52e6614f0c7","document_type":"judgment","category":"judicial","subcategory":"general","title":"شركة -نزاع بن شركاء يف شركة -تظلم من قرار شريك أدى خلسارة الشركة -إقامة الدعوى ضد الغرفة التجارية -دفع املدعى عليها بعدم الصفة وأن مهمتها تقدمي الدعم واملشورة وكونها حاضنة للمشروع ال يلزمها منه حتمل املسؤولية التضامنية -صرف النظر عن دعوى املدعي.","document_number":"3443725","case_number":"2354","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/23","year":"1434","subject":"شركة -نزاع بن شركاء يف شركة -تظلم من قرار شريك أدى خلسارة الشركة -إقامة الدعوى ضد الغرفة التجارية -دفع املدعى عليها بعدم الصفة وأن مهمتها تقدمي الدعم واملشورة وكونها حاضنة للمشروع ال يلزمها منه حتمل املسؤولية التضامنية -صرف النظر عن دعوى املدعي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/2/23 :‬هـ َر ْق ُم‬\n                         ‫ُ‬                ‫َر ْق ُم َّ‬\n                             ‫الص ِّك‪3443725 :‬‬\n                                   ‫الدعوى‪2354 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 34265623‬تاريخه‪1434/7/11:‬هـ‬\n\n\n   ‫شــركة ‪ -‬نــزاع بــن شــركاء يف شــركة ‪ -‬تظلــم مــن قــرار شــريك‬\n   ‫أدى خلســارة الشــركة ‪ -‬إقامــة الدعــوى ضــد الغرفــة التجاريــة ‪ -‬دفــع‬\n   ‫املدعى عليها بعدم الصفة وأن مهمتها تقدمي الدعم واملشــورة وكونها‬\n   ‫حاضنة للمشــروع ال يلزمها منه حتمل املســؤولية التضامنية ‪ -‬صرف‬\n                                                   ‫النظــر عــن دعــوى املدعــي‪.‬‬\n\n\n\n\n   ‫مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة الــواردة يف‬\n                                                                ‫تســبب احلكــم‪.‬‬\n\n\n\n   ‫ادعــى املدعــي بدعــوى ضــد الغرفــة التجاريــة بأنــه اتفــق مــع أحــد رؤســاء‬\n   ‫جلانهــا علــى إنشــاء شــركة ملزاولــة نشــاط جتــاري وبعــد فتــح حســاب‬\n   ‫مصــريف لــه والترويــج واســتقبال املســاهمات مــن النــاس أصــدر قــرارا‬\n   ‫برفــع قيمــة الســهم ممــا حمــل املســاهمني لســحب أموالهــم ممــا أحلــق‬\n   ‫اخلســارة الفادحــة بــه ويطلــب تعويضــه عمــا حصــل لــه مــن ضــرر دفــع‬\n   ‫وكيــل الغرفــة التجاريــة بطلــب صــرف النظــر عــن دعــواه إلقامتــه علــى‬\n   ‫غيــر ذي صفــة فمهمــة الغرفــة التجاريــة تقــدمي االرشــادات واالستشــارات‬\n   ‫وقــرار رئيــس أحــد اللجــان املتظلــم منــه كان بصفتــه الشــخصية ال‬\n   ‫بصفتــه رئيس ـ ًا للجنــة وأن النظــام ال يســمح للغرفــة التجاريــة مبزاولــة‬\n                                                                                       ‫‪14‬‬\n\f     ‫التجــارة وكــون الغرفــة حاضنــة للمشــروع وداعمــة لــه ال يعنــي ضمانهــا‬\n     ‫وال يحملهــا املســؤولية عليــه وملــا اتضــح مــن دعــوى املدعــي أن النــزاع‬\n     ‫الــذي يذكــره نــزاع بــن شــركاء‪ ،‬والغرفــة التجارية ليســت طرف ًا فيه‪،‬‬\n     ‫وليســت شــريكة يف هــذه الشــركة علــى فــرض وجودهــا‪ ،‬وقــد ظهر أن‬\n     ‫القــرار الــذي يدعــى املدعــي تضــرره منــه صــادر مــن رئيــس مجلــس إدارة‬\n     ‫الشــركة املشــار إليهــا‪ ،‬وكــون الغرفــة التجاريــة حتتضــن هذا املشــروع‬\n     ‫وتدعمــه ال يحملهــا مســؤولية إخفاقــه يف حــال تقصيرهــا‪ ،‬لــذا فقــد‬\n     ‫صــدر احلكــم بــرد دعــوى املدعــي جتــاه املدعــى عليــه الغرفــة التجاريــة‬\n     ‫ولــه إقامــة دعــواه ضــد الشــريك لــدى اجلهــة القضائيــة املختصــة قــرر‬\n     ‫املدعــي االعتــراض فأفهــم بالتعليمــات‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                         ‫االســتئناف‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده لــدي أنــا (‪ )......‬القاضــي يف احملكمــة العامــة‬\n     ‫ـاء علــى املعاملــة املقيــدة يف هــذه احملكمــة برقــم‬      ‫باملدينــة املنــورة بنـ ً‬\n     ‫‪ 318588‬وتاريــخ ‪1431/02/10‬ه ـ واحملالــة مــن فضيلــة الرئيــس برقــم‬\n     ‫‪2354‬وتاريــخ ‪1431/02/10‬ه ـ عليــه ففــي هــذا اليــوم الســبت املوافــق‬\n     ‫‪1432/06/25‬ه افتتحــت اجللســة الســاعة ‪11.30‬ص وفيهــا حضــر‬\n     ‫(‪ )......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )......‬ولــم يحضــر‬\n     ‫ممثــل (‪ )......‬وقــد وردنــا خطــاب (‪ )......‬املتضمــن أنــه نظــر ًا النتهــاء مــدة‬\n     ‫مجلــس اإلدارة احلالــي وال تــزال وزارة التجــارة والصناعــة بصــدد اتخــاذ‬\n     ‫إجــراءات انتخــاب مجلــس إدارة جديــد ورفعــت اجللســة ويف جلســة‬\n     ‫أخــرى لــم يحضــر املدعــي وال مــن ميثلــه ولــم يحضــر املدعــى عليــه وال مــن‬\n\n‫‪15‬‬\n\f‫ميثلــه ونظــر ًا النتهــاء الوقــت احملــدد للنظــر يف الدعــوى لــذا فقــد جــرى‬\n‫شــطبها للمــرة األولــى ويف جلســة أخــرى كان املدعــي قــد تقــدم بطلــب‬\n‫مواصلــة النظــر يف دعــواه فتــم قبــول طلبــه ومت حتديــد هــذا اليــوم موعــد ًا‬\n‫لنظــر الدعــوى وقــد حضــر املدعــي ولــم يحضــر ممثــل للمدعــى عليهــا‬\n‫(‪ )......‬وقــد وردنــا منهــم خطــاب رقــم ق‪ 258/‬وتاريــخ ‪1433/01/24‬ه ـ‬\n‫يتضمــن أنــه لــم يصلهــم قــرار اعتمــاد رئيــس مجلــس (‪ )......‬إال منــذ‬\n‫أيــام قليلــة ويطلبــون تأجيــل اجللســة وعليــه رفعــت اجللســة ويف جلســة‬\n‫أخــرى حضــر املدعــي وحضــر حلضــوره (‪ )......‬ســعودي اجلنســية مبوجــب‬\n‫الهويــة الوطنيــة ذات الرقــم (‪ )......‬بصفتــه الوكيــل الشــرعي عــن اجلهــة‬\n‫املدعــى عليهــا مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الثانيــة‬\n‫باملدينــة املنــورة برقــم ‪ 7293‬وتاريــخ ‪1433/01/29‬ه ـ وقــد قــرر املدعــي‬\n‫قائ ـاً‪ :‬أطلــب إمهالــي إلحضــار دعــواي محــررة فأجيــب لطلبــه ورفعــت‬\n‫اجللســة ويف جلســة أخــرى حضــر املدعــي وحضــر حلضــوره املدعــى عليــه‬\n‫وكالــة ثــم ابــرز املدعــي الئحــة دعــوى مكونــة مــن ســبع صفحــات‬\n‫تقــرر االطــاع عليهــا ورصــد مضمونهــا يف اجللســة القادمــة ومت تزويــد‬\n‫املدعــى عليــه وكالــة بنســخة منهــا للجــواب عليهــا يف اجللســة القادمــة‬\n‫ورفعــت اجللســة ويف جلســة أخــرى حضــر الطرفــان وقــد أحضــر املدعــى‬\n‫عليــه وكالــة مذكــرة جوابيــة علــى الدعــوى ونظــر ًا ألن مذكرتــي‬\n‫الدعــوى واإلجابــة طويلتــان فقــد طلــب مــن الطرفــن إحضارهمــا عــن‬\n‫طريــق وســائط إلكترونيــة لكــي يتــم تنزيلهــا يف الضبــط فاســتعدا‬\n‫لذلــك ورفعــت اجللســة ويف جلســة أخــرى حضــر املدعــي وحضــر حلضــوره‬\n‫(‪ )......‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪ )......‬بصفتــه‬\n‫ممثـ ًـا (‪ )......‬مبوجــب خطــاب التفويــض ذي الرقــم ق‪ 1791/‬وتاريــخ‬\n\n\n                                                                                      ‫‪16‬‬\n\f     ‫‪1433/9/9‬ه ـ الصــادر مــن رئيــس مجلــس إدارة (‪ )......‬والتــي تخــول لــه‬\n     ‫حــق املرافعــة واملدافعــة واملخاصمــة واملطالبــة وحضــور اجللســات والــرد‬\n     ‫عليهــا وســماعها واإلقــرار واإلنــكار واجلــرح والتعديــل والطعــن وقبــول‬\n     ‫األحــكام مــن عدمهــا واملطالبــة باحلقــوق وإثباتهــا وطلــب حلــف اليمــن‬\n     ‫ورده واالســتئناف والتمييــز وقــد قــرر الطرفــان قائلــن‪ :‬نطلــب تأجيــل‬\n     ‫ـاع للصلــح فأجيبــا لطلبهمــا ورفعــت اجللســة ويف‬        ‫اجللســة لوجــود مسـ ٍ‬\n     ‫جلســة أخــرى حضــر املدعــي وحضــر حلضــوره (‪ )......‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم (‪ )......‬بصفتــه الوكيــل الشــرعي عــن‬\n     ‫اجلهــة املدعــى عليهــا مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n     ‫الثانيــة باملدينــة املنــورة برقــم ‪ 343368‬وتاريــخ ‪1434/1/3‬ه والتــي‬\n     ‫تخــول لــه فيهــا حــق املطالبــة وإقامــة الدعــاوي واملرافعــة واملدافعــة‬\n     ‫وســماع الدعــاوي والــرد عليهــا وطلــب حلــف اليمــن ورده واالمتنــاع عنــه‬\n     ‫واحضــار الشــهود والبينــات والطعــن فيهــا واالجابــة وبســؤال املدعــي عــن‬\n     ‫ا إننــي أملــك مؤسســة جتاريــة باســم (‪ )......‬واملســجلة‬   ‫دعــواه ادعــى قائـ ً‬\n     ‫يف وزارة التجــارة مبوجــب الســجل التجــاري ذي الرقــم (‪ )......‬وتاريــخ‬\n     ‫‪1428/08/05‬هـ ـ تعمــل هــذه املؤسســة يف نشــاط تأهيــل وتدريــب‬\n     ‫وتوظيــف الكــوادر النســائية يف منطقــة (‪ )...‬ومنطقــة (‪ )...‬ثــم مت االتفاق‬\n     ‫مــع رئيــس جلنــة شــباب األعمــال يف الغرفــة التجاريــة بــ‪ ......‬املدعــى عليهــا‬\n     ‫مبوجــب مذكــرة تفاهــم وتتضمــن تأســيس شــركة (‪ )......‬كشــركة‬\n     ‫مســاهمة تطــرح لالكتتــاب ثــم مت فتــح حســاب بإســمي وباســم املديــر‬\n     ‫املالــي (‪ )......‬يف بنــك (‪ )......‬وبــدأ األعضــاء واملؤسســون بإيــداع املبالــغ‬\n     ‫وكان الســهم حينهــا لألعضــاء املؤسســن خمســة وثالثــون ألــف ريــال‬\n     ‫ثــم أتخــذ رئيــس جلنــة شــباب األعمــال املعــن رئيس ـ ًا ملجلــس إدارة هــذه‬\n\n\n‫‪17‬‬\n\f‫الشــركة قــرار ًا برفــع الســهم مــن خمســة وثالثــن ألــف ريــال إلــى مائــة‬\n‫ألــف ريــال فســحب املؤسســون مــا دفعــوه ثــم مت إجهــاض املشــروع مــن‬\n‫قبــل رئيــس مجلــس اإلدارة بعــد الترويــج لــه إعالميـ ًا وقــد تضــررت مــن‬\n‫ذلــك حيــث إننــي بذلــت جهــدي وانتقلــت مــع مؤسســتي وأســرتي كاملــة‬\n‫مــن منطقــة تبــوك واجلــوف إلــى املدينــة املنــورة وأعــددت دراســة جــدوى‬\n‫للمشــروع كلفتنــي مائــة وســتني ألــف ريــال لــذا أطلــب تعويضــي عــن‬\n‫ذلــك مببلــغ قــدره أربعمائــة وخمســون ألــف ريــال علم ـ ًا أننــي شــريك يف‬\n‫هــذه الشــركة واملديــر التنفيــذي للشــركة بنــاء علــى قــرار مجلــس‬\n‫إدارة الشــركة علمـ ًا أن رئيــس مجلــس اإلدارة مت تعيينــه مبوجــب قــرار‬\n‫مجلــس إدارة الشــركة والغرفــة التجاريــة ليســت شــريكه يف هــذه‬\n‫الشــركة هــذه دعــواي وبعــرض دعــوى املدعــي علــى املدعــى عليــه‬\n‫ا إن الغرفــة التجاريــة مهمتهــا تقــدمي‬‫ممثــل الغرفــة التجاريــة أجــاب قائـ ً‬\n‫اخلدمــات االرشــادية واالستشــارات املتعلقــة بالتجــار والصناعــة وتهيئــة‬\n‫األجــواء لغــرض االســتثمار وقــد تقــدم املدعــي إلــى الغرفــة مبشــروعه‬\n‫الــذي يذكــر وســاهمت الغرفــة يف تقــدمي االرشــادات وكان شــريك ًا‬\n‫لرئيــس جلنــة شــباب األعمــال يف الغرفــة حســب مــا ذكــر وذلــك بصفتــه‬\n‫الشــخصية فتــم عقــد جلنــة بينهــم لتأســيس شــركة تقــوم بالنشــاط الــذي‬\n‫ذكــره ولــم تظهــر الشــركة للوجــود ومهمــة الغرفــة هــي املســاعدة‬\n‫يحمــل‬‫واالشــراف وكونهــم فشــلوا يف االتفــاق فيمــا بينهــم فهــذا ال ّ‬\n‫الغرفــة أي مســؤولية والغرفــة التجاريــة ليســت شــريكه يف املشــروع‬\n‫وال يحــق لهــا نظام ـ ًا ذلــك لــذا فــإن الغرفــة التجاريــة موكلتــي ليســت‬\n‫مســؤولة عــن االضــرار التــي حلقــت بــه هكــذا أجــاب فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واالجابــة ومــا قــرره الطرفــان ونظــر ًا ألنــه اتضــح مــن‬\n\n\n                                                                                      ‫‪18‬‬\n\f     ‫دعــوى املدعــي أن النــزاع الــذي يذكــره هــو نــزاع بــن شــركاء والغرفــة‬\n     ‫التجاريــة ليســت طرف ـ ًا فيــه وليســت شــريكه يف هــذه الشــركة علــى‬\n     ‫فــرض وجودهــا وقــد ظهــر أن القــرار الــذي يدعــى املدعــي تضــرره منــه‬\n     ‫صــادر مــن رئيــس مجلــس إدارة الشــركة املشــار إليهــا وكــون الغرفــة‬\n     ‫التجاريــة حتتضــن هــذا املشــروع وتدعمــه ال يحملهــا مســؤولية اخفاقــه‬\n     ‫يف حــال تقصيرهــا لــذا فقــد حكمــت بــرد دعــوى املدعــي (‪ )......‬املشــار‬\n     ‫إليهــا جتــاه املدعــى عليــه (‪ )......‬وبعــرض احلكــم علــى الطرفــن قــرر‬\n     ‫ممثــل (‪ )......‬قناعتــه باحلكــم أمــا املدعــي فأبــدى عــدم القناعــة وطلــب‬\n     ‫اســتئناف احلكــم بالئحــة فتــم إفهامــه بالتعليمــات املتعلقــة بهــذا الشــأن‬\n     ‫وأن عليــه احلضــور خــال عشــرة أيــام الســتالم صــورة مــن صــك احلكــم‬\n     ‫لالعتــراض عليــه خــال ثالثــن يوم ـ ًا مبضيهــا وعــدم تقــدم اعتراضــه‬\n     ‫يســقط حقــه يف االعتــراض ويكتســب احلكــم القطعيــة‪ ،‬علم ـ ًا أن‬\n     ‫اجللســة املقــررة يف يــوم األحــد املوافــق ‪1433/11/21‬هـ ـ لــم تنعقــد‬\n     ‫اللتحاقــي يف دورة تدريبــة تابعــة لــوزارة العــدل وأغلقــت اجللســة الســاعة‬\n     ‫العاشــرة ‪ ،‬وبــاهلل التوفيــق ‪ ،‬حــرر يف ‪1434/02/20‬ه ـ وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬احلمــد هلل وحــده وبعــد ففــي‬\n     ‫هــذا اليــوم األحــد املوافــق ‪1434/6/18‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫الثانيــة عشــرة والربــع وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n     ‫بخطابهــم رقــم ‪ 341107169‬وتاريــخ ‪1434/5/28‬ه ـ مرفق ـ ًا بهــا قــرار‬\n     ‫املالحظــة رقــم ‪ 34216615‬وتاريــخ ‪1434/5/20‬ه ـ املتضمــن بعــد‬\n     ‫حــذف املقدمــة مــا نصــه» وبدراســة احلكــم وصــورة ضبطــه والئحتــه‬\n     ‫االعتراضيــة تقــرر باألكثريــة إعادتهــا لفضيلتــه ملالحظــة مــا يلــي ‪:‬‬\n     ‫‪ -1‬الدعــوى غيــر محــررة وال بــد مــن حتريرهــا قبــل ضبطهــا علم ـ ًا أن‬\n\n\n‫‪19‬‬\n\f‫فضيلتــه أشــار إلــى أن الدعــوى قــد قدمهــا املدعــي وكذلــك اإلجابــة‬\n‫عنهــا عــن طريــق وســائط الكترونيــة ليتــم تنزليهــا يف الضبــط لكــن‬\n‫فضيلتــه لــم يقــم بذلــك ويعمــل املــادة (‪ )62‬مــن نظــام املرافعــات الشــرعية‬\n‫ولوائحــه التنفيذيــة ‪ -2‬علــى فضيلتــه بعــد حتريــر الدعــوى التأكــد مــن‬\n‫أن القضيــة داخلــة يف اختصاصــه الوالئــي ‪ -3‬االطــاع علــى العقــد‬\n‫بــن الطرفــن وتدويــن مضمونــه يف الضبــط وإجــراء الــازم نحــوه ‪-4‬‬\n‫االطــاع علــى الالئحــة االعتراضيــة ومناقشــة مــا ورد فيهــا بحضــور‬\n‫الطرفــن ال ســيما مــا ذكــره املعتــرض مــن أن لديــه مســتندات رســمية‬\n‫تثبــت صحــة دعــواه وإجــراء املقتضــى الشــرعي نحوهــا ‪ ،‬واهلل املوفــق‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم» أ‪.‬ه ـ وعليــه‬\n‫أجيــب أصحــاب الفضيلــة قضــاة محكمــة االســتئناف حفظهــم اهلل‬\n‫مبــا يلــي ‪ :‬أوالً‪ :‬الدعــوى محــررة وهــي شــفوية ‪ ،‬وكان قــد طلــب مــن‬\n‫الطرفــن إحضارهــا عبــر وســائط الكترونيــة لطولهمــا ‪ ،‬وقــد طلــب‬\n‫ـاء‬\n‫الطرفــان يف اجللســة الثامنــة ســماع الدعــوى واإلجابــة مشــافهة وبنـ ً‬\n‫عليــه مت رصــد الدعــوى واإلجابــة يف اجللســة الثامنــة‪ .‬ثاني ـاً‪ :‬ظهــر لــي‬\n‫أن هــذه الدعــوى مــن اختصــاص احملكمــة العامــة نظــر ًا ألن املدعــى‬\n‫عليهــا ليســت جهــة حكوميــة وإمنــا هــي يف احلقيقــة جمعيــة للتجــار ‪،‬‬\n‫ـاء عليــه فليســت الدعــوى‬   ‫كمــا أن املدعــى عليهــا ليســت شــريكه وبنـ ً‬\n‫بــن شــركاء ‪ .‬ثالثـاً‪ :‬اتضــح مــن دعــوى املدعــي أن االتفــاق مت بينــه وبــن‬\n‫رئيــس جلنــة شــباب األعمــال بالغرفــة ( الشــريك لــه ورئيــس مجلــس إدارة‬\n‫ـاء عليــه‬\n        ‫الشــركة) وأن الغرفــة ليســت شــريكة يف هــذه الشــركة وبنـ ً‬\n‫فــإن هــذه الدعــوى ال تتوجــه علــى املدعــى عليهــا واحلقيقــة أنــه خــاف‬\n‫بــن الشــركاء ومــن ضمنهــم رئيــس مجلــس إدارة الشــركة ويســتطيع‬\n\n\n                                                                                     ‫‪20‬‬\n\f     ‫ـاء‬\n      ‫رفــع دعــواه عليــه إذا كان لــه حــق أمــام احملكمــة املختصــة‪ ،‬وبنـ ً‬\n     ‫عليــه فــا زلــت علــى حكمــي واهلل أعلــم وأحكــم هــذا مــا أجيــب‬\n     ‫بــه أصحــاب الفضيلــة وأمــرت بإحلاقــه ورفعــه حملكمــة االســتئناف ‪،‬‬\n     ‫وأغلقــت اجللســة الســاعة الثانيــة عشــرة والنصــف ‪ ،‬وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/06/18‬ه ـ‬\n     ‫ويف هــذا اليــوم الثالثــاء املوافــق ‪1434/8/16‬ه ـ افتتحــت اجللســة لــدي‬\n     ‫أنــا (‪ )......‬القائــم بعمــل املكتــب القضائــي التاســع عشــر وقــد عــادت‬\n     ‫املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة بخطابهــم رقــم‬\n     ‫‪ 341107169‬وتاريــخ ‪1434/7/19‬ه ـ مرفقـ ًا بــه قــرار الدائــرة احلقوقيــة‬\n     ‫الثانيــة رقــم ‪ 34265623‬وتاريــخ ‪1434/7/11‬ه ـ املظهــر علــى الصــك‬\n     ‫املتضمــن املوافقــة علــى احلكــم لــذا جــرى إحلاقــه بضبطــه وســجله‬\n     ‫وبــاهلل التوفيــق حــرر يف ‪1434/8/16‬ه ـ وصلــى اهلل وســلم علــى نبينــا‬\n                                                   ‫محمــد وعلــى آلــه وصحبــه وســلم‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n     ‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n     ‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن‬\n     ‫فضيلــة رئيــس احملكمــة باملدينــة املنــورة برقــم ‪ 341107169‬وتاريــخ‬\n     ‫‪1434/6/19‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ (‪)......‬‬\n     ‫القاضــي باحملكمــة العامــة باملدينــة املنــورة برقــم ‪ 3443725‬وتاريــخ‬\n     ‫‪1434/2/23‬هـ ‪ ،‬املتضمن دعوى (‪ )......‬ضد (‪ ، )......‬وبدراســة الصك‬\n     ‫وصــورة ضبطــه والئحتــه اإلعتراضيــة تقــرر املوافقــة علــى احلكــم بعــد‬\n     ‫األجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                                                                ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n‫‪21‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":14,"source_page_end":21,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ba984b1c4d2a24f883b855d93101be4a16b092b06c5e5eb65bb0e62bdcbff7b2","normalized_text_hash":"a75b29464337ce7701cb43c14276446110a6aa0c0f2b7f8a3012e66212a598a3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p14-3443725"},{"id":"84a71e57-7466-5784-968c-a84ae12d6de9","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة -عقد -مضاربة -تسليم أموال للمدعى عليها لغرض املتاجرة -ثبوت احتيال املدعى عليها -مطالبة املدعي برد رأس املال واألرباح -مصادقة املدعى عليها على رأس املال دون األرباح- دفع املدعى عليها باملتاجرة واخلسارة وال بينة على اخلسارة -إلزام املدعى عليها برد رأس املال للمدعي .","document_number":"34188973","case_number":"3250477","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبكة املكرمة بقرارها","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/15","year":"1434","subject":"شراكة -عقد -مضاربة -تسليم أموال للمدعى عليها لغرض املتاجرة -ثبوت احتيال املدعى عليها -مطالبة املدعي برد رأس املال واألرباح -مصادقة املدعى عليها على رأس املال دون األرباح- دفع املدعى عليها باملتاجرة واخلسارة وال بينة على اخلسارة -إلزام املدعى عليها برد رأس املال للمدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/15 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34188973 :‬‬\n                    ‫َر ْق ُم الدعوى‪3250477 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34232389‬تاريخه‪1434/6/6 :‬هـ‬\n\n\n‫شــراكة ‪ -‬عقــد ‪ -‬مضاربــة ‪ -‬تســليم أمــوال للمدعــى عليهــا لغــرض‬\n‫املتاجــرة ‪ -‬ثبــوت احتيــال املدعــى عليهــا‪ -‬مطالبــة املدعــي بــرد رأس‬\n‫املــال واألربــاح‪ -‬مصادقــة املدعــى عليهــا علــى رأس املــال دون األربــاح‪-‬‬\n‫دفــع املدعــى عليهــا باملتاجــرة واخلســارة وال بينــة علــى اخلســارة‪ -‬إلــزام‬\n                                  ‫املدعــى عليهــا بــرد رأس املــال للمدعــي ‪.‬‬\n\n\n\n         ‫قوله صلى اهلل عليه وسلم ‪ ( :‬على اليد ما أخذت حتى تؤديه )‬\n\n\n\n\n‫ذكــر وكيــل املدعــي شــرح ًا لدعــواه أن موكلــه قــام بتســليم مبلــغ‬\n‫للمدعــى عليهــا لغــرض املتاجــرة فيــه وســلمته إيصــا ًال بذلــك يتضمــن‬\n‫أنهــا مرابحــة يف األســهم‪ ،‬تبــن للمدعــي أن املدعــى عليهــا قــد حكــم‬\n‫عليهــا يف قضيــة احتيــال لقيامهــا بجمــع األمــوال والنصــب واالحتيــال‬\n‫علــى النــاس لذلــك طلــب إلــزام املدعــى عليها بــرد املبلغ املســلم واألرباح‪،‬‬\n‫صادقــت املدعــى عليهــا علــى دعــوى املدعــي فيمــا يتعلــق باملبلــغ املســلم‬\n‫لهــا والثابــت مبوجــب شــيك دون غيــره ألنهــا تاجــرت وخســرت مــن جتــارة‬\n‫األســهم وال بينــة لهــا علــى اخلســارة‪ ،‬لــذا حكمــت احملكمــة بإلــزام‬\n‫املدعــى عليهــا بــرد املبلــغ للمدعــي‪ ،‬قــرر املدعــي القناعــة وقــررت‬\n\n                                                                                    ‫‪22‬‬\n\f     ‫املدعــى عليهــا االعتــراض علــى احلكــم بالئحــة اعتراضيــة‪ -‬متــت‬\n                             ‫مصادقــة احلكــم مــن محكمــة اإلســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا‪ ........‬القاضــي باحملكمــة اجلزائيــة‬\n     ‫باملدينــة القاضــي اخللــف لفضيلــة القاضــي الشــيخ مبوجــب قــرار‬\n     ‫النقــل رقــم (‪ )33/18/2085‬يف ‪1433/4/17‬ه ـ الصــادر مــن املجلــس‬\n     ‫األعلــى للقضــاء ‪ ،‬وقــد عــادت املعاملــة مــن احملكمــة العليــا برقــم‬\n     ‫‪ 34169721‬وتاريــخ ‪1434/1/25‬ه ـ رفقهــا القــرار رقــم ‪/400‬ش‬\n     ‫وتاريــخ ‪1434/1/25‬ه ـ املتضمــن اإلذن باســتمرار ســماع الدعــوى بعــد‬\n     ‫شــطبها للمــرة الثانيــة وتنبيــه املدعــي بعــدم تكــرار غيابــه ورصــد ذلــك‬\n     ‫يف ضبــط القضيــة‪ .‬ويف يــوم االثنــن املوافــق ‪1434/3/23‬ه ـ افتتحــت‬\n     ‫اجللســة يف متــام الســاعة احلاديــة عشــر صباحــا وفيهــا حضــر ســعودي‬\n     ‫اجلنســية بالســجل املدنــي رقــم (‪ )........‬الوكيــل الشــرعي عــن املدعــي‬\n     ‫‪ ........ /‬مبوجــب الوكالــة رقــم ‪ 45909‬يف ‪1431/7/23‬ه ـ اجللــد ‪6440‬‬\n     ‫الصــادرة مــن كتابــة عــدل املدينــة املنــورة الثانيــة وجــرى تنبيهــه بعــدم‬\n     ‫تكــرار غيابــه وحضــر حلضــوره املدعــى عليهــا ســعودية بالســجل املدنــي‬\n     ‫رقــم وادعــى وكيــل املدعــي قائــا إن ملوكلــي يف ذمــة احلاضــرة معــي‬\n     ‫يف املجلــس الشــرعي مبلــغ وقــدرة مليــون وخمســة وثمانــون الــف ريــال‬\n     ‫ســلمها للمدعــى عليهــا لغــرض املتاجــرة فيهــا وقــد اســتلمت املدعــى‬\n     ‫عليهــا املبلــغ وســلمتنا إيصــاال يتضمــن أنهــا مرابحــة يف األســهم تــرد‬\n     ‫بعــد طلبهــا بشــهر واحــد ‪ ،‬اإليصــال األول بســند قبــض برقــم ‪4591‬‬\n     ‫مببلــغ خمســة عشــر الــف ريــال وإيصــاال آخــر يتضمــن أنهــا قــرض‬\n\n‫‪23‬‬\n\f‫حســن ورده عنــد الطلــب بســند قبــض برقــم ‪ 5456‬مببلــغ ثمامنائــة الــف‬\n‫ريــال ويوجــد شــيك برقــم ‪ 152‬بتاريــخ ‪1429/7/17‬ه ـ املســحوب‬\n‫علــى البنــك االهلــي التجــاري مببلــغ مئتــان وثمانــن الــف وجميعهــا‬\n‫بتوقيــع املدعــى عليهــا ومكتوبــة بخــط يدهــا ثــم تبــن لنــا بعــد ذلــك‬\n‫أنهــا قامــت بجمــع األمــوال والنصــب واالحتيــال علــى النــاس وقــد صــدر‬\n‫حكــم قضائــي علــى املدعــى عليهــا مــن قبــل فضيلــة القاضــي الشــيخ‬\n‫للحــق العــام يف قضيــة احتيالهــا مــن خــال جمعهــا أمــوال النــاس بغــرض‬\n‫توظيفهــا بالقــرار الشــرعي رقــم ‪ 8/69‬يف ‪ 1432/5/14‬واملؤيــد مــن‬\n‫محكمــة االســتئناف مبكــة املكرمــة بقرارهــا رقــم ‪ 2/2/300‬املــؤرخ‬\n‫يف ‪1432/4/28‬ه ـ يف مبالــغ ماليــة هــذا وقــد طلــب موكلــي مــن املدعــى‬\n‫املســلم لهــا لكنهــا امتنعــت والمتناعهــا عــن الدفــع أطلب‬    ‫عليهــا رد املبلــغ َ‬\n‫احلكــم عليهــا بدفــع مــا بذمتهــا ملوكلــي وهــو مبلــغ وقــدره مليــون‬\n‫وخمســة وثمانــون ألــف ريــال هــذه دعــواي وبســؤال املدعــى عليهــا عــن‬\n‫دعــوى املدعــي وكالــة أجابــت املدعــى عليهــا بقولهــا مــا ذكــره املدعــي‬\n‫وكالــة مــن اســتالمي مــن موكلــه املبلــغ الــذي ذكــر غيــر صحيــح‬\n‫والصحيــح أننــي تاجــرت مببلــغ مالــي ســلمه لــي وال أذكــر مقــداره يف‬\n‫جتــارة تــداول األســهم وخســرت وال بينــة لــي علــى ذلــك أطلــب إحضــار‬\n‫املدعــي أصالــة إليضــاح مبلغــه الــذي ســلمه لــي و أمــا بالنســبة للســندات‬\n‫والشــيك املرصــود أرقامهــا بدعــوى املدعــي وكالــة فهــي بخــط يــدي وال‬\n‫أنكرهــا ولكنــي خســرت يف جتــارة األســهم وال بينــة لــي علــى اخلســارة‬\n‫هكــذا أجابــت عليــه فقــد قــررت رفــع اجللســة إلحضــار املدعــي أصالــة‬\n‫ويف جلســة أخرى افتتحت يف يوم األحد املوافق ‪1434/4/14‬هـ يف متام‬\n‫الســاعة الثانيــة ظهــر ًا بنــاء علــى قــرار وزيــر العــدل املوافقــة علــى العمــل‬\n\n\n                                                                                          ‫‪24‬‬\n\f     ‫خــارج وقــت الــدوام الرســمي برقــم (‪ )2982‬وتاريــخ ‪1434/2/18‬ه ـ‬\n     ‫وفيهــا حضــر املدعــي أصالــة ســعودي اجلنســية مبوجــب هويــة وطنيــة‬\n     ‫رقــم (‪ )........‬وحضــر حلضــوره املدعــى عليهــا ســعودية مبوجــب هويــة‬\n     ‫وطنيــة رقــم (‪ )........‬وبســؤال املدعــي أصالــة عــن إيضــاح للمبلــغ املســلم‬\n     ‫للمدعــى عليهــا حقيقــة فأجــاب بقولــه املبلــغ املســلم للمدعــى عليهــا هــو‬\n     ‫املبلــغ املرصــود بالشــيك املشــار إليــه يف اجللســة الســابقة التــي حضرهــا‬\n     ‫وكيلــي الشــرعي وهــو مبلــغ مائتــان وثمانــون ألــف ريــال فقــط وأما باقي‬\n     ‫املبلــغ املرصــود بســندات القبــض والــذي قــدره ثمامنائــة وخمســة عشــر‬\n     ‫ألــف ريــال فهــو وعــد مــن املدعــى عليهــا كأربــاح للمبلــغ املســلم لهــا‬\n     ‫والــذي قدره ـ مائتــان وثمانــون ألــف ريــال وتكــون مــن نصيبــي هكــذا‬\n     ‫أجــاب وبعــرض ذلــك علــى املدعــى عليهــا قالــت مــا ذكــره املدعــي مــن‬\n     ‫أننــي ســلمته الشــيك املشــار إليــه بالدعــوى واملرصــود فيــه مبلــغ مائتــان‬\n     ‫وثمانــون ألــف ريــال فهــذا صحيــح ولكننــي ســلمته لــه مقابــل حفــظ‬\n     ‫حقــه يف املســاهمة باملبلــغ احلقيقــي الــذي ســلمه لــي وال اذكــره مقــداره‬\n     ‫حاليــا فهــذا الشــيك يحتــوي مبلــغ املســاهمة الــذي ســلمه لــي للمتاجرة به‬\n     ‫ومبلــغ األربــاح التــي كنــت ســأعطيها لــه لــو ربحــت بالتجــارة ولكننــي‬\n     ‫خســرت وال بينــة لــي علــى اخلســارة هكــذا أجابــت لــذا وبنــاء علــى مــا‬\n     ‫تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــي أصالــة أنــه لــم يســلم‬\n     ‫املدعــى عليهــا ســوى مبلــغ مائتــان وثمانــون ألــف ريــال مبوجــب الشــيك‬\n     ‫املشــار إليــه بالدعــوى وحيــث صادقــت املدعــى عليهــا علــى صــدور‬\n     ‫هــذا الشــيك مــن قبلهــا إال أنهــا ادعــت اخلســارة وال بينــة لهــا علــى ذلــك‬\n     ‫وباالطــاع علــى الصــك املشــار إليــه رقــم ‪ 8/69‬وتاريــخ ‪1431/5/14‬ه ـ‬\n     ‫واملصــدق مــن محكمــة االســتئناف مبكــة املكرمــة واملتضمــن إثبــات‬\n\n\n‫‪25‬‬\n\f‫ناظــر القضيــة إدانــة املدعــى عليهــا باالحتيــال علــى بعــض املواطنــن مــن‬\n‫خــال توظيــف أموالهــم لتداولهــا بســوق األســهم ودفــع عمــوالت وأربــاح‬\n‫وهميــة لهــم حلملهــم علــى إيــداع أموالهــم لديهــا بــدون ترخيــص والتســبب‬\n‫يف ضياعهــا وتبديدهــا بــدون وجــه حــق ‪ ،‬فنظــر َا إلــى مــا دون ونظــر َا‬\n‫ملصادقــة املدعــى عليهــا علــى اســتالمها للمبلــغ املدعــى بــه مــن املدعيــة‬\n‫أصالــة لقصــد املتاجــرة ولعــدم وجــود بينــة لهــا علــى مــا دفعــت بــه مــن‬\n‫اخلســارة ونظــرا ملــا جــاء يف القــرار الشــرعي رقــم ‪ 8/69‬واملؤيــد مــن‬\n‫محكمــة االســتئناف بثبــوت إدانتهــا بالنصــب واالحتيــال وخروجهــا‬\n‫عــن قصــد املتاجــرة وهــذا يجعلهــا ضامنــة للمبلــغ ولقــول النبــي صلــى‬\n‫اهلل عليــه وســلم ( علــى اليــد مــا أخــذت حتــى تؤديــه ) وعليــه فقــد‬\n‫حكمــت علــى املدعــى عليهــا بدفــع مبلــغ مائتــن وثمانــن ألــف ريــال‬\n‫للمدعــي وبعــرض احلكــم علــى طــريف الدعــوى قــرر املدعــي القناعــة‬\n‫باحلكــم وقــررت املدعــى عليهــا عــدم القناعــة باحلكــم واســتعدت‬\n‫بتقــدمي الئحــة اعتراضيــة فأفهمتهــا باملــدة النظاميــة وان عليهــا تقــدمي‬\n‫الالئحــة االعتراضيــة خــال ثالثــن يومــا مــن تاريــخ اســتالمها لصــورة‬\n‫مــن صــك احلكــم وإال فيعتبــر احلكــم مكتســب القطعيــة ففهمــت ذلــك‬\n‫واســتعدت بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                               ‫وصحبــه أجمعــن ‪ .‬حــرر يف ‪1434/04/14‬هــ‪.‬‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪:‬ـ فقــد‬\n‫جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 32877919‬وتاريــخ‬\n‫‪1434/05/22‬ه ـ املرفــق بهــا الصــك الصادر من فضيلة الشــيخ القاضي‬\n\n\n                                                                                    ‫‪26‬‬\n\f     ‫باحملكمــة اجلزائيــة باملدينــة املنــورة املســجل برقــم ‪ 34188973‬وتاريــخ‬\n     ‫‪1434/04/15‬ه ـ املتضمــن دعــوى ضــد ‪ ،‬وبدراســة الصــك وص ــورة‬\n     ‫ضبطـه والئحته االعتراضية تقـررت املوافقـة علـى احلكم واهلل املوفق‪.‬‬\n                    ‫وصلـى اهلل علـى نبينا محمد وعلـى آلـه وصحبـه وسلم ‪.‬‬\n\n\n\n\n‫‪27‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":22,"source_page_end":27,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"75589ed67c4712ab76bcd23d75148ff908fa487cc0951d0be690786d89c187ca","normalized_text_hash":"b98b4c2667be0d8d56a6aab5cce479b3ebe63b3d9daafd15c3cf4fe4eaf7a788","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p22-34188973"},{"id":"4fd2442c-632d-5295-89e7-1d19f3e00f69","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة يف فتح مطعم -حوالة -املطالبة برأس املال مع األرباح -إذا صحت احلوالة برئ احمليل من الدين سواء أمكن استيفاء احلق أو تعذر-اعتماد الترجمة يف الترافع حال كون أحد االطراف أجنبي ا -احلكم بصرف النظر عن دعوى املدعي.","document_number":"3427257","case_number":"3313727","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/2","year":"1434","subject":"شراكة يف فتح مطعم -حوالة -املطالبة برأس املال مع األرباح -إذا صحت احلوالة برئ احمليل من الدين سواء أمكن استيفاء احلق أو تعذر-اعتماد الترجمة يف الترافع حال كون أحد االطراف أجنبي ا -احلكم بصرف النظر عن دعوى املدعي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/2/2 :‬هـ َر ْق ُم‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪3427257 :‬‬\n                              ‫الدعوى‪3313727 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 34564058‬تاريخه‪1434/3/7:‬هـ‬\n\n\n ‫شــراكة يف فتــح مطعــم ‪ -‬حوالــة ‪ -‬املطالبــة بــرأس املــال مــع األربــاح‬\n ‫‪ -‬إذا صحــت احلوالــة بــرئ احمليــل مــن الديــن ســواء أمكــن اســتيفاء‬\n ‫احلــق أو تعذر‪-‬اعتمــاد الترجمــة يف الترافــع حــال كــون أحــد االطــراف‬\n                       ‫أجنبي ـ ًا ‪ -‬احلكــم بصــرف النظــر عــن دعــوى املدعــي‪.‬‬\n\n\n\n\n ‫‪ -1‬قــال ابــن قدامــه رحمــه اهلل ‪ ( :‬وإذا صحــت احلوالــة بــرئ احمليــل مــن‬\n ‫الديــن ألنــه قــد حتــول مــن ذمتــه فــإن تعــذر االيفــاء مــن احملــال عليــه‬\n ‫ملــوت أو فلــس حــادث أو مطــل لــم يرجــع علــى احمليــل كمــا لــو أبــرأه )‪.‬‬\n                                                         ‫الكافــى(‪.)346-345/2‬‬\n ‫‪ -2‬قــال صاحــب الــروض املربــع (‪ ( : )120-119/5‬وإذا صحــت احلوالــة‬\n ‫نقلــت احلــق إلــى ذمــة احملــال عليــه وبــرئ احمليــل مبجــرد احلوالــة فــا‬\n ‫ميلــك الرجــوع علــى احمليــل بحــال ‪.‬قــال صاحــب احلاشــية ‪ :‬ألن احلــق‬\n ‫انتقــل بذلــك فلــم يعــد احلــق إلــى احمليــل أبــدا ‪ .‬ثــم جــاء يف الــروض‬\n ‫أيض ـ ًا ‪ :‬ســواء أمكــن اســتيفاء احلــق أو تعــذر ملطــل أو فلــس أو مــوت أو‬\n                                                                         ‫غيرهــا ‪).‬‬\n\n\n\n\n                                                                                      ‫‪28‬‬\n\f     ‫ادعــى مقيــم علــى مقيــم آخــر بأنــه ســلم للمدعــى عليــه خمســة وعشــرين‬\n     ‫الــف ريــال بنــاء علــى طلــب املدعــى عليــه مــن أجــل افتتــاح مطعــم ‪ ،‬بعــد‬\n     ‫اســتالم املدعــى عليــه املبلــغ اســتأجر مطعمــا بتاريــخ ‪1431/6/14‬ه ـ‬\n     ‫وأبرمــا عقــدا لتلــك الشــراكة متتــد الــى تاريــخ ‪1433/1/14‬ه ـ ‪ ،‬يف‬\n                                               ‫شــهر رمضــان مــن عــام ‪1432‬ه ـ ‪.‬‬\n     ‫لــم يقــم املدعــى عليــه بدفــع أي ربــح وأخبــر املدعــي أنــه اذا رغــب يف‬\n     ‫اخلــروج مــن تلــك الشــراكة فســوف يعيــد لــه رأس املــال الــذي دفعــه‬\n     ‫باإلضافــة الــى اربــاح قدرهــا اثنــان وعشــرون ألفــا وخمســمائة وثمانيــة‬\n     ‫وعشــرون ريــاال باإلضافــة إلــى مبلــغ قــدره خمســة وعشــرون ألــف ريــال‬\n     ‫نصيــب املدعــى مــن تقديــر املطعــم عنــد تقبيلــه مببلــغ مائتــن وعشــرين‬\n     ‫ألــف ريــال ‪ ،‬كان أقصــى موعــد لتســليم هــذه املبالــغ ‪1432/9/15‬هــ‪،‬‬\n     ‫عنــد حلــول األجــل حــول املدعــى عليــه املدعــي علــى شــخص آخــر‬\n     ‫لكونــه مــن قــام بتقبيــل املطعــم ‪ .‬قابــل املدعــى احملــال عليــه يف أحــد‬\n     ‫املســاجد بتاريــخ ‪1432/9/15‬ه ـ فطلــب هــذا الشــخص (احملــال عليــه)‬\n     ‫مــن املدعــي اثبــات مالــه يف ذمــة املدعــى عليــه ‪ ،‬أبــرز املدعــى ســندا‬\n     ‫بذلــك ‪ .‬قــام احملــال عليــه بتمزيــق هــذا الســند ‪ ، .‬ماطــل احملــال عليــه‬\n     ‫املدعــى يف الســداد ثــم أخبــره أنــه ســيعطيه خمســن ألــف ريــال بعــد‬\n     ‫حــج عــام ‪1433‬ه ـ ‪ ،‬بعــد احلــج ذهــب املدعــي للمحــال عليــه فطلــب منــه‬\n     ‫كتابــة اقــرار باســتالمه ملبلــغ خمســن الــف ريــال والباقــي وقــدره اثنــان‬\n     ‫وعشــرون ألف ـ ًا وخمســمائة وثمانيــة وعشــرون ريــا ًال ســيدفعها احملــال‬\n     ‫عليــه الحق ـ ًا ‪ .‬كتــب املدعــى اقــرار ًا باســتالمه اخلمســن ألــف ريــال‬\n\n‫‪29‬‬\n\f‫وســلم احملــال عليــه للمدعــى شــيكا بخمســة وثالثــن ألــف ريــال فقــط‬\n‫‪ .‬عنــد طلــب صــرف هــذه الشــيك تبــن أنــه بغيــر رصيــد ‪ .‬وكل املدعــي‬\n‫أحــد األشــخاص ملطالبــة احملــال عليــه وســلم املدعــى الشــيك لوكيلــه‬\n‫‪ .‬ذهــب وكيــل املدعــي للمحــال عليــه فاخــذ احملــال عليــه الشــيك وقــام‬\n‫بتقطيعــه وســلم لوكيــل املدعــي قيمتــه خمســة وثالثــن الــف ريــال‬\n‫وهــى اآلن بحــوزة والــد الوكيــل الشــرعي للمدعــي ‪ .‬طلــب املدعــي‬\n‫احلكــم علــى املدعــى عليــه بدفــع املبلــغ كامــا وقــدره اثنــان وســبعون‬\n‫ألف ـ ًا وخمســمائة وثمانيــة وعشــرون ريــا ًال صــادق املدعــى عليــه علــى‬\n‫الشــراكة وأنــه اســتلم مــن املدعــي خمســة وعشــرين الــف ريــا ًال كمــا‬\n‫صــادق املدعــى عليــه علــى أربــاح املدعــي البالــغ قدرهــا اثنــان وعشــرون‬\n‫الفــا وخمســمائة وثمانيــة وعشــرون ريــا ًال دفــع املدعــى عليــه بــأن املدعــي‬\n‫طلــب منــه أن يضيــف لــه علــى رأس املــال واألربــاح مبلغــا قــدره خمســة‬\n‫وعشــرون الــف ريــال مــن قيمــة تقبيــل املطعــم وأن املدعــى عليــه وافــق‬\n‫علــى ذلــك رغــم أن املدعــي ال يســتحقها ‪ .‬قــرر املدعــى عليــه بأنــه ســلم‬\n‫خمســن الــف ريــال للمحــال عليــه مــن أجــل أن يســلمها للمدعــى ‪ .‬قــرر‬\n‫املدعــي بأنــه ذهــب مــع املدعــى عليــه للمحــال عليــه يف احــدى ليالــى شــهر‬\n‫رمضــان عــام ‪1432‬ه ـ وأن احملــال عليــه أعطــى للمدعــى خمســة وثالثــن‬\n‫الــف ريــال مبوجــب شــيك ســأل املدعــى عليــه احملــال عليــه عــن ذلــك‬\n‫فأخبــره احملــال عليــه بأنــه توجــد هنــاك حســابات بينــه وبــن املدعــي‬\n‫وقــرر املدعــى عليــه أنــه ال يعلــم تفاصيــل هــذه احلســابات ‪ .‬ملــا قــرره أهــل‬\n‫العلــم مــن أنــه اذا صحــت احلوالــة بــرئ احمليــل مــن الديــن ســواء أمكــن‬\n‫اســتيفاء احلــق أم تعــذر لــذا صــدر احلكــم بصــرف النظــر عــن دعــوى‬\n‫املدعــى جتــاه املدعــى عليــه ‪ .‬اعتــرض املدعــي علــى احلكــم ‪ .‬صــدق‬\n\n\n                                                                                        ‫‪30‬‬\n\f                                            ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة مبكــة‬\n     ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة مبكــة املكرمــة برقــم ‪ 3313727‬وتاريــخ ‪ 1433/01/04‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 3334336‬وتاريــخ ‪ 1433/01/04‬ه ـ املتعلقــة‬\n     ‫بدعــوى ‪...‬ضــد ‪...‬ففــي هــذا اليــوم الثالثــاء املوافــق ‪1433/04/27‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 11 : 00‬وفيهــا حضــر ‪...‬باكســتاني‬\n     ‫اجلنســية مبوجــب االقامــة رقــم ‪...‬وحضــر حلضــوره املدعــى عليــه املدعــو‬\n     ‫‪...‬باكســتاني اجلنســية مبوجــب االقامــة رقــم ‪...‬ثــم ســألت املدعــي‬\n     ‫عــن دعــواه فأدعــى بواســطة مترجــم احملكمــة ‪...‬قائــا لقــد أعطيــت‬\n     ‫هــذا املدعــى عليــه مبلغــا مــن املــال قــدره خمســة وعشــرين الــف ريــال‬\n     ‫حيــث طلــب منــي ذلــك ألجــل افتتــاح مطعــم يقــع يف حــي ‪ ...‬فمــا كان‬\n     ‫مــن املدعــى عليــه بعــد أن ســلمته ذلــك املبلــغ إال أن أســتأجر مطعمــا‬\n     ‫بتاريــخ ‪1431/6/14‬ه ـ وأبرمنــا عقــدا لتلــك الشــراكة متتــد إلــى تاريــخ‬\n     ‫‪1433/1/14‬ه ـ وقبــل نهايــة عقــد الشــراكة وبالتحديــد قبــل شــهر‬\n     ‫رمضــان مــن عــام ‪1432‬ه ـ لــم يقــم هــذا املدعــى عليــه بدفــع أي ربــح لــي‬\n     ‫منهــا وأخبرنــي بأنــي إن رغبــت يف اخلــروج مــن تلــك الشــراكة فســوف‬\n     ‫يعيــد لــي رأس مالــي الــذي دفعتــه لــه باالضافــة إلــى أربــاح حــدد لــي‬\n     ‫قدرهــا وهــي أثنــان و عشــرون الفـ ًا و خمســمائة و ثمانيــة و عشــرون ريــال‬\n     ‫هــذا إضافــة إلــى موافقتــه علــى أن يدفــع لــي مبلــغ خمســة وعشــرين ألــف‬\n     ‫ريــال والتــي تعــد نصيبــي بعــد أن مت تقديــر املطعــم عنــد تقبيلــه مببلــغ‬\n\n‫‪31‬‬\n\f‫مائتــن وعشــرين ألــف ريــال وكان أقصــي موعــد وعدنــي بتســليمي‬\n‫املــال الــذي يخصنــي هــو يف ‪1432/9/15‬ه ـ فلمــا أتــى موعــد التســليم‬\n‫طالبتــه بــه ولكنــه أحالنــي علــى شــخص يدعــى ‪...‬كــي أتقاضــى حقــي‬\n‫منــه وحــدد لــي مكانــة فســألته عــن ســبب ذلــك فأخبرنــي بأنــه مــن‬\n‫تقبــل املطعــم وبإمكانــي أن آخــذ مالــي منــه فتوجهــت ل‪ ...‬هــذا وقابلتــه‬\n‫يف أحــد املســاجد بتاريــخ ‪1432/9/15‬ه ـ بعــد األفطــار فطلــب منــي أن‬\n‫اثبــت لــه إن كان لــي بالفعــل حــق علــي هــذا املدعــى عليــه فأبــرزت‬\n‫ســندا يثبــت حقــي فلمــا قــام بأخــذه منــي مزقــة أمــام عينــي فتغيظــت مــن‬\n‫صنيعــه ذلــك لكنــه قــال ســأعطيك حقــك الحقــا فأخــذ يف مماطلتــي‬\n‫الــى أن قــال يف وقــت آخــر بأنــه ســيعطيني خمســن ألــف ريــال بعــد حــج‬\n‫عــام ‪1433‬ه ـ فلمــا ذهبــت إليــه يف ذلــك الوقــت طلــب منــي أن أكتــب‬\n‫لــه إقــرار ًا باســتالمي ملبلــغ خمســن ألــف ريــال والباقــي وقــدره أثنــان و‬\n‫عشــرون ألف ريال و خمســمائة وثمانية و عشــرون رياال ســيعطيني إياها‬\n‫يف وقــت آخــر فأخــذ منــي إقــرار ًا بذلك وأعطاني شــيك ًا مصرفي ًا مببلغ‬\n‫خمســة و ثالثــن ألــف ريــال فقــط فلمــا اســتلمته توجهــت لســحب مبلغــه‬\n‫فوجدتــه بغيــر رصيــد وبعــد ذلــك وكلــت أحــد األشــخاص الســعوديني‬\n‫للمرافعــة واملدافعــة وأعطيتــه ذلــك الشــيك فلمــا توجــه بــه إلــى ‪ ...‬الــذي‬\n‫ذكرتــه أخــذ ‪ ...‬الشــيك وقــام بتقطيعــه وســلم للوكيــل الشــرعي قيمتــه‬\n‫البالغــة خمســة و ثالثــن ألــف ريــال وهــي اآلن بحــوزة والــد الوكيــل‬\n‫الشــرعي لــم أســتلمها حتــى اآلن لــذا فإنــي أطلــب احلكــم علــى هــذا‬\n‫احلاضــر بدفــع املبلــغ الكامــل وقــدره اثنــن وســبعني ألــف وخمســمائة‬\n‫وثمانيــة وعشــرين ريــال هــذه دعــواي وأســأله اجلــواب وبعــرض ذلــك علــى‬\n‫ا إن بعــض مــا جــاء‬  ‫املدعــى عليــه أجــاب بواســطة املترجــم املذكــور قائـ ً‬\n\n\n                                                                                     ‫‪32‬‬\n\f     ‫يف دعــوى املدعــي صحيــح وبعضــه غيــر صحيــح فمــا ورد يف دعــواه مــن‬\n     ‫تســليمي مبلــغ خمســة وعشــرين ألــف ريــال ألجــل الشــراكة يف افتتــاح‬\n     ‫مطعــم فصحيــح وال أنكــره يف ذلــك حيــث افتتحــت مطعم ـ ًا واســتمر‬\n     ‫يف العمــل قرابــة ســنة وشــهرين وفــق مــا ذكــره ثــم أراد كفيلــي تقبيلــه‬\n     ‫فعرضــت ذلــك علــى املدعــي وأخبرتــه إن كان يرغــب هــو يف تقبلــه‬\n     ‫فرفــض ذلــك بحجــة قلــة خبرتــه يف ذلــك املجــال فطلــب منــي إعطــاءه‬\n     ‫رأس املــال الــذي دفعــه واملكاســب فوعدتــه بإعطائــه إياهــا حيــث‬\n     ‫ظهــر بــأن مكاســبه بلغــت اثنــن وعشــرين ألــف وخمســمائة وثمانيــة‬\n     ‫وعشــرين ريــا ًال غيــر أنــه طلــب منــي قســر ًا أن أضيــف لــه علــى رأس‬\n     ‫املــال واألربــاح مبلــغ خمســة وعشــرين ألــف ريــال مــن قيمــة تقبيــل املطعــم‬\n     ‫فوافقــت علــى ذلــك علــى الرغــم مــن أنــه ال يســتحقها ثــم ســلمت مبلــغ‬\n     ‫خمســن ألــف ريــال للمدعــو‪... /‬كــي يســلمه لهــذا املدعــي وقــد ذهبــت‬\n     ‫مــع املدعــي يف إحــدى ليالــي شــهر رمضــان عــام ‪1432‬ه ـ إلــى ‪...‬الــذي‬\n     ‫ذكرتــه ولكنــه أعطــاه خمســة وثالثــن ألــف ريــال مبوجــب شــيك ثــم‬\n     ‫ســألت ‪ ...‬عــن ذلــك فأخبرنــي بــأن هنــاك حســابات بينــه وبــن املدعــي ال‬\n     ‫أعلــم تفاصيلهــا هكــذا قــال ويف يــوم الســبت ‪1434/01/17‬ه ـ افتتحت‬\n     ‫اجللســة وفيهــا حضراملتداعيــان وبعــد دراســة مــا تقــدم وإلقــرار املدعــي‬\n     ‫بــأن املدعــى عليــه أحالــه علــى الشــخص الــذي أســماه ‪...‬كــي يتقاضــا‬\n     ‫حقــه منــه ولتوجهــه إليــه وإبــرازه ســند ًا يثبــت حقــه وملــا قالــه أهــل العلــم‬\n     ‫يف هــذا الشــأن حيــث قــال ابــن قدامــه رحمــه اهلل يف الــكايف «وإذا‬\n     ‫صحــت احلوالــة بــرئ احمليــل مــن الديــن ألنــه قــد حتــول مــن ذمتــه فــإن‬\n     ‫تعــذر اإليفــاء مــن احملــال عليــه ملــوت أو فلــس حــادث أو مطــل لــم يرجــع‬\n     ‫علــى احمليــل كمــا لــو أبــرأه» ‪ 346 - 345/2‬وقــال صاحــب الــروض‬\n\n\n‫‪33‬‬\n\f‫املربــع «وإذا صحــت احلوالــة نقلــت احلــق إلــى ذمــة احملــال عليــه وبــرئ‬\n‫احمليــل مبجــرد احلوالــة فــا ميلــك الرجــوع علــى احمليــل بحــال» قــال‬\n‫صاحــب احلاشــية «ألن احلــق إنتقــل بذلــك فلــم يعــد احلــق إلــى احمليــل‬\n‫أبــداً» ثــم جــاء يف الــروض أيض ـ ًا «ســواء أمكــن إســتيفاء احلــق أو تعــذر‬\n‫ملطــل أو فلــس أو مــوت أو غيرهــا» ‪ 120 - 119/5‬بنــاء علــى ذلــك فقــد‬\n‫صرفــت النظــر عــن دعــوى املدعــي ‪ ...‬وأخليــت ســبيل املدعــى عليــه‬\n‫‪...‬ومبــا تقــدم حكمــت وبعرضــه علــى لســان مترجــم احملكمــة ‪...‬قــرر‬\n‫املدعــي اعتراضــه عليــه بينمــا قنــع املدعــى عليــه فجــرى إفهــام املدعــي‬\n‫مبراجعــة احملكمــة خــال عشــرة أيــام الســتالم نســخة احلكــم لتقــدمي‬\n‫اعتراضــه عليــه خــال ثالثــن يوم ـ ًا فــإن لــم يفعــل خاللهــا فــإن حقــه‬\n‫يف االعتــراض يســقط ويكتســب احلكــم القطعيــة فقــرر ذلــك علــى‬\n‫لســان املترجــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                          ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/17‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ثــم عــادت أوراق املعاملــة من محكمة االســتئناف‬\n‫باخلطــاب رقــم ‪ 34515559‬يف ‪1434/3/18‬ه ـ رفقهــا الصــك الشــرعي‬\n‫رقــم ‪ 3427257‬يف ‪1434/2/2‬ه ـ مظهــر ًا عليــه بقــرار الدائــرة احلقوقيــة‬\n‫السادســة مبحكمــة االســتئناف رقــم ‪ 3456405‬يف ‪1434/3/7‬ه ـ‬\n‫املتضمــن أنــه بدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة‬\n‫تقــررت املوافقــة علــى احلكــم قاضــي اســتئناف ختــم وتوقيــع‪ /...‬رئيــس‬\n‫اســتئناف ختــم وتوقيــع ‪ /.../‬رئيــس الدائــرة ختــم وتوقيــع ‪... /‬وصــل اهلل‬\n   ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/4/17‬ه ـ‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ فق ــد ج ــرى‬\n‫م ّنــا نح ــن رئيــس واعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n\n\n                                                                                    ‫‪34‬‬\n\f     ‫االستئناف مبنطقة مك ــة املكرم ــة االطال ُع عل ــى هذا احلكم الصادر‬\n     ‫مــن فضيلــة الشــيخ ‪... /‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‬\n     ‫واملســجل بع ــدد ‪ 3427257‬وتاريــخ ‪1434/2/2‬ه ـ املتضمــن دعــوى ‪...‬‬\n     ‫باكســتاني اجلنســية ضــد ‪ ...‬باكســتاني اجلنســية ‪ ،‬احملكــوم في ــه مبــا‬\n     ‫دون باطنــه ‪ ،‬وبدراس ــة احلكــم وص ــورة ضبط ــه و الئحتــه االعتراضيــة‬\n     ‫تق ــررت املوافق ــة عل ــى احلكــم ‪ ،‬واهلل املوفــق وصل ــى اهلل عل ــى نبينــا‬\n                                               ‫محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪35‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":28,"source_page_end":35,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"130d1f391b2d736ca92782cfbc95a68218986d156c6052aa4abd762f2ec4133c","normalized_text_hash":"af7879563b87747e15fcb86845a20d7be5495f35e84adccaeebcaae352c5996c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p28-3427257"},{"id":"62d3f48b-6e34-531c-a530-e6dd184b94c7","document_type":"judgment","category":"judicial","subcategory":"general","title":"شراكة -عقد مضاربة -مطالبة بكامل رأس املال -عدم إعفاء رب املال للمضارب -ال يحق تصرف الشريك يف مال شريكه من غير علمه -احلكم بالباقي من رأس املال .","document_number":"34167017","case_number":"3341856","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/21","year":"1434","subject":"شراكة -عقد مضاربة -مطالبة بكامل رأس املال -عدم إعفاء رب املال للمضارب -ال يحق تصرف الشريك يف مال شريكه من غير علمه -احلكم بالباقي من رأس املال .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/3/21 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34167017 :‬‬\n                    ‫َر ْق ُم الدعوى‪3341856 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34343932‬تاريخه‪1434/10/28:‬ه‬\n\n\n‫شــراكة ‪ -‬عقــد مضاربــة ‪ -‬مطالبــة بكامــل رأس املــال ‪ -‬عــدم إعفــاء رب‬\n‫املــال للمضــارب ‪ -‬ال يحــق تصــرف الشــريك يف مــال شــريكه مــن غيــر‬\n                                  ‫علمــه ‪ -‬احلكــم بالباقــي مــن رأس املــال ‪.‬‬\n\n\n\n\n‫‪ -1‬قــال ابــن قدامــة يف املغنــي « وليــس لــه أن يشــارك مبــال الشــركة‬\n‫وال يدفعــه مضاربــة ألن ذلــك يثبــت يف املــال حقوقــا ويســتحق ربحــه‬\n                                                ‫لغيــره وليــس لــه ذلــك» ‪.‬‬\n‫‪ -2‬جــاء يف قــرار مجمــع الفقــه اإلســامي الدولــي رقــم (‪ )123‬مــا نصــه‬\n‫[ املضــارب أمــن وال يضمــن مــا يقــع مــن خســارة أو تلــف إال بالتعــدي‬\n                                                              ‫والتقصيــر ] ‪.‬‬\n\n\n\n\n‫دعــوى املدعــي يف كونــه ســلم ملــوكل املدعــى عليــه مبلغــا وقــدره مئتــان‬\n‫وثمانــون ألــف ريــال علــى أن يتاجــر لــه يف البرســيم ويكــون مــن املدعــي‬\n‫املــال ومــن املدعــى عليــه العمــل ولــم يســلمه شــيئا مــن رأس املــال وال‬\n‫األربــاح يطلــب إلزامــه بتســليمه كامــل رأس املــال وقــدره مئتــان وثمانون‬\n‫ألــف ريــال ‪..‬ثــم قصــر دعــواه يف مبلــغ وقــدره مائــة وثمانيــة وتســعون ألــف‬\n‫ريــال‪ ،‬أجــاب املدعــى عليــه بــأن مــا ذكــره املدعــي صحيــح ولكننــي‬\n\n                                                                                      ‫‪36‬‬\n\f               ‫ســلمت مــوكل املدعــي مبلغــا وقــدره اثنــان وثمانــون ألــف ريــال‪.‬‬\n     ‫وقــد ســلمت جميــع املبلــغ لطــرف آخــر وأخبــرت موكلــه بذلــك وأعفانــي‬\n     ‫مــن الباقــي وقــال ســأطالب الطــرف اآلخــر‪ ،‬حضــر املدعــي أصالــة‬\n     ‫وأنكــر إعفــاؤه مــن املبلــغ وأنــه لــم يفوضــه يف تســليم املبلــغ ألي طــرف‬\n     ‫آخــر وبســؤال املدعــى عليــه ألديــك بينــة علــى االعفــاء قــال ال ‪ ،‬قــررت‬\n     ‫احملكمــة إلــزام املدعــى عليــه بســداد مبلــغ وقــدره مائة وثمانية وتســعون‬\n     ‫ألــف ريــال ‪ ،‬اعتــرض املدعــى عليــه علــى احلكــم ‪ ،‬قــررت محكمــة‬\n     ‫االســتئناف إعــادة الدعــوى لتحليــف املدعــي اليمــن بعــدم اإلعفــاء مــن‬\n            ‫املبلــغ‪ ،‬حلــف املدعــي صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......................‬القاضــي يف احملكمــة‬\n     ‫العامــة بتبــوك وبنــاء علــى املعاملــة احملالــة ملكتبنــا مــن فضيلــة‬\n     ‫رئيــس احملكمــة العامــة بتبــوك املكلــف برقــم ‪ 3340556‬وتاريــخ‬\n     ‫‪1433/01/16‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33102542‬وتاريــخ‬\n     ‫‪1433/01/16‬ه ـ ففــي ي ــوم األربع ــاء امل ــوافق ‪1434/01/14‬ه ـ افتتحت‬\n     ‫اجل ـلـس ــة الساعـ ــة ‪ 10 : 30‬وفيهــا حضــر ‪ .....................‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪ ...................‬بصفتــه وكيال عــن ‪..............‬‬\n     ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..................‬مبوجــب‬\n     ‫الوكالــة الصــادرة مــن كتابــة العــدل يف اخلــرج برقــم ‪310508020274‬‬\n     ‫يف ‪1431/6/18‬ه ـ كمــا حضــر ‪ .............‬ســعودي اجلنســية مبوجــب‬\n     ‫السجل املدني رقم ‪ .............‬وادعى األول يف عام ‪1428‬هـ سلم موكلي‬\n     ‫لهــذا احلاضــر مبلغــا وقــدره مئتــان وثمانــون ألــف ريــال علــى أن يتاجــر‬\n\n‫‪37‬‬\n\f‫لــه يف البرســيم ويكــون مــن موكلــي املــال ومــن املدعــى عليــه العمــل‬\n‫وحتــى هــذه الســاعة لــم يســلم موكلــي شــيئا مــن رأس املــال وال األربــاح‬\n‫شــيئا أطلــب إلزامــه بتســليم موكلــي كامــل رأس املــال وقــدره مئتــان‬\n‫وثمانــون ألــف ريــال هــذه دعــواي وبعــرض الدعــوى علــى املدعــي عليــه‬\n‫أجــاب بقولــه مــا ذكــره املدعــي وكالــة صحيــح كلــه جملــة وتفصيــا‬\n‫إال مــا ذكــره مــن أنــي لــم أســلم موكلــه شــيئا مــن رأس املــال فغيــر‬\n‫صحيــح فقــد ســلمته مبلغــا وقــدره اثنــان وثمانــون ألــف ريــال وذلــك أننــي‬\n‫ســلمت كامــل املبلــغ املدعــى بــه لشــخص يدعــى ‪ ..............‬ثــم طلــب منــي‬\n‫املدعــي أصالــة مبلغــا وقــدره اثنــان وثمانــون ألــف فأخذتهــا مــن ‪..............‬‬\n‫وأعطيتهــا املدعــي أصالــة وعليــه يكــون املتبقــي لــه يف ذمتــي قــدره مائــة‬\n‫وثمانيــة وتســعون الــف ريــال ومــع ذلــك فقــد أخبــرت املدعــي أصالــة بــأن‬\n‫املائــة وثمانيــة وتســعني ألــف ريــال مــع ‪ .............‬وملــا ذكــرت لــه ذلــك‬\n‫أعفانــي حينهــا مــن املطالبــة وقــال ســوف أطالــب ‪ ................‬هكــذا‬\n‫أجــاب وبعرضــه علــى املدعــي وكالــة قــال مــا ذكــره املدعــى عليــه‬\n‫مــن أنــه ســلم املبلــغ ل‪ ...............‬فــا علــم لــي بــه وليــس لــي بذلــك أي‬\n‫عالقــة وموكلــي لــم يعــف املدعــى عليــه مــن املطالبــة وأطلــب إمهالــي‬\n‫للرجــوع إلــى موكلــي الســتيضاح األمــر ويف جلســة أخــرى حضر املدعي‬\n‫أصالــة ‪ .......................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ .....................‬كمــا حضــر املدعــي عليــه وبعــرض مــا مت رصــده بعاليــه‬\n‫علــى املدعــي أصالــة قــال مــا ذكــره املدعــى عليــه مــن أنــي اســتلمت منــه‬\n‫مبلغــا وقــدره اثنــان وثمانــون ألــف ريــال وأن املتبقــي عليــه مائــة وثمانيــة‬\n‫وتســعون ألــف ريــال فصحيــح ومــا ذكــره مــن أنــي أعفيتــه عــن املطالبــة‬\n‫ملــا أبلغنــي أنــه ســلم كامــل املبلــغ للمدعــو ‪ .............‬وأنــي ســوف أطالــب‬\n\n\n                                                                                         ‫‪38‬‬\n\f     ‫‪ ................‬مباشــرة فغيــر صحيــح واملدعــى عليــه هــو الــذي فــرط وســلم‬\n     ‫املدعــو ‪ .................‬هــذا املبلــغ وال عالقــة لــي بذلــك فأنــا تعاقــدت مــع‬\n     ‫املدعــى عليــه دون ســواه هكــذا أجــاب وبســؤال املدعــى عليــه هــل أخبــر‬\n     ‫املدعــي أصالــة قبــل تســليم املبلــغ املدعــى بــه إلــى ‪ ....................‬وأنــه أذن‬\n     ‫لــه بهــذا التصــرف فقــال ال فجــرى ســؤال الطرفــن هــل مت إبــرام عقــد‬\n     ‫بينهــم فقــاال نعــم وأبــرزا صــورة مــن العقــد ومت إرفاقــه باملعاملــة وهــذا‬\n     ‫نصــه ‪ ( :‬مت بحمــد اهلل االتفــاق بــن كل مــن الطرفــن الطــرف األول‬\n     ‫‪ .....................‬الطــرف الثانــي ‪ .................‬وذلــك علــى دفــع الطــرف األول‬\n     ‫مبلــغ مــن املــال وقــدره ‪ 280.000‬ريــال للطــرف الثانــي وذلــك لشــراء‬\n     ‫كميــة مــن األعــاف خــال موســم ‪1428‬ه ـ وبيعهــا يف نهايــة املوســم‬\n     ‫علــى أن يكــون الطــرف الثانــي لــه التصــرف املطلــق وعليــه مت التوقيــع‬\n     ‫وعلــى العقــد اســم وتوقيــع املدعــي أصالــة واملدعــى عليه)أ‪.‬ه ـ ولتأمــل‬\n     ‫مــا مت رصــده بعاليــه رفعــت اجللســة ويف جلســة أخــرى حضــر املدعــي‬\n     ‫وكالــة واملدعــى عليــه وبســؤال الطرفــن هــل لديهمــا مــا يضيفانــه‬\n     ‫أجابــا بالنفــي فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر‬\n     ‫املدعــى عليــه بأنــه اســتلم مــن املدعــي أصالــة مبلغــا وقــدره مائتــان‬\n     ‫وثمانــون ألــف ريــال وأنــه ســلم املدعــي مبلغــا وقــدره اثنــان وثمانــون ألــف‬\n     ‫ريــال وحيــث قصــر املدعــي أصالــة مطالبتــه باملبلــغ املتبقــي وقــدره مائــة‬\n     ‫وثمانيــة وتســعون ألــف ريــال وحيــث دفــع املدعــى عليــه بأنــه ســلم املبلــغ‬\n     ‫املدعــى بــه لطــرف ثالــث دون علــم رب املــال وحيــث أن هــذا التصــرف‬\n     ‫ليــس مــن حقــه قــال ابــن قدامــة يف املغنــي ‪( :‬وليــس لــه ـ أي ‪ :‬املضــارب‬\n     ‫ـ أن يشــارك مبــال الشــركة ‪ ،‬وال يدفعــه مضاربــة ؛ ألن ذلــك يثبــت يف‬\n     ‫املــال حقوقــا ‪ ،‬ويســتحق ربحــه لغيــره ‪ ،‬وليــس ذلــك لــه) ‪ ،‬وقــال أيضــا‬\n\n\n‫‪39‬‬\n\f‫‪( :‬وليــس للمضــارب دفــع املــال إلــى آخــر مضاربــة) ‪ ،‬وقــال البهوتــي يف‬\n‫كشــاف القنــاع ‪( :‬فلــو قــال رب املــال‪ :‬عليــك ضمانــه لــم يضمنــه ؛ ألن‬\n‫العقــد يقتضــي كونــه أمانــة غيــر مضمونــة ‪ ،‬مــا لــم يتعــد أو يفــرط)‬\n‫وجــاء يف قــرار مجمــع الفقــه اإلســامي الدولــي رقــم ‪ 123‬مــا نصــه ‪:‬‬\n‫( املضــارب أمــن وال يضمــن مــا يقــع مــن خســارة أو تلــف إال بالتعــدي‬\n‫أو التقصيــر) ‪ ،‬واملدعــى عليــه فــرط يف دفعــه املــال ملضــارب آخــر دون‬\n‫علــم املدعــي لذلــك كلــه فقــد حكمــت علــى املدعــى عليــه ‪..................‬‬\n‫أن يســلم للمدعــي ‪ ..............‬مبلغــا وقــدره مائــة وثمانيــة وتســعون ألــف‬\n‫ريــال ومبــا تقــدم قضيــت وبعرضــه علــى الطرفــن قــرر املدعــي وكالــة‬\n‫القناعــة وقــرر املدعــى عليــه عــدم القناعــة وطلــب االســتئناف واســتعد‬\n‫بتقــدمي الئحــة اعتراضيــة فأجبتــه لطلبــه وجــرى تســليمه نســخة مــن‬\n‫صــك احلكــم لتقــدمي الئحتــه االعتراضيــة خــال املــدة النظاميــة ثالثــن‬\n‫يومــا يســقط بعدهــا حقــه يف االعتــراض ويكتســب احلكــم الصفــة‬\n‫القطعيــة ففهــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                              ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/18‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1434/07/01‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 12 : 00‬وفيهــا أن املعاملــة عــادت مــن محكمة‬\n‫االســتئناف يف تبــوك بخطــاب رئيســها رقــم ‪ 33102542‬وتاريــخ‬\n‫‪1434/5/22‬هـ وبرفقه القرار رقم ‪ 34216577‬وتاريخ ‪1434/5/20‬هـ‬\n‫واملتضمــن بعــد املقدمــة مــا نصــه ‪ ( :‬وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة املقدمــة مــن املدعــى عليــه وأوراق املعاملــة لوحــظ‬\n‫مــا يلــي ‪ -1 :‬لــم ترفــق وكالــة املدعــي أصالــة ولــم يذكــر مضمونهــا يف‬\n‫الصــك والضبــط ‪ -2 .‬لــم يطلــب البينــة مــن املدعــى عليــه علــى مــا دفــع‬\n\n\n                                                                                    ‫‪40‬‬\n\f     ‫بــه مــن أن املدعــى أصالــة أعفــاه مــن املطالبــة وأنــه ســوف يطالــب ‪..........‬‬\n     ‫وقــد ذكــر املدعــى عليــه يف مذكرتــه االعتراضيــة أنــه ال بينــة لديــه‬\n     ‫ويطلــب ميــن املدعــي أصالــة علــى نفــي ذلــك الطــاع فضيلتــه وإكمــال‬\n     ‫مــا يلــزم وإعــادة املعاملــة إلينــا وبــاهلل التوفيــق ) أ‪.‬ه ـ وعلــى القــرار ختــم‬\n     ‫وتوقيــع قضــاة الدائــرة احلقوقيــة األولــى مبحكمــة االســتئناف يف تبــوك‬\n     ‫‪ ....................‬و‪ ..................‬و‪ ..........................‬وأجيــب أصحــاب الفضيلــة‬\n     ‫حفظهــم اهلل مبــا يلــي‪ /1 :‬مــا يتعلــق باملالحظــة األولــى فقــد مت إرفــاق‬\n     ‫صــورة مصدقــة مــن صــك الوكالــة واملدعــي أصالــة ‪ ..................‬قد أقام‬\n     ‫املدعي وكالة ‪ ...................‬وكيال عنه يف املطالبة واملرافعة واملدافعة‬\n     ‫واملخاصمــة وإقامــة الدعــوى ضــد املدعــى عليــه وإنهــاء مــا يلــزم حضــوره‬\n     ‫أمــام احملاكــم الشــرعية والهيئــات القضائيــة وأي جهــة أخــرى وإنهــاء‬\n     ‫كافــة اإلجــراءات املتعلقــة بذلــك ولــه احلــق يف حضــور اجللســات وســماع‬\n     ‫الدعــوى والــرد عليهــا واإلقــرار واإلنــكار وإحضــار البينــات والشــهود‬\n     ‫وطلــب اليمــن وردهــا وقبــول احلكــم واالعتــراض عليــه وطلــب متييــزه‬\n     ‫والطعــن يف البينــات والشــهود وقبولــه ومراجعــة اجلهــات احلكوميــة ذات‬\n     ‫العالقــة بــكل مــا يلــزم والتوقيــع نيابــة عنــه وذلــك مبوجــب الوكالــة‬\n     ‫الصــادرة مــن كتابــة عــدل محافظــة اخلــرج برقــم ‪310508020274‬‬\n     ‫وتاريــخ ‪1431/6/18‬ه ـ ‪ /2 .‬مــا يتعلــق باملالحظــة الثانيــة فقــد حضــر‬\n     ‫الطرفــان وجــرى ســؤال املدعــي عليــه هــل لديــه بينــة علــى أن املدعــي‬\n     ‫أصالــة أعفــاه مــن املطالبــة وأنــه ســوف يطالــب ‪ ...................‬قــال ال‬\n     ‫فجــرى إفهامــه بأنــه لــه ميــن املدعــي أصالــة فقــال إننــي أطلــب ميينــه ‪.‬‬\n     ‫وبنــاء عليــه فقــد جــرى رفــع رفــع اجللســة وتأجيلهــا ويف جلســة أخــرى‬\n     ‫حضــر املدعــي أصالــة ‪ ...................‬ســعودي اجلنســية مبوجــب الســجل‬\n\n\n‫‪41‬‬\n\f‫املدنــي رقــم ‪ ...............‬كمــا حضــر املدعــى عليــه وبســؤال املدعــي‬\n‫أصالــة هــل هــو مســتعد بحلــف اليمــن قــال نعــم فجــرى تخويفــه بعاقبــة‬\n‫اليمــن فقــال إنــي مســتعد باحللــف ثــم حلــف قائــا ‪ ( :‬واهلل العظيــم الــذي‬\n‫ـف هــذا احلاضــر مــن املطالبــة باملبلــغ إطالقــا‬         ‫ال إلــه إال هــو أننــي لــم ُأ ْعـ ِ‬\n‫وأننــي بــاق علــى حقــي) أ‪.‬ه ـ فبنــاء علــى مــا تقــدم وحيــث حلــف املدعــي‬\n‫أصالــة اليمــن املرصــودة بعاليــه فإننــي ال زلــت علــى مــا حكمــت بــه‬\n‫ســابقا وبــه متــت اإلجابــة واالســتجابة علــى مــا حلظــه أصحــاب الفضيلــة‬\n‫وأمــرت بإعــادة كامــل أوراق املعاملــة حملكمــة االســتئناف كاملتبــع‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                  ‫وســلم ‪ .‬حــرر يف ‪1434/08/01‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق ‪ 1434/11/24‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا أن املعاملــة عــادت مــن محكمــة االســتئناف‬\n‫يف تبــوك بخطــاب رئيســها رقــم ‪ 33102542‬وتاريــخ ‪1434/11/10‬ه ـ‬\n‫وبرفقــه القــرار رقــم ‪ 34343932‬وتاريــخ ‪1434/10/28‬ه ـ واملتضمــن‬\n‫بعــد املقدمــة مــا نصــه ‪ ( :‬بنــاء علــى مــا أجــراه فضيلتــه علــى ضــوء‬\n‫قرارنــا رقــم ‪ 34216577‬وتاريــخ ‪1434/5/20‬ه ـ جــرت املصادقــة‬\n‫علــى احلكــم بعــد اإلجــراء األخيــر وبــاهلل التوفيــق) أ‪.‬ه ـ وعلــى القــرار‬\n‫ختــم وتوقيــع قضــاة الدائــرة احلقوقيــة األولــى مبحكمــة االســتئناف يف‬\n‫تبــوك ‪.................‬و‪........................‬و‪ . .............................‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                           ‫‪1434/11/24‬هــ‪.‬‬\n\n\n\n\n                                                                                                       ‫‪42‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":36,"source_page_end":42,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"26db47fbb7cb310bd05e7d19ae980c64c949157c136d1549a38afb3bdaa08c0d","normalized_text_hash":"88c26edc5b3be64e04564a641919c353447be4376a37e7071b3ba69ba1500104","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p36-34167017"},{"id":"0002f70b-8997-54ea-bf41-c86308c2dd67","document_type":"judgment","category":"judicial","subcategory":"general","title":"مشاركة يف عمل -املطالبة بسداد نصيبه من األرباح -رفض املدعى عليه استالم ورقة التبليغ -شهادة الشهود العدول واليمن -تسليم املبلغ احملكوم به -جواز التنازل عن بعض احملكوم به - إلزام املدعى عليه دفع املبلغ املدعى به.","document_number":"3429669","case_number":"3342255","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة يف يوم األربعاء املوافق 1433/2/17ه فتحت اجللسة الساعة يف متام 8","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/4","year":"1434","subject":"مشاركة يف عمل -املطالبة بسداد نصيبه من األرباح -رفض املدعى عليه استالم ورقة التبليغ -شهادة الشهود العدول واليمن -تسليم املبلغ احملكوم به -جواز التنازل عن بعض احملكوم به - إلزام املدعى عليه دفع املبلغ املدعى به.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/2/4 :‬هـ َر ْق ُم‬\n                             ‫ُ‬                ‫َر ْق ُم َّ‬\n                                 ‫الص ِّك‪3429669 :‬‬\n                                   ‫الدعوى‪3342255 :‬‬\n                ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                       ‫‪ 34216863‬تاريخه‪1434/5/20:‬هـ‬\n\n\n      ‫مشــاركة يف عمــل ‪ -‬املطالبــة بســداد نصيبــه مــن األربــاح ‪ -‬رفــض‬\n      ‫املدعــى عليــه اســتالم ورقــة التبليــغ ‪ -‬شــهادة الشــهود العــدول واليمــن‬\n      ‫‪ -‬تســليم املبلــغ احملكــوم بــه ‪ -‬جــواز التنــازل عــن بعــض احملكــوم بــه ‪-‬‬\n                                   ‫إلــزام املدعــى عليــه دفــع املبلــغ املدعــى بــه‪.‬‬\n\n\n\n      ‫‪ -1‬قــال ابــن قدامــة يف املغنــي « وليــس لــه أن يشــارك مبــال الشــركة‬\n      ‫وال يدفعــه مضاربــة ألن ذلــك يثبــت يف املــال حقوقــا ويســتحق ربحــه‬\n                                                      ‫لغيــره وليــس لــه ذلــك» ‪.‬‬\n      ‫‪ -2‬جــاء يف قــرار مجمــع الفقــه اإلســامي الدولــي رقــم (‪ )123‬مــا نصــه‬\n      ‫[ املضــارب أمــن وال يضمــن مــا يقــع مــن خســارة أو تلــف إال بالتعــدي‬\n                                                                        ‫والتقصيــر ] ‪.‬‬\n\n\n\n\n      ‫حضــر املدعــي ولــم يحضــر املدعــى عليــه وأفــاد محضــر اخلصــوم بــأن‬\n      ‫املدعــى عليــه رفــض اســتالم ورقــة التبليــغ‪ ،‬قــررت احملكمــة الســير‬\n      ‫يف نظــر الدعــوى غيابيـاً‪ ،‬ادعــى املدعــي بأنــه اشــترك مــع املدعــى عليــه‬\n      ‫يف عمــل ديكــورات جبســية إلحــدى العمائــر بطلــب مــن املدعــى عليــه‬\n      ‫علــى أن للمدعــي نصــف األربــاح‪ ،‬مت العمــل وجــرت احملاســبة وتبــن أن‬\n\n‫‪43‬‬\n\f‫نصيــب املدعــي مــن األربــاح تســعة وأربعــن ألــف ريــال‪ ،‬طلــب املدعــي‬\n‫إلــزام املدعــى عليــه بدفــع هــذا املبلــغ‪ ،‬أحضــر املدعــي أربعــة شــهود‪،‬‬\n‫ثالثــة شــهود بالعمــل والرابــع باملخالصــة لســبعة أدوار‪ ،‬جــرى ســؤال‬\n‫املدعــي عــن الفــرق يف املبلــغ بــن مــا جــاء يف شــهادة الشــاهد ومــا جــاء‬\n‫يف دعــواه فقــرر أن املبلــغ الــذي ذكــره يف دعــواه يشــمل أجــرة عمــل‬\n‫الــدور الثامــن كام ـاً‪ ،‬جــرى تعديــل الشــهود‪ ،‬طلــب مــن املدعــي‬\n‫اليمــن تكملــة لبينتــه فحلــف اليمــن‪ ،‬جــرى إفهــام املدعــي بــأن لــه‬\n‫ميــن املدعــى عليــه علــى نفــي مــا زاد عــن املبلــغ الــذي شــهد بــه الشــاهد‬\n‫فقــرر أنــه ال يطلــب ميينــه‪ ،‬صــدر احلكــم بإلــزام املدعــى عليــه بدفــع مبلــغ‬\n‫واحــد وأربعــن ألــف ريــال للمدعــي وصــرف النظــر عمــا زاد عــن ذلــك‬\n‫ممــا جــاء يف دعــوى املدعــي‪ ،‬اقتنــع املدعــي باحلكــم‪ ،‬صــدق احلكــم‬\n‫مــن محكمــة االســتئناف‪ ،‬حضــر املدعــي الحقــا وقــرر أنــه اســتلم مــن‬\n‫املدعــى عليــه أربعــن ألــف ريــال وتنــازل عــن ألــف ريــال وبذلــك انتهــت‬\n                                                                         ‫القضيــة‪.‬‬\n\n\n\n\n‫احلمــد هلل رب العاملــن والصــاة والســام علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه أجمعــن وبعــد فبنــاء علــى االســتدعاء الــوارد إلينــا واملقيــد برقم‬\n‫‪ 331073771‬وتاريــخ ‪1433/1/16‬ه ـ واحملــال مــن فضيلة الرئيس برقم‬\n‫‪ 3342255‬لــدي أنــا ‪...‬القاضــي باحملكمــة العامــة مبكــة املكرمــة يف‬\n‫يــوم األربعــاء املوافــق ‪1433/2/17‬ه ـ فتحــت اجللســة الســاعة يف متــام‬\n‫‪ 8.30‬وفيهــا حضــر ‪ ...‬باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة‬\n‫رقــم ‪...‬ثــم يف يــوم األربعــاء املوافــق ‪1433/4/7‬ه ـ فتحــت اجللســة وفيهــا‬\n\n                                                                                       ‫‪44‬‬\n\f     ‫حضــر املدعــي ولــم يحضــر املدعــى عليــه وقــد وردتنــا ورقــة التبليــغ رقــم‬\n     ‫‪ 33330085‬يف ‪1433/2/20‬ه ـ وتتضمــن أنــه مت الوصــول إلــى العنــوان‬\n     ‫املذكــور أعــاه فرفــض املدعــى عليــه اســتالم الطلــب حيــث يقــول ال‬\n     ‫أعتــرف باحملكمــة وال أحضــر يف اجللســة أ‪.‬ه ـ فأذنــت بســماع الدعــوى‬\n     ‫ا إننــي قــد اشــتركت أنــا واملدعــى‬      ‫عليــه غيابي ـ ًا فادعــى املدعــي قائ ـ ً‬\n     ‫عليــه يف عمــل ديكــورات جبســية يف عمــارة ‪...‬بطلــب منــه علــى أن لــي‬\n     ‫نصــف األربــاح التــي تنتــج مــن ذلــك وقــد مت العمــل وجــرت احملاســبة‬\n     ‫بيننــا ومت حســاب املصاريــف وتبــن أن نصيبــي تســعة وأربعــن ألــف‬\n     ‫ريــال فأطلــب إلزامــه بتســليم هــذا املبلــغ هــذه دعــواي فطلبــت منــه البينــة‬\n     ‫علــى ذلــك فقــال أطلــب مهلــة إلحضارهــا فأجبتــه لطلبــه ثــم يف يــوم‬\n     ‫األحــد املوافــق ‪1433/10/22‬ه ـ فتحــت اجللســة وفيهــا حضراملدعــي‬\n     ‫وأحضرللشــهادة كال مــن ‪...‬باكســتاني اجلنســية مبوجــب رخصــة‬\n     ‫االقامــة رقــم ‪...‬و‪ ...‬باكســتاني اجلنســية مبوجــب رخصــة االقامــة رقــم‬\n     ‫‪...‬و‪ ...‬شــاهد ‪ ...‬باكســتاني اجلنســية مبوجــب رخصــة االقامــة رقــم‬\n     ‫‪...‬فشــهد األول بقولــه رايــت هــذا احلاضــر ‪ ...‬عنــد عمــارة يف ‪...‬التــي فيهــا‬\n     ‫األن فنــدق ‪...‬وأخبرنــي ‪ ...‬أن ‪...‬شــريك معــه يف هــذه العمــارة هــذا مــا‬\n     ‫لــدي وبــه أشــهد وشــهد الثانــي بقولــه أنــه حــاول الصلــح بينهمــا وقــد أقــر‬\n     ‫أمامــي بــأن ‪...‬شــريك معــه يف االعمــال اجلبســية ويف عمــارة يف ‪...‬التــي‬\n     ‫فيهــا االن فنــدق ‪...‬وانهمــا اكمــا ســبعة أدوار فطلبــت منــه األوراق‬\n     ‫إلجــراء احملاســبة فاعتــذر بعــدم وجــود االوراق معــه ووعــد بإحضارهــا‬\n     ‫ولــم يفعــل هــذا مــا لــدي وبــه اشــهد وشــهد الثالــث بقولــه رايــت احلاضــر‬\n     ‫هــو و‪ ...‬بإنــزال جبــس مــن شــاحنة الــى عمــارة يف ‪...‬هــذا مــا لــدي وبــه‬\n     ‫أشــهد وبســؤال املدعــي هــل لديــه غيــر مــا أحضــر قــال أطلــب مهلــة‬\n\n\n‫‪45‬‬\n\f‫فأجبتــه لطلبــه ثــم يف يــوم الثالثــاء املوافــق ‪1434/1/6‬ه ـ الســاعة‬\n‫العاشــرة والنصــف صباحـ ًا فتحــت اجللســة وفيهــا حضــر املدعــي وأحضر‬\n‫معــه للشــهادة ‪ ... ...‬باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n‫‪...‬وبســؤال احلاضــر عمــا لديــه قــال إن هــذا احلاضــر ابــن عمــي وقــد كان‬\n‫يعمــل مــع ‪...‬يف عمــارة ‪...‬قــرب كليــة البنــات يعمــان ســوي ًا يف اجلبــس‬\n‫وقــد طلــب منــي هــذا احلاضــر اإلصــاح بينــه وبــن ‪...‬يف تصفيــة احلســاب‬\n‫بينهمــا فاتصلــت علــى ‪...‬وطلبــت منــه احلضــور إلينــا للتفاهــم فحضــر يف‬\n‫عصــر أحــد أيــام اجلمعــة وحصــل نقــاش فأفــاد ‪...‬بأنــه عمــل هــو ‪...‬هــذا‬\n‫احلاضــر ســبعة أدوار وجــزء ًا مــن الثامــن مــن العمــارة التــي يف ‪...‬وأنــه لــه‬\n‫نصــف األجــرة وأنــه قــد قــام بحســاب أجــرة األدوار الســبعة وأنهــا اثنــان‬\n‫وثمانــون ألف ـ ًا ولــم يتــم حســاب أجــرة مــا مت عملــه مــن الــدور الثامــن‬\n‫فقلــت لــه ســلم ‪...‬نصيبــه فقــال إذا اســتلمت املبلــغ مــن صاحــب العمــارة‬\n‫فسأســلم ‪...‬حقــه ثــم بعــد عــدة أســابيع اتصلــت عليــه فقــال ليــس عنــدي‬\n‫لــه إال ألــف ومائــة ريــال ولــن أعطيــه غيرهــا هــذا مــا لــدي وبــه أشــهد‬\n‫فســألت املدعــي هــل لديــه زيــادة بينــة فقــال ليــس لــدي زيــادة فســألته‬\n‫عــن املبلــغ الــذي ذكــره يف دعــواه فقــال إننــي طلبــت تســعة وأربعــن ألفـ ًا‬\n‫منهــا واحــد وأربعــن ألف ـ ًا نصيبــي مــن أجــرة ســبعة أدوار وثمانيــة آالف‬\n                                           ‫هــي نصيبــي مــن عمــل الــدور الثامــن‬\n‫فســألته هــل لديــه بينــة علــى أجــرة الــدور الثامــن فقــال ال فطلبــت منــه‬\n‫ال من ‪ ...‬باكســتاني اجلنســية‬     ‫تعديل شــهوده فاســتعد بذلك وأحضر ك ً‬\n‫مبوجــب رخصــة اإلقامــة رقــم ‪...‬و‪ ...‬باكســتاني اجلنســية مبوجــب رخصة‬\n‫اإلقامــة رقــم ‪...‬فشــهد كل منهمــا بثقــة وعدالــة الشــهود جميعـ ًا ونظــر ًا‬\n‫لعــدم وجــود بينــة للمدعــي علــى املبلــغ الزائــد عمــا شــهد بــه الشــاهد‬\n\n\n                                                                                        ‫‪46‬‬\n\f     ‫األخيــر فقــد أفهمتــه بــأن لــه ميــن املدعــى عليــه علــى نفيــه فقــال ال أريــد‬\n     ‫ميينــه فأفهمتــه بــأن عليــه أداء اليمــن علــى مقــدار املبلــغ الــذي ذكــره‬\n     ‫الشــاهد األخيــر مــع شــهادة الشــاهد الواحــد فاســتعد بذلــك ثــم حلــف‬\n     ‫ا أقســم بــاهلل أن ‪...‬قــد أخبرنــي أن حســاب األدوار الســبعة التــي‬            ‫قائ ـ ً‬\n     ‫عملناهــا اثنــان وثمانــون ألــف ريــال وأن لــي نصفهــا هكــذا حلــف فبنــاء‬\n     ‫علــى مــا تقــدم مــن الدعــوى وشــهادة الشــهود الذيــن أحضرهــم املدعــي‬\n     ‫وألنــه لــم يشــهد منهــم علــى املبلــغ إال شــاهد واحــد وأدى املدعــي اليمــن‬\n     ‫مــع شــهادة هــذا الشــاهد وقــد روى مســلم رحمــه اهلل بســنده عــن ابــن‬\n     ‫عبــاس رضــي اهلل عنهمــا أن النبــي صلــى اهلل عليــه وســلم قضــى بيمــن‬\n     ‫وشــاهد وألن املدعــي قــرر عــدم طلبــه ميــن املدعــى عليــه علــى املبلــغ‬\n     ‫الزائــد عمــا شــهد بــه الشــاهد فقــد ألزمــت املدعــى عليــه بــأن يدفــع‬\n     ‫للمدعــي واحــد ًا وأربعــن ألــف ريــال وصرفــت النظــر عــن الدعــوى عليــه‬\n     ‫مبــا زاد عــن ذلــك وبــه حكمــت وقنــع بــه املدعــي واملدعــى عليــه علــى‬\n     ‫حجتــه متــى حضــر وأمــرت بإصــدار صــك بذلــك وبعــث صورتــه للمدعــى‬\n     ‫عليــه ولــه حــق االعتــراض عليــه خــال ثالثــن يوم ـ ًا مــن تاريــخ تبلغــه‬\n     ‫بــه وإال يســقط حقــه يف االعتــراض ويكتســب احلكــم القطعيــة واهلل‬\n     ‫املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــة أجمعــن‬\n                                                                  ‫حــرر يف ‪1434/1/6‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪...‬ناظــر القضيــة ‪ ...‬يف يــوم األحــد املوافــق‬\n     ‫‪1434/11/23‬ه ـ حضــر ‪...‬وقــرر قائــا إننــي اســتلمت مــن املدعــى عليــه‬\n     ‫‪...‬كامــل املبلــغ احملكــوم بــه يف هــذه الدعــوى وقــدره أربعــون ألــف ريــال‬\n     ‫وإنــي متنــازل عــن األلــف الباقيــة مــن املبلــغ ولــم يبــق يف ذمــة املدعــى عليــه‬\n     ‫أي مبلــغ بخصــوص هــذه الدعــوى هكــذا قــرر وهــو بحالتــه املعتبــرة‬\n\n\n‫‪47‬‬\n\f‫شــرع ًا فبنــاء علــى ذلــك ثبــت لــدي هــذا اإلقــرار وأمــرت بإحلــاق ذلــك علــى‬\n‫الصــك وســجله وبــاهلل التوفيــق وصـ ــلى اهلل وســلم علــى نبينــا محـ ــمد‬\n               ‫وعلى آله وصـ ـ ــحبه أجم ـ ــعني حـ ــرر يف ‪1434 /11 /23‬هـ ‪.‬‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪:‬ـ فقــد‬\n‫جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪33/107371‬‬\n‫وتاريــخ ‪1434/05/04‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ ‪...‬القاضــي باحملكمــة العامــة مبكــة املكرمــة املســجل برقــم‬\n‫‪ 3429669‬وتاريــخ ‪1434/02/04‬ه ـ املتضمــن دعــوى ‪ ...‬باكســتاني‬\n‫اجلنســية ضــد ‪ ،...‬وبدراســة الصــك وص ــورة ضبط ــه تق ــررت املوافق ــة‬\n                          ‫عل ــى احلكــم والغائــب علــى حجتــه واهلل املوفــق‪.‬‬\n                    ‫وصلـى اهلل علـى نبينا محمد وعلـى آلـه وصحبـه وسلم‪.‬‬\n\n\n\n\n                                                                                        ‫‪48‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":43,"source_page_end":48,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7e193325b48956b140c5287c322215bd6baacd5e3fd52b57fc9518b2776545e1","normalized_text_hash":"1282d5669d37f5e178502bf990a8ce24111144bb4040f41b2e5d2195a44cf8b1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p43-3429669"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
